  {"id":"q_ap_2023_ssss_9","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Easy","question":"The structures responsible for production of speech are found in the _______.","options":["Epiglottis","Glottis","Trachea","Larynx","Pharynx"],"correctAnswer":"Glottis","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_10","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Hard","question":"Robert’s mom tells him to chew more carefully, but he continues to inhale his food while eating (literally). Robert eventually enters a violent coughing fit. The food he inhaled has most likely come in contact with which portion of his lung?","options":["A","B","C","D","E"],"correctAnswer":"C","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_11","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"The respiratory epithelium consists of what type of epithelium?","options":["Simple ciliated","Pseudostratified ciliated","Stratified ciliated","Squamous ciliated","More than one of the above"],"correctAnswer":"Pseudostratified ciliated","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_12","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following outlines best traces the path of air entering the body during respiration?","options":["Nose -> pharynx -> larynx -> bronchi","Nose -> larynx -> trachea -> bronchi","Nose -> larynx -> epiglottis -> trachea -> bronchi","Nose -> pharynx -> epiglottis -> bronchi","Nose -> pharynx -> larynx -> trachea -> bronchi"],"correctAnswer":"Nose -> pharynx -> larynx -> trachea -> bronchi","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_13","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"The respiratory membrane is which of the following cells?","options":["Type I alveolar cells","Type II alveolar cells","Macrophages","A and C","All of the above"],"correctAnswer":"All of the above","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_14","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following structures is not found in the left lung?","options":["Superior lobe","Middle lobe","Inferior lobe","Cardiac notch","All of the above may be found on the left lung"],"correctAnswer":"Middle lobe","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_15","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Easy","question":"Deoxygenated blood travels to the alveoli through the:","options":["Pulmonary vein","Pulmonary artery","Aorta","Superior vena cava","Inferior vena cava"],"correctAnswer":"Pulmonary artery","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_16","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Easy","question":"Contraction of the external intercostals and of the diaphragm results in:","options":["Regular inhalation","Regular exhalation","Irregular inhalation","Irregular exhalation","No net movement; these two forces oppose each other"],"correctAnswer":"Regular inhalation","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_17","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Ellie is sprinting in a race. During this time, she is most likely experiencing _______.","options":["Eupnea","Deep breathing","Diaphragmatic breathing","Costal breathing","Hyperpnea"],"correctAnswer":"Hyperpnea","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_18","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Forced expiration requires the contribution of _______ in addition to that of the diaphragm and external intercostals.","options":["Internal intercostals","Muscles of the neck","Accessory abdomen muscles","A and C","All of the above"],"correctAnswer":"Muscles of the neck","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_19","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Pulmonary ventilation is primarily regulated by which neural structure?","options":["Medulla oblongata","Pons","Hypothalamus","Cortex","Aortic body"],"correctAnswer":"Medulla oblongata","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_20","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Respiration is most strongly determined by _______.","options":["Blood oxygen concentration","Blood carbon dioxide concentration","Blood velocity","Blood viscosity","Blood nutrient levels"],"correctAnswer":"Blood carbon dioxide concentration","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_21","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Carbon dioxide transport in the blood occurs primarily via:","options":["Plasma and hemoglobin","Plasma and bicarbonate","Bicarbonate and hemoglobin","Platelets and plasma","Platelets and hemoglobin"],"correctAnswer":"Plasma and bicarbonate","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_22","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Hard","question":"Alex is experiencing abnormally high CO2 levels in their blood. This symptom can be attributed to:","options":["Hyperventilation","Slower than usual metabolism","Hyperglycemia resulting in a reduction of Alex's blood sugar","A deficiency in carbonic anhydrase","Excess bicarbonate"],"correctAnswer":"A deficiency in carbonic anhydrase","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_23","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Hard","question":"A chloride shift describes when bicarbonate bound to erythrocytes is switched for chloride (Cl-) ions. This phenomenon serves what purpose?","options":["Alters the electrical charge of the blood to be more positive","Alters the electrical charge of the blood to be more negative","Maintains chemical equilibrium in the blood","Binds otherwise dangerous chlorine","Transports chlorine throughout the lymphatic system"],"correctAnswer":"Maintains chemical equilibrium in the blood","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_24","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Easy","question":"Pleural fluid is a secretion from the _______ that serves to lubricate the pleurae during breathing.","options":["Type I alveolar cells","Type II alveolar cells","Macrophages","Mesothelial cells","Glial cells"],"correctAnswer":"Mesothelial cells","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_25","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Most blood carbon dioxide is transported by:","options":["Binding to hemoglobin","Binding to myoglobin","Binding to bicarbonate","Dissolution as carbonic acid","Direct dissolution as CO2"],"correctAnswer":"Binding to bicarbonate","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_26","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Easy","question":"True/false: The right lung is shorter and wider than the left lung.","options":["True","False"],"correctAnswer":"True","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_27","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"True/false: Stimulation via the sympathetic nervous system results in bronchoconstriction.","options":["True","False"],"correctAnswer":"False","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_28","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"True/false: Normal expiration does not require energy.","options":["True","False"],"correctAnswer":"True","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_29","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Match the definition to the term: The air remaining in the lungs after a large exhalation, prevents alveolar collapse.","options":["Residual volume","Tidal volume","Expiratory reserve volume","Vital capacity","Functional residual capacity","Inspiratory reserve volume"],"correctAnswer":"Residual volume","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_30","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Match the definition to the term: Amount of air that generally enters the lungs during eupnea (500 mL)","options":["Residual volume","Tidal volume","Expiratory reserve volume","Vital capacity","Functional residual capacity","Inspiratory reserve volume"],"correctAnswer":"Tidal volume","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_31","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Match the definition to the term: Amount of air that can be forcefully exhaled past a normal value (<1200mL)","options":["Residual volume","Tidal volume","Expiratory reserve volume","Vital capacity","Functional residual capacity","Inspiratory reserve volume"],"correctAnswer":"Expiratory reserve volume","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_32","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Match the definition to the term: Consists of inspiratory reserve volume, tidal volume, and expiratory reserve volume","options":["Residual volume","Tidal volume","Expiratory reserve volume","Vital capacity","Functional residual capacity","Inspiratory reserve volume"],"correctAnswer":"Vital capacity","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_33","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Match the definition to the term: Consists of expiratory reserve volume and residual volume.","options":["Residual volume","Tidal volume","Expiratory reserve volume","Vital capacity","Functional residual capacity","Inspiratory reserve volume"],"correctAnswer":"Functional residual capacity","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_34","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Match the definition to the term: Amount of air that can be inhaled past a normal value","options":["Residual volume","Tidal volume","Expiratory reserve volume","Vital capacity","Functional residual capacity","Inspiratory reserve volume"],"correctAnswer":"Inspiratory reserve volume","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_35","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"FRQ","difficulty":"Hard","question":"Identify the two graphs by their names or by the effects which they depict. (Graph A plots CO2 in blood vs PCO2 at different PO2; Graph B plots Hb O2 saturation vs Oxygen pressure at different CO2 levels)","correctAnswer":"(1) graph A: carbon dioxide-hemoglobin dissociation curve (Haldane effect) (2) graph B: oxygen-hemoglobin dissociation curve (Bohr effect)","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_36","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"FRQ","difficulty":"Hard","question":"Using the Haldane effect, explain how hemoglobin’s CO2 affinity changes at the lungs.","correctAnswer":"(1) binding of oxygen in the lungs (increase in partial pressure) (2) results in a decrease of CO2 affinity","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_37","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Does the following effect result in a decrease or increase in hemoglobin oxygen affinity: Diminishing 2,3-BPG concentration.","options":["Increase","Decrease"],"correctAnswer":"Increase","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_38","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Does the following effect result in a decrease or increase in hemoglobin oxygen affinity: Growing tissue H+ concentration.","options":["Increase","Decrease"],"correctAnswer":"Decrease","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_39","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Does the following effect result in a decrease or increase in hemoglobin oxygen affinity: Colder temperatures.","options":["Increase","Decrease"],"correctAnswer":"Increase","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_40","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"MCQ","difficulty":"Medium","question":"Does the following effect result in a decrease or increase in hemoglobin oxygen affinity: Movement from sea-level to mountaintop altitudes.","options":["Increase","Decrease"],"correctAnswer":"Decrease","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_41","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"FRQ","difficulty":"Medium","question":"Given two chest X-rays (A is normal, B is cloudy with mucus), identify which X-ray depicts a disorder and identify the disorder.","correctAnswer":"Scan B depicts Cystic fibrosis","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_42","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe the sodium concentrations of a diseased cell with cystic fibrosis in comparison to a healthy cell.","correctAnswer":"A diseased cell has more sodium","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_43","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"FRQ","difficulty":"Hard","question":"A 56-year-old female patient is admitted after complaining of shortness of breath, sharp chest pain, rales, tachypnea, and 102.1°F fever. History of smoking. Identify the most likely diagnosis.","correctAnswer":"Pneumonia","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_44","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the symptom characterizing the pneumonia patient’s sharp chest pain flare-up on her canoe trip.","correctAnswer":"Pleurisy","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_45","event":"Anatomy & Physiology","subtopic":"Respiratory System","division":"C","type":"FRQ","difficulty":"Hard","question":"A resident doctor suggests administering antibiotics to the pneumonia patient. Is this a viable treatment? Briefly explain.","correctAnswer":"Yes, it is likely that the patient is infected with Streptococcus pneumoniae which is a bacteria. OR No, the patient’s pneumonia may be viral in origin.","year":2023,"tournament":"SSSS"}
,
  {"id":"q_ap_2023_ssss_46","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"The path which food travels through the gastrointestinal tract is best described as:","options":["Pharynx -> esophagus -> stomach -> small intestines -> large intestines","Esophagus -> pharynx -> stomach -> small intestines -> large intestines","Pharynx -> larynx -> esophagus -> large intestines -> small intestines","Larynx -> small intestines -> stomach -> large intestines","Larynx -> stomach -> small intestines -> large intestines"],"correctAnswer":"Pharynx -> esophagus -> stomach -> small intestines -> large intestines","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_47","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Easy","question":"The digestive and respiratory tracts intersect at the:","options":["Larynx","Pharynx","Mouth","Esophagus","Stomach"],"correctAnswer":"Pharynx","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_48","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Easy","question":"All of the following structures are accessory organs of the digestive system except for the:","options":["Teeth","Mouth","Salivary glands","Tongue","Pancreas"],"correctAnswer":"Mouth","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_49","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"Most taste buds of the tongue are located on which structure?","options":["Fungiform papillae","Filiform papillae","Foliate papillae","Vallate papillae","Terminal sulcus"],"correctAnswer":"Fungiform papillae","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_50","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"Sam is a patient presenting with diarrhea caused by issues with peristalsis. This issue is most likely caused by an issue of the:","options":["Submucosal plexus","Myenteric plexus","Dorsal root plexus","Esophageal hiatus","Bile duct"],"correctAnswer":"Myenteric plexus","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_51","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Easy","question":"Chyme production occurs in the _______.","options":["Pharynx","Esophagus","Stomach","Small intestine","Large intestine"],"correctAnswer":"Stomach","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_52","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"The following structures classifications are all correctly matched with their respective epithelia except for:","options":["Oral cavity; stratified squamous","Pharynx; stratified squamous","Esophagus; simple columnar","Small intestine; simple columnar","Large intestine; simple columnar"],"correctAnswer":"Esophagus; simple columnar","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_53","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Easy","question":"The innermost lining of the digestive tract is known as the _______.","options":["Muscularis interna","Serosa","Mucosa","Submucosa","Endothelium"],"correctAnswer":"Mucosa","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_54","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"Sheets of connective tissue known as the mesenteries are directly responsible for _______.","options":["Peristalsis and bowel movements","Digestion and diffusion of nutrients","Anchorage of the intestines to the abdominal wall","Transport of wastes for filtration to the kidneys","Neural impulses in the GI tract"],"correctAnswer":"Anchorage of the intestines to the abdominal wall","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_55","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"Which of the following descriptions is incorrectly paired with its corresponding anatomical structure?","options":["Mucous membrane; secretes mucus and is involved in absorption","Muscularis; smooth muscle that pulls the small intestine into folds to increase its surface area","Lamina propria; house mucosa-associated lymphoid tissue (MALT)","Submucosa; promotes mechanical digestion and moves food along the digestive canal","Serosa; churns the contents of the stomach during digestion"],"correctAnswer":"Serosa; churns the contents of the stomach during digestion","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_56","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"In order from entrance to exit, the primary regions of the stomach are:","options":["Cardia -> fundus -> body -> pylorus","Pylorus -> fundus -> body -> cardia","Fundus -> body -> cardia -> pylorus","Body -> cardia -> fundus -> pylorus","Cardia -> body -> fundus -> pylorus"],"correctAnswer":"Cardia -> fundus -> body -> pylorus","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_57","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"The stomach’s unique functions can be primarily attributed to its _______ layer, which differs in its appearance in the alimentary canal.","options":["Mucous membrane","Muscularis","Lamina propria","Submucosa","Serosa"],"correctAnswer":"Muscularis","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_58","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"These structures of the tongue are responsible for speech production.","options":["Intrinsic muscles","Extrinsic muscles","Lingual tonsils","Vocalis ligament","Vocalis muscle"],"correctAnswer":"Intrinsic muscles","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_59","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Easy","question":"An adult generally has how many teeth total?","options":["22","26","28","32","34"],"correctAnswer":"32","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_60","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Easy","question":"The first teeth to emerge in children are the:","options":["Incisors","Canines","Premolars","Molars","Wisdom teeth"],"correctAnswer":"Incisors","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_61","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Easy","question":"After eating a pack of starchy saltines, this salivary component begins to assist in the breakdown of the saltines before they enter the digestive tract.","options":["Mucus","Electrolytes","Lysozyme","Amylase","Lipase"],"correctAnswer":"Amylase","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_62","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Easy","question":"\"Heartburn\" describes a burning feeling in the chest that results from acid from the stomach entering the ________.","options":["Pharynx","Larynx","Esophagus","Small intestine","Trachea"],"correctAnswer":"Esophagus","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_63","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"Most of dietary fat is digested in the:","options":["Mouth","Esophagus","Stomach","Small intestine","Large intestine"],"correctAnswer":"Small intestine","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_64","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"Teniae coli, bands of longitudinal smooth muscle, are characteristic of what structure?","options":["Esophagus","Small intestine","Pharynx","Large intestine","Colon"],"correctAnswer":"Colon","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_65","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"Relaxation of the upper esophageal sphincter contributes in which action?","options":["Movement of a bolus out of the laryngopharynx","Movement of a bolus out of the stomach","Pushing of a bolus through the esophagus","Lubrication of the esophagus","Peristalsis and mechanical breakdown of foods"],"correctAnswer":"Movement of a bolus out of the laryngopharynx","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_66","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"These gastric gland cells are responsible for the secretion of gastric lipase and pepsinogen.","options":["Mucous cells","Stem cells","Parietal cells","Chief cells","Enteroendocrine cells"],"correctAnswer":"Chief cells","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_67","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"Julian skipped breakfast then went his whole work shift without eating. Levels of the hormone _______ are most likely especially high in his system at this point.","options":["Ghrelin","Leptin","Cholecystokinin","Insulin","Glucagon"],"correctAnswer":"Ghrelin","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_68","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"Without the stomach, a person would most likely suffer from:","options":["Lack of digestion","Lack of vitamin B12 synthesis","Lack of vitamin D absorption","A and B","A and C"],"correctAnswer":"Lack of vitamin B12 synthesis","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_69","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"Which hormone is primarily responsible for gastric motility during digestion?","options":["Gastrin","Cholecystokinin","Secretin","Somatostatin","Glucagon"],"correctAnswer":"Gastrin","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_70","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Easy","question":"What do the liver’s bile salts primarily assist with the digestion of?","options":["Proteins","Fats","Nucleic acids","Vitamins","Electrolytes"],"correctAnswer":"Fats","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_71","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"CO2 + H2O → H2CO3 → HCO3- + H+ The equation describing gastric HCl synthesis is shown above. The first step is catalyzed by an enzyme found in the _______.","options":["Mucous cells","Stem cells","Parietal cells","Chief cells","Enteroendocrine cells"],"correctAnswer":"Parietal cells","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_72","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"True/false: The epithelia of the mouth is nonkeratinized.","options":["True","False"],"correctAnswer":"False","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_73","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"True/false: The enteric nervous system has more neurons than does the central nervous system.","options":["True","False"],"correctAnswer":"True","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_74","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Medium","question":"True/false: Parasympathetic stimulation of salivary glands results in increased secretion.","options":["True","False"],"correctAnswer":"True","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_75","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"Match the function to the term: Anchors the liver in place.","options":["Falciform ligament","Mesentery","Mesocolon","Lesser omentum","Greater omentum"],"correctAnswer":"Falciform ligament","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_76","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"Match the function to the term: A band of tissue that anchors to the small intestine.","options":["Falciform ligament","Mesentery","Mesocolon","Lesser omentum","Greater omentum"],"correctAnswer":"Mesentery","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_77","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"Match the function to the term: Attaches the transverse and sigmoid colon to the posterior abdominal wall.","options":["Falciform ligament","Mesentery","Mesocolon","Lesser omentum","Greater omentum"],"correctAnswer":"Mesocolon","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_78","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"Match the function to the term: Suspends the stomach from the liver.","options":["Falciform ligament","Mesentery","Mesocolon","Lesser omentum","Greater omentum"],"correctAnswer":"Lesser omentum","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_79","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"MCQ","difficulty":"Hard","question":"Match the function to the term: A structure superficial to the small intestine but transverse to the colon where fat is deposited.","options":["Falciform ligament","Mesentery","Mesocolon","Lesser omentum","Greater omentum"],"correctAnswer":"Greater omentum","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_80","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Medium","question":"Blood leaving the stomach after digestion has a _______ pH than the blood which entered.","correctAnswer":"lower","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_81","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Hard","question":"The phenomenon of blood leaving the stomach with a different pH is due to which process? Explain.","correctAnswer":"alkaline tide - CO2 and Cl- exit the bloodstream at parietal cells and are traded for HCO3- which is basic","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_82","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Hard","question":"Identify all the primary subdivisions of the pharynx and briefly describe their functions.","correctAnswer":"nasopharynx (used for breathing/speech), oropharynx and laryngopharynx (used for breathing and digestion)","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_83","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Hard","question":"In which organ does segmentation of digestive contents mainly occur? Briefly explain the process.","correctAnswer":"small intestine - contractions of the muscularis layer of the alimentary canal section the contents, moving them while dividing them, mixing them with digestive juices and promoting absorption","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_84","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Medium","question":"Deglutition apnea describes a brief, temporary cessation of breathing which occurs during swallowing. Which phase of deglutition might this occur during? Briefly justify your answer.","correctAnswer":"the pharyngeal phase - breathing would have to stop briefly here to stop food from entering the trachea","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_85","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Medium","question":"A 76-year old man presents complaining of sharp stomach pains at night. The patient is using aspirin and fluoxetine. Identify the most likely diagnosis for the patient.","correctAnswer":"peptic ulcer","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_86","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Hard","question":"What class of drugs does aspirin belong to, and how does it interfere with standard digestive function?","correctAnswer":"NSAIDs - reduces the production of stomach mucus and blocks enzymes which produce prostaglandins, which also serve to protect the stomach","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_87","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Medium","question":"Aside from medicative causes, a peptic ulcer may also be caused by a pathogen. Identify this pathogen.","correctAnswer":"Helicobacter pylori","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_88","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Medium","question":"A 30 year-old US male presents with jaundice, fever, and fatigue. Lab tests found lowered platelet count, hyperglycemia, and hyperbilirubinemia. Diagnosed with Diabetes Mellitus and another disorder. Discharged with a warning to avoid medications and alcohol usage. Identify the most likely diagnosis (be specific).","correctAnswer":"Hepatitis A","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_89","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the most likely method of transmission of Hepatitis A?","correctAnswer":"Fecal-oral (e.g. through contaminated water in a different country)","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_90","event":"Anatomy & Physiology","subtopic":"Digestive System","division":"C","type":"FRQ","difficulty":"Medium","question":"Briefly justify the warning against medication and alcohol usage given to the patient with Hepatitis A.","correctAnswer":"the liver needs to heal and may have problems processing certain medications and alcohol","year":2023,"tournament":"SSSS"}
,
  {"id":"q_ap_2023_ssss_91","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"The acid mantle of the skin is consisted of:","options":["Fatty acids","Proteins","Defensins","A and B","A and C"],"correctAnswer":"Fatty acids","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_92","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"Some bacteria excrete toxins containing an enzyme which breaks down glycosaminoglycans in areolar tissue below the skin, facilitating their movement into connective tissues. What molecule is most likely being targeted by the bacteria in these scenarios?","options":["Lysozyme","Dermcidin","Cathelicidins","Hyaluronic acid","Keratin"],"correctAnswer":"Hyaluronic acid","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_93","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"These wandering leukocytes engage in an activity known as a respiratory burst, involving rapid formation of hydrogen peroxide and hypochlorite to form a chemical killing zone which enhances the destruction of nearby bacteria. This behavior is most characteristic of _______.","options":["Eosinophils","Neutrophils","Basophils","Lymphocytes","Macrophages"],"correctAnswer":"Neutrophils","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_94","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"_______ secrete chemicals such as leukotrienes and heparin which mobilize and modulate the activity of other leukocytes.","options":["Neutrophils","Macrophages","Basophils","Eosinophils","Lymphocytes"],"correctAnswer":"Basophils","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_95","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Hard","question":"All of the following cells are derived from myeloid stem cells except for:","options":["Megakaryocytes","Erythrocytes","Basophils","Monocytes","All of the above are derived from myeloid stem cells"],"correctAnswer":"All of the above are derived from myeloid stem cells","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_96","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"Secretion of chemical messengers such as Ca2+ is associated with the primary task of:","options":["B cells","T cells","Plasma cells","Natural killer cells","A and B"],"correctAnswer":"T cells","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_97","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Hard","question":"In comparison to B and T cells, plasma cells have an especially expansive:","options":["Cytoplasm","Mitochondria","Vacuoles","Rough ER","Smooth ER"],"correctAnswer":"Rough ER","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_98","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"This oral enzyme aids in the destruction of foreign bacteria.","options":["Bromelain","Pepsin","Lysozyme","Amylase","Lipase"],"correctAnswer":"Lysozyme","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_99","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"Phagocytosis is a function of which of the following cells?","options":["T cells","B cells","Plasma cells","Megakaryocytes","Neutrophils"],"correctAnswer":"Neutrophils","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_100","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Hard","question":"Kupffer cells are phagocytic cells in the liver which break down gut bacteria, endotoxins, and other debris in the GI tract. Based on this description, what types of cells are Kupffer cells most likely categorized as?","options":["Macrophages","Eosinophils","Neutrophils","Dendritic cells","Monocytes"],"correctAnswer":"Macrophages","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_101","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"Plasma cell maturation primarily occurs in the _____.","options":["Lymph nodes","Thymus","Bone marrow","Liver","Bloodstream"],"correctAnswer":"Lymph nodes","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_102","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Hard","question":"Shown below are steps of the classical pathway of the complement system. Select the option which best categorizes the descriptions into chronological order.\nI. Complement-binding sites are exposed.\nII. Complement C1 binds to complement-binding sites.\nIII. An antibody binds to an antigen on the surface of a microbe.\nIV. A reaction cascade is created.","options":["I -> II -> III -> IV","I -> III -> IV -> II","III -> I -> II -> IV","III -> IV -> II -> I","III -> IV -> I -> II"],"correctAnswer":"III -> I -> II -> IV","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_103","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Hard","question":"All the pathways of the complement system have this step in common.","options":["Binding of lectin to a pathogenic surface","Binding of C3b to a pathogenic surface","Binding of an antibody to a pathogenic surface","Dissociation of C3 into C3a and C3b","Creation of antibody-binding sites on the host cell"],"correctAnswer":"Dissociation of C3 into C3a and C3b","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_104","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"Perforins, a protein that creates holes in target cell plasma membranes, are a common secretion of what immune cell?","options":["Natural killer cells","Monocytes","Macrophages","Erythrocytes","Dendritic cells"],"correctAnswer":"Natural killer cells","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_105","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"During the _______ stage of fever, the infected person’s internal temperature adjusts to and oscillates around a higher-than-usual set point.","options":["Onset","Stadium","Stabilization","Equilibrium","Defervescence"],"correctAnswer":"Stadium","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_106","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"The SARS-CoV-2 vaccine and its effects best fall under the umbrella of:","options":["Natural active immunity","Artificial active immunity","Natural passive immunity","Artificial passive immunity","Neutral immunity"],"correctAnswer":"Artificial active immunity","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_107","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"The most common class of antibody in blood plasma, _______ also contributes to fetal immunity due to its ease of transfer across the placenta.","options":["IgA","IgD","IgE","IgG","IgM"],"correctAnswer":"IgG","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_108","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Hard","question":"Immediately after a pathogenic infection subsides, one would expect elevated activity from the _______ class of T cells.","options":["TC","TH","TR","TM","None of the above; T cell activity should drop"],"correctAnswer":"TR","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_109","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"Helper T cells bind to other cells with _______ on their surface.","options":["MHC-II proteins","Antigens","Antibodies","Complements","CD8 receptors"],"correctAnswer":"MHC-II proteins","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_110","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"Simon comes down with a bad case of a viral infection. Upon being infected a second time, an antibody survey would find that his body has mainly produced _______.","options":["IgA","IgD","IgE","IgG","IgM"],"correctAnswer":"IgG","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_111","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"Allergies and parasites are primarily mediated by activity of:","options":["IgA","IgD","IgG","IgE","IgM"],"correctAnswer":"IgE","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_112","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"All of the following molecules are secreted by cytotoxic T cells except for:","options":["Perforins","Granzymes","Interferons","Tumor necrosis factor","Haptens"],"correctAnswer":"Haptens","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_113","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Hard","question":"One of William's asthma episodes typically lasts just a few minutes, but he keeps his inhaler on him at all times to mitigate his coughing. William's asthma is an example of _______ hypersensitivity.","options":["Type I","Type II","Type III","Type IV","Type V"],"correctAnswer":"Type I","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_114","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"A blood transfusion of incompatible blood types can result in _______, where erythrocytes clump up and become dysfunctional.","options":["Complement fixation","Neutralization","Agglutination","Precipitation","Pinocytosis"],"correctAnswer":"Agglutination","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_115","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"Someone with type AB blood most likely has:","options":["Both A and B antigens","No antigens","Both A and B antibodies","No antibodies","A and D"],"correctAnswer":"Both A and B antigens","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_116","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"True/false: B cells mature in red bone marrow and T cells mature in the thymus.","options":["True","False"],"correctAnswer":"True","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_117","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"True/false: Interferons are common bacterial secretions which halt phagocytic activity.","options":["True","False"],"correctAnswer":"False","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_118","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"True/false: Hemolytic disease of the newborn occurs when an Rh positive mother is exposed to a child’s Rh negative RBCs.","options":["True","False"],"correctAnswer":"True","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_119","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"True/false: Class I MHC markers are displayed on RBCs, B-cells, and T-cells.","options":["True","False"],"correctAnswer":"True","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_120","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"True/false: Neutrophils are the most numerous WBC.","options":["True","False"],"correctAnswer":"True","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_121","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"Sort the following into innate (I), adaptive (A) immunity, or both (IA): The skin.","options":["I","A","IA"],"correctAnswer":"I","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_122","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"Sort the following into innate (I), adaptive (A) immunity, or both (IA): Inflammation.","options":["I","A","IA"],"correctAnswer":"I","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_123","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"Sort the following into innate (I), adaptive (A) immunity, or both (IA): The classical pathway of the complement system.","options":["I","A","IA"],"correctAnswer":"A","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_124","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Medium","question":"Sort the following into innate (I), adaptive (A) immunity, or both (IA): The lectin pathway of the complement system.","options":["I","A","IA"],"correctAnswer":"I","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_125","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"MCQ","difficulty":"Easy","question":"Sort the following into innate (I), adaptive (A) immunity, or both (IA): Helper T cells.","options":["I","A","IA"],"correctAnswer":"IA","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_126","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Hard","question":"Fill in the Venn diagram for Humoral Immunity, Both, and Cell-Mediated Immunity. Which descriptions belong in Humoral Immunity only? Options: A. Activated by free antigens, B. Defends against intracellular pathogens, C. Defends against cancer, D. Involves B cells, E. Involves cytotoxic T cells, F. Involves helper T cells, G. Involves antigens.","correctAnswer":"A, D","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_127","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Hard","question":"Fill in the Venn diagram for Humoral Immunity, Both, and Cell-Mediated Immunity. Which descriptions belong in Both? Options: A. Activated by free antigens, B. Defends against intracellular pathogens, C. Defends against cancer, D. Involves B cells, E. Involves cytotoxic T cells, F. Involves helper T cells, G. Involves antigens.","correctAnswer":"F, G","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_128","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Hard","question":"Fill in the Venn diagram for Humoral Immunity, Both, and Cell-Mediated Immunity. Which descriptions belong in Cell-Mediated Immunity only? Options: A. Activated by free antigens, B. Defends against intracellular pathogens, C. Defends against cancer, D. Involves B cells, E. Involves cytotoxic T cells, F. Involves helper T cells, G. Involves antigens.","correctAnswer":"E, B, C","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_129","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Medium","question":"List the four cardinal signs of inflammation.","correctAnswer":"(1) redness (2) swelling (3) heat (4) pain","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_130","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Hard","question":"Compare the maturation process of T cells in the thymus cortex and medulla.","correctAnswer":"(1) T cells in the cortex are tested on their ability to recognize foreign antigens/APCs while (2) T cells in the medulla are tested on whether they react to host antigens/APCs","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_131","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Hard","question":"Briefly describe the two mechanisms by which natural killer cells induce apoptosis in target cells.","correctAnswer":"(1) expression of the fas ligand (2) which sends the cell apoptotic signals. (3) Release of perforins and granzymes (4) which form pores and trigger apoptosis.","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_132","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Hard","question":"Cold medications that act to reduce fever such as aspirin tend to slow recovery time from illness. What beneficial role does fever play?","correctAnswer":"increases interferon activity, prevents bacteria and virus reproduction, increases metabolism of host cells, speeds up tissue repair (any of the above)","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_133","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Medium","question":"A 53 year-old male presents with a 103°F fever and night sweats. He tested HIV-positive 4 years ago and has lost 20 pounds over the last month. HIV is known as a retrovirus. What does this mean?","correctAnswer":"HIV is an RNA virus (reverse transcriptase)","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_134","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Medium","question":"The death of which cell type is responsible for the marked immunodeficiency found in patients like the one described with HIV?","correctAnswer":"CD4 T lymphocytes","year":2023,"tournament":"SSSS"},
  {"id":"q_ap_2023_ssss_135","event":"Anatomy & Physiology","subtopic":"Immune System","division":"C","type":"FRQ","difficulty":"Hard","question":"Identify the criteria necessary for diagnosis of AIDS.","correctAnswer":"a CD4 count of <200 cells/mm3","year":2023,"tournament":"SSSS"}
,
  {"id":"q_astro_2024_ssss_1","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Easy","question":"HII regions are formed when photons remove electrons from hydrogen atoms, a process known as ___________?","correctAnswer":"Ionization","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_2","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Easy","question":"In order to achieve ionization, photons need to possess above 13.6 eV (2.18e-18 J) of energy. This value is known as the _______________?","correctAnswer":"Lyman Limit","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_3","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Medium","question":"Using the Lyman Limit energy (2.18e-18 J), calculate the maximum wavelength of a photon in order for it to be energetic enough to knock an electron off of a hydrogen atom in nanometers.","correctAnswer":"91 nm","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_4","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Medium","question":"What is a Strömgren radius and how does it relate to HII regions?","correctAnswer":"The Strömgren radius gives the radius of an idealized, spherical HII region. It describes the sphere of hydrogen that can be ionized given the luminosity of an ionizing source.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_5","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Hard","question":"The Strömgren radius can be described by the formula R_s = (3Q_s / 4pi*n^2*alpha)^x. Where R is the length of the Strömgren radius, Q is the number of energetic photons emitted in a unit of time, n is the number density of protons, alpha is the recombination coefficient with units of meters^3 per second, and x is an unknown constant. Determine x by dimensional analysis.","correctAnswer":"1/3","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_6","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following classes of stars are typically hot enough to create HII regions?","options":["M and A","A and O","O and B","B and M"],"correctAnswer":"O and B","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_7","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the strongest hydrogen emission line from HII regions, and what causes the emission of this type of radiation?","correctAnswer":"Hydrogen-alpha, or Hα. It is emitted when an ionized hydrogen atom collides with an electron and they recombine, specifically when the newly captured electron drops from the third orbital to the second.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_8","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Medium","question":"Herbig Haro objects are typically _________ (larger/smaller) than HII regions and are ___________ (more/less) dense.","correctAnswer":"Smaller, More","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_9","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Hard","question":"Given 4 images of galaxies (A is an elliptical galaxy, others are spiral/irregular), which galaxy is least likely to contain HII regions and why?","correctAnswer":"Image A. It is an elliptical galaxy, in which HII regions rarely form, because elliptical galaxies have a lot less available gas, as most of it is used to form stars.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_10","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Medium","question":"How are Herbig Haro objects formed?","correctAnswer":"HH objects are formed when a jet of ionizing radiation emitted by a protostar collides with the interstellar medium, creating a region of ionized gas.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_11","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Hard","question":"As it turns out, about 80% of the stars giving rise to HH objects are binary or multiple star systems. Explain why this may be true.","correctAnswer":"A reason could be that binary/multiple stars systems are more likely to undergo mass-loss events or have an outflow that carries away excess angular momentum as the stars in a system spiral towards each other.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_12","event":"Astronomy","subtopic":"Star Formation","division":"C","type":"FRQ","difficulty":"Hard","question":"Why do Herbig Haro objects usually look “knotty” and irregular?","correctAnswer":"Because of the changes in their parent stars, including precession of the ionizing jets, pulsating, variability, and shock waves created by the jets interacting with the interstellar medium. They are also impacted by other external factors, such as stellar winds.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_13","event":"Astronomy","subtopic":"Stellar Evolution","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the difference between a classical, weak-line, and naked T Tauri star?","correctAnswer":"The difference is in the size of the circumstellar disk. Classical T Tauri stars have substantial circumstellar disks, while weak-line T Tauri stars have very small and faint disks, and naked T Tauri stars have no disk at all.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_14","event":"Astronomy","subtopic":"Stellar Evolution","division":"C","type":"FRQ","difficulty":"Medium","question":"Fusion of lithium through a proton-proton chain provides one of the main sources of energy for T Tauri stars. Explain why lithium burning can occur in these stars even when hydrogen fusion does not.","correctAnswer":"Lithium fuses at lower temperatures than hydrogen.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_15","event":"Astronomy","subtopic":"Stellar Evolution","division":"C","type":"FRQ","difficulty":"Medium","question":"The Henyey track is characterized by a decrease in the star’s _____________, while its luminosity stays basically constant.","correctAnswer":"Temperature","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_16","event":"Astronomy","subtopic":"Stellar Evolution","division":"C","type":"FRQ","difficulty":"Medium","question":"Stars that are _________ (less/more) massive typically spend more time on the Hayashi track.","correctAnswer":"Less","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_17","event":"Astronomy","subtopic":"Stellar Evolution","division":"C","type":"MCQ","difficulty":"Easy","question":"A characteristic of Herbig Ae/Be stars is the presence of an excess of ____________ radiation.","options":["Ultraviolet","Infrared","Radio","Gamma"],"correctAnswer":"Infrared","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_18","event":"Astronomy","subtopic":"Stellar Evolution","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the main cause of the excess infrared radiation in Herbig Ae/Be stars?","correctAnswer":"The presence of circumstellar dust and/or envelopes around the star, which emits infrared radiation.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_19","event":"Astronomy","subtopic":"Stellar Evolution","division":"C","type":"MCQ","difficulty":"Easy","question":"True or False: Herbig Ae stars are more massive than Herbig Be stars.","options":["True","False"],"correctAnswer":"False","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_20","event":"Astronomy","subtopic":"Stellar Evolution","division":"C","type":"MCQ","difficulty":"Easy","question":"What is the coolest class of brown dwarves?","options":["M Class","L Class","T Class","Y Class"],"correctAnswer":"Y Class","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_21","event":"Astronomy","subtopic":"Stellar Evolution","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of these sets of nuclear fusion reactions typically occurs at the highest temperatures?","options":["Proton-proton chain","CNO cycle","Triple-alpha process","Deuterium burning"],"correctAnswer":"Triple-alpha process","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_22","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"MCQ","difficulty":"Easy","question":"Which method of observing exoplanets has discovered the most exoplanets to date?","options":["Transit Photometry","Radial Velocity","Direct Imaging","Microlensing"],"correctAnswer":"Transit Photometry","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_23","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"FRQ","difficulty":"Hard","question":"If a radial velocity curve is quite skewed, identify a reason for this.","correctAnswer":"The skewed curve is caused by the orbit having an irregular argument of periapsis and a large eccentricity.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_24","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"MCQ","difficulty":"Easy","question":"What is the term for an exoplanet that is slightly more massive than the Earth?","options":["Super-Earth","Mini-Saturn","Rocky Jupiter","Hot Earth"],"correctAnswer":"Super-Earth","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_25","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the easiest type of exoplanet to detect by the radial velocity method?","correctAnswer":"Hot Jupiters","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_26","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain why Hot Neptunes are easier to observe via transit than Mini Neptunes.","correctAnswer":"A Hot Neptune is much larger than a Mini-Neptune, making both the probability that it will transit higher and the resulting transit deeper.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_27","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"MCQ","difficulty":"Medium","question":"What is the difference between a Hot Jupiter and a Hot Neptune?","options":["Hot Neptunes have more methane and ammonia, whereas Hot Jupiters have more helium and hydrogen compounds","Hot Neptunes are slightly colder than Hot Jupiters","Hot Jupiters are more massive than Hot Neptunes","Hot Jupiters are older than Hot Neptunes"],"correctAnswer":"Hot Jupiters are more massive than Hot Neptunes","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_28","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"FRQ","difficulty":"Hard","question":"Explain why the radial velocity method only allows us to calculate a lower bound for the mass of an exoplanet. Identify which orbital parameter is the cause of this.","correctAnswer":"The parameter that matters is the inclination i of the orbit. The radial velocity method assumes that the orbit is facing the observer head on, ignoring any motion perpendicular to our line of sight, taking the radial velocity of the star at its minimum possible value. By calculating mass from this, we are calculating its minimum possible mass.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_29","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"FRQ","difficulty":"Medium","question":"Imagine that a planet of mass m orbits a star with mass M. In the frame of reference of their center of mass, what is the total linear momentum of the system?","correctAnswer":"0","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_30","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"FRQ","difficulty":"Medium","question":"What is a Chthonian planet?","correctAnswer":"A Chthonian planet is a gas giant whose atmosphere has been stripped away, leaving only the rocky and metallic core.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_31","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"FRQ","difficulty":"Hard","question":"Name a phenomenon or process that might lead to the formation of a Chthonian planet.","correctAnswer":"This can happen through hydrodynamic escape, when a planet’s atmosphere is carried away through collisions with small, energetic particles like photons. Another way is if the atmosphere is stripped away by solar winds from the host star.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_32","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"FRQ","difficulty":"Hard","question":"A Hycean planet is a theoretical exoplanet that is slightly larger than Earth. What are two features of Hycean planets that might make them promising candidates to look for life?","correctAnswer":"Their surfaces would be covered in water, they would have more free energy available to an ecosystem, and there would be organic molecules present to foster life.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_33","event":"Astronomy","subtopic":"Exoplanets","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the difference between in situ and ex situ formation of exoplanets?","correctAnswer":"In situ refers to planets that have formed at the same orbital distance as they are currently, whereas ex situ refers to planets that form in different orbital distances than they are currently orbiting at.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_34","event":"Astronomy","subtopic":"Orbital Mechanics","division":"C","type":"FRQ","difficulty":"Easy","question":"An eccentricity of 0 describes a __________ orbit.","correctAnswer":"Circular","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_35","event":"Astronomy","subtopic":"Orbital Mechanics","division":"C","type":"MCQ","difficulty":"Easy","question":"When the total energy is positive, the object takes a/an ________ path.","options":["Straight","Elliptical","Parabolic","Hyperbolic"],"correctAnswer":"Hyperbolic","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_36","event":"Astronomy","subtopic":"Orbital Mechanics","division":"C","type":"MCQ","difficulty":"Easy","question":"When the total energy is zero, the object takes a/an ________ path.","options":["Straight","Elliptical","Parabolic","Hyperbolic"],"correctAnswer":"Parabolic","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_37","event":"Astronomy","subtopic":"Orbital Mechanics","division":"C","type":"MCQ","difficulty":"Easy","question":"When the total energy is negative, the object takes a/an ________ path.","options":["Straight","Elliptical","Parabolic","Hyperbolic"],"correctAnswer":"Elliptical","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_38","event":"Astronomy","subtopic":"Orbital Mechanics","division":"C","type":"FRQ","difficulty":"Medium","question":"What must be the ratio between an object’s kinetic and potential energy in order for its orbit to be circular?","correctAnswer":"-1/2","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_39","event":"Astronomy","subtopic":"Stellar Parameters","division":"C","type":"FRQ","difficulty":"Medium","question":"A star is discovered with a parallax of 0.014 arcseconds. Its spectrum shows a maximum wavelength of about 430 nm. What is the temperature of the star in Kelvin?","correctAnswer":"around 6700 K","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_40","event":"Astronomy","subtopic":"Stellar Parameters","division":"C","type":"MCQ","difficulty":"Medium","question":"Neutral hydrogen and metal lines are detected from the star. What, most likely, is its stellar class?","options":["A","B","K","F"],"correctAnswer":"F","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_41","event":"Astronomy","subtopic":"Stellar Parameters","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the distance to the star (parallax 0.014 arcseconds) in meters?","correctAnswer":"2.2e+18 meters","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_42","event":"Astronomy","subtopic":"Stellar Parameters","division":"C","type":"FRQ","difficulty":"Hard","question":"Given that the angular diameter of the star is 550 μas, and its distance is 71.43 parsecs, what is its radius in meters?","correctAnswer":"2.9e+9 meters","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_43","event":"Astronomy","subtopic":"Stellar Parameters","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the luminosity of the star (R=2.9e+9 m, T=6700 K)? Express the answer in both solar luminosities and Watts.","correctAnswer":"30.9 solar luminosities / 1.2e+28 Watts","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_44","event":"Astronomy","subtopic":"Stellar Parameters","division":"C","type":"FRQ","difficulty":"Hard","question":"Assume the star is on the main sequence. Approximate its mass in solar masses given a luminosity of 30.7 solar luminosities.","correctAnswer":"2.6 solar masses","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_45","event":"Astronomy","subtopic":"Exoplanet Parameters","division":"C","type":"FRQ","difficulty":"Hard","question":"A planet is discovered orbiting the star at a transit depth of 2.26E - 5. What is the radius of the planet in Earth radii?","correctAnswer":"2.15 Earth radii","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_46","event":"Astronomy","subtopic":"Exoplanet Parameters","division":"C","type":"FRQ","difficulty":"Medium","question":"An exoplanet orbits a sun-like star with an approximately circular orbit. Its radial velocity curve shows one full cycle every 700 days. What is the period of the planet’s orbit?","correctAnswer":"around 700 days","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_47","event":"Astronomy","subtopic":"Exoplanet Parameters","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the orbital radius of the planet (period = 700 days, orbiting a sun-like star)? Express your answer in meters and AU.","correctAnswer":"1.54 AU / 2.3e+11 meters","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_48","event":"Astronomy","subtopic":"Exoplanet Parameters","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the orbital velocity of a star if its radial velocity curve peaks at 47 m/s?","correctAnswer":"47 m/s","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_49","event":"Astronomy","subtopic":"Exoplanet Parameters","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the mass of the planet in Earth masses? (Star mass = 2e30 kg, star velocity = 47 m/s, planet orbital velocity = 2.4e4 m/s)","correctAnswer":"653.27 Earth masses","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_50","event":"Astronomy","subtopic":"Exoplanet Parameters","division":"C","type":"FRQ","difficulty":"Medium","question":"Is this planet (orbiting at 1.54 AU around a 1 solar luminosity star) in the habitable zone of the star? If not, is it too close or too far?","correctAnswer":"Not in the habitable zone because it is too far","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_51","event":"Astronomy","subtopic":"Exoplanet Parameters","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the equilibrium temperature of the planet? Assume that it has very little atmosphere and a bond albedo of 0.4, and give your answer in Celsius. (L = 3.8e26 W, d = 2.3e11 m)","correctAnswer":"-76 degrees Celsius","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_52","event":"Astronomy","subtopic":"Exoplanet Parameters","division":"C","type":"FRQ","difficulty":"Medium","question":"Planets that receive too little flux from their stars will usually be too cold for life to flourish. However, it is possible for them to support life by retaining heat. Identify one way this can be done.","correctAnswer":"The planet can retain heat through the greenhouse effect, as well as by having a smaller bond albedo.","year":2024,"tournament":"SSSS"}
,
  {"id":"q_botany_2020_ut_1","event":"Botany","subtopic":"Economic Botany","division":"C","type":"MCQ","difficulty":"Medium","question":"In Theophrastus' famous book, Enquiry Into Plants, one of the 10 books on the natural history of plants describes it's medicinal uses. For example, hemlock is a poison that gives a painless death; pepper is its antidote. Which of the following plants can be used to expel a woman's placenta?","options":["Strykhnos","Peony","Frankincense","Birthwort"],"correctAnswer":"Birthwort","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_2","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Hard","question":"According to the ABC Hypothesis in flower development, this abnormal Arabidopsis flower seems to have an internal flower replacing carpels in normal plants, meaning that there is a mutation in which of the following genes.","options":["A","B","C"],"correctAnswer":"C","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_3","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following phytopathogenic diseases is on a tree in the picture below?","options":["Apiosporina morbosa","Thousand Cankers","Black Knot","Anthracnose"],"correctAnswer":"Thousand Cankers","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_4","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"MCQ","difficulty":"Medium","question":"Cedar-apple rust is an example of a disease caused by a fungus with a polycyclic life cycle.","options":["True","False"],"correctAnswer":"False","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_5","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the production of fruit without any seeds called?","correctAnswer":"Parthenocarpy","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_6","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Medium","question":"A. tumefaciens genes force plant cells to produce which of the following plant hormones?","options":["Auxin and Cytokinin","Auxin and Gibberellin","Cytokinin and Ethylene","Gibberellin and Testosterone","Abscisic acid and Ethylene"],"correctAnswer":"Auxin and Cytokinin","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_7","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"MCQ","difficulty":"Easy","question":"Powdery mildew can be wiped off of the surface of a plant, making it easy to control without the use of a fungicide.","options":["True","False"],"correctAnswer":"True","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_8","event":"Botany","subtopic":"Biochemistry","division":"C","type":"MCQ","difficulty":"Hard","question":"Which of the following is not an agent that interferes with oxidation phosphorylation or photophosphorylation?","options":["Myxothiazol","Amytal","Rotenone","Ubiquinone"],"correctAnswer":"Ubiquinone","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_9","event":"Botany","subtopic":"Biochemistry","division":"C","type":"MCQ","difficulty":"Easy","question":"What part of a plant's chloroplast does the Calvin Cycle take place?","options":["Inner membrane","Outer membrane","Thylakoid","Stroma"],"correctAnswer":"Stroma","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_10","event":"Botany","subtopic":"Biochemistry","division":"C","type":"MCQ","difficulty":"Easy","question":"In [answer], CO2 is first fixed in mesophyll cells into oxaloacetate then malate, which then passes into bundle-sheath cells and releases CO2 in high concentrations.","options":["C2 plants","C3 plants","C4 plants","CAM plants"],"correctAnswer":"C4 plants","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_11","event":"Botany","subtopic":"Biochemistry","division":"C","type":"MCQ","difficulty":"Medium","question":"Where would one look for oxygen production in photosynthesis?","options":["Hack and Slack cycle","Cyclic phosphorylation","Noncylic phosphorylation","Calvin Cycle"],"correctAnswer":"Noncylic phosphorylation","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_12","event":"Botany","subtopic":"Biochemistry","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following enzymes helps an excited Photosystem I (PSI) pass its electrons from ferredoxin to NADP+.","options":["PQa","FNR","PQb","Plastocyanin"],"correctAnswer":"FNR","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_13","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Medium","question":"The following question will test your knowledge of this flower's anatomical parts. Read all of the provided choices then select the incorrect answer.","options":["A3; contains one or more ovules that develop into seeds once fertilized.","B2; male reproductive part which contains pollen.","B4; collectively called the calyx.","A1; a source of nectar that attracts insects and birds.","A2; often sticky from which pollen germinates."],"correctAnswer":"A2; often sticky from which pollen germinates.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_14","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Hard","question":"Inflorescence is a botanical term used to describe the arrangement of different plants, in this case, flowers. What type of inflorescence flower is this?","options":["Panicle","Raceme","Compound cyme","Compound umbel","Corymb"],"correctAnswer":"Compound umbel","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_15","event":"Botany","subtopic":"Taxonomy","division":"C","type":"MCQ","difficulty":"Easy","question":"Compare the plant in the previous question to a cycad. Which of the following scientific classifications is unique to a cycad?","options":["Eukaryota","Spermatophyte","Gymnospermae","Trachophytes","Eudicots"],"correctAnswer":"Gymnospermae","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_16","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Easy","question":"Plastic mulches are not effective for evaporation control because they are not biodegradable.","options":["True","False"],"correctAnswer":"False","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_17","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"MCQ","difficulty":"Hard","question":"Which of the following viruses is used for the bio-control of insect pests in plants?","options":["Rice Tungro Virus","Nuclear Polyhedrosis Virus","Cucumber Mosaic Virus","Tomato Mosaic Virus"],"correctAnswer":"Nuclear Polyhedrosis Virus","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_18","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following is not an adaptation of a hydrophyte?","options":["There exists a poorly developed root system.","There is less parenchyma in the stem.","Stomata found on the upper leaf surface.","There are fewer cuticles over the epidermis by comparison."],"correctAnswer":"There is less parenchyma in the stem.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_19","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following is not an adaptation of xerophytic plants?","options":["Presence of palisade-like tissue in the stem","Presence of thick cuticles","Adopts the CAM cycle for photosynthesis","Large leaves are present"],"correctAnswer":"Large leaves are present","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_20","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Medium","question":"Black mustard seeds (Brassica juncea) are edible and used as the phytoremediation agent for the removal of which of the following heavy metals found in the soil?","options":["Lead","Cadmium","Nickel","Arsenic","Copper"],"correctAnswer":"Lead","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_21","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following routes allow water and minerals to diffuse into the cortex along the matrix of walls and extracellular spaces?","options":["Symplastic","Transmembrane","Apoplastic","Xylemic","Vascular"],"correctAnswer":"Apoplastic","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_22","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"MCQ","difficulty":"Medium","question":"This discolored leave exhibits a disease that is common in acidic or sandy soils, indicating which macronutrient deficiency?","options":["Mg 2+","K+","Ca 2+","SO4 2-"],"correctAnswer":"Mg 2+","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_23","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Easy","question":"The Mistletoe plant would be most closely associated with which of the following symbiotic relationships?","options":["Commensalism","Mutualism","Parasitism","Recidivism","Amensalism"],"correctAnswer":"Parasitism","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_24","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Easy","question":"Plants that grow under direct sunlight and called [Answer 1], and those growing under shade are called [Answer 2].","options":["Heliophytes and Psamophytes","Psamophytes and Heliophytes","Sciophytes and Psamophytes","Heliophytes and Sciophytes"],"correctAnswer":"Heliophytes and Sciophytes","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_25","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Medium","question":"In callus culture, higher concentrations of auxin rather than cytokinin induce the formation of which plant structure?","options":["Adventitious Shoot","Adventitious Root","Bothe Root and Shoot","None of the Above"],"correctAnswer":"Adventitious Root","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_26","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Medium","question":"Mangrove trees inhabiting low tides and growing in oxygen-poor waters develop unique root systems such that their roots appear in the air. What are these roots known as?","options":["Buttress roots","Strangling aerial roots","Pneumatophores","Prop roots"],"correctAnswer":"Pneumatophores","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_27","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"FRQ","difficulty":"Medium","question":"The evolutionary adaptation of stems by plants is quite unique. Whether for food storage or asexual reproduction, plants develop modified stems that are often mistaken for roots. Identify the modified stems in a strawberry plant image.","correctAnswer":"Stolons and Runners","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_28","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Easy","question":"Lateral plant roots stem from which of the following plant structures?","options":["Pith","Endodermis","Cortex","Pericycle"],"correctAnswer":"Pericycle","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_29","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Easy","question":"Narrowed xylem cells with lignified walls that help with water transportation.","options":["Endodermis","Collenchyma","Sclerenchyma","Tracheids","Periderm"],"correctAnswer":"Tracheids","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_30","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Hard","question":"Which of the following describes connation in flowers? 1. Styles connected to stamen, 2. Petals connected to each other, 3. Pistil connected to stamen, 4. Carpels connected to each other","options":["1","2,3","1,4","2,4","4"],"correctAnswer":"2,4","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_31","event":"Botany","subtopic":"Taxonomy","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following correctly identifies the taxonomical category of an orange/citrus fruit slice image?","options":["Achenes","Drupe","Pepo","Hesperidium","Cirkusis","Pome"],"correctAnswer":"Hesperidium","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_32","event":"Botany","subtopic":"Taxonomy","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following came second in plant evolution?","options":["Non-vascular plants","Conifers","Seedless vascular plants","Flowering plants"],"correctAnswer":"Seedless vascular plants","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_33","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"FRQ","difficulty":"Medium","question":"Plants that can switch between C3 and CAM mode are called _________ _____. Capitalize the first word. Capitalize the entire second word (acronym).","correctAnswer":"Facultative CAM","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_34","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"MCQ","difficulty":"Easy","question":"A microbe found on a plant with Erwinia carotovora may have caused a certain disease but you cannot find published information verifying this. Which procedure do you follow to determine whether this pathogen caused that disease?","options":["Fungal determinant.","Karnal's rules.","Draw numbers out of a hat.","Koch's postulates.","Moist chamber."],"correctAnswer":"Koch's postulates.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_35","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"FRQ","difficulty":"Hard","question":"Which of the following diseases does the microbe Erwinia carotovora cause? (Aster yellows, Soft rot, Apple scab, Slime flux, Corn smut)","correctAnswer":"Soft rot and Slime flux","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_36","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"MCQ","difficulty":"Medium","question":"Fireblight initially evolved in which continent?","options":["Asia","North America","South America","Europe"],"correctAnswer":"North America","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_37","event":"Botany","subtopic":"Economic Botany","division":"C","type":"MCQ","difficulty":"Hard","question":"Biodiesel is obtainable from which plant?","options":["Prosopis","Catharanthus","Calotropis","Jatropha curcas"],"correctAnswer":"Jatropha curcas","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_38","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Medium","question":"A biodiversity hotspot is characterized by which of the following concepts?","options":["Endemic plants","Threat perception","Endemic flowering plants","Species flowering plants"],"correctAnswer":"Endemic flowering plants","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_39","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following ecosystem has the longest energy transfer time?","options":["Open ocean","Tropical rain","Temperate deciduous","Desert"],"correctAnswer":"Temperate deciduous","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_40","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Hard","question":"Gibberellic Acid (GA) controls seed germination by directing breakdown of the stored starch. Which of the following barley seed tissues does the a-amylase gene is induced in respond to GA?","options":["Endosperm","Coleoptile","Aleurone layer","Embryo"],"correctAnswer":"Aleurone layer","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_41","event":"Botany","subtopic":"Biochemistry","division":"C","type":"MCQ","difficulty":"Hard","question":"Nitrogen fixation is a process where nitrogen gas is converted into ammonia. One of the key enzymes in this process is nitrogenase. Which of the following statements best highlights the production and activity of nitrogenase? 1. Energetically expensive process. 2. Under a constitutive promoter. 3. Highly sensitive to oxygen. 4. Endogenous availability of cofactor is very low.","options":["1 and 2","1 and 3","2 and 3","2 and 4"],"correctAnswer":"1 and 3","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_42","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Medium","question":"The bending of an oat coleoptile tip towards the source of unilateral light of wavelength 454 nm is due to which of the following?","options":["Synthesis of auxin in the shaded area.","Lateral distribution of auxin toward shaded area","Degradation of auxin in the light area.","Polar transport of auxin."],"correctAnswer":"Lateral distribution of auxin toward shaded area","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_43","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Medium","question":"The hydrostatic opening of stomata is due to which of the following?","options":["Movement of K+ ions into guard cells.","Low water potential in mesophyll cells.","Movement of water into guard cells.","Decreased concentration of ABA."],"correctAnswer":"Low water potential in mesophyll cells.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_44","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following are regulators of plant circadian rhythms?","options":["Phototropins","Cryotophores","Phycobilins","Phytochromes"],"correctAnswer":"Phytochromes","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_45","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Easy","question":"What type of fruit is a pineapple?","options":["Berry","Aggregate","Dehiscent","Multiple"],"correctAnswer":"Multiple","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_46","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Easy","question":"What are the paired outgrowths typically found alongside the petiole attachment to the stem called?","options":["Stipules","Crazy twig","Areoles","Lenticels"],"correctAnswer":"Stipules","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_47","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Medium","question":"Certain plants have an anatomical feature called a holdfast. Such a plant would be associated with which biome?","options":["Desert","Ocean","Tropical rainforest","Tundra"],"correctAnswer":"Ocean","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_48","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Easy","question":"Abscission in a plant would be associated with which of the following process?","options":["Germination","Reproduction","Growth","Defoliation"],"correctAnswer":"Defoliation","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_49","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following is an example of an organ of perennation in plants?","options":["Rhizome","Seed","Petal of a flower","Calyx of a flower"],"correctAnswer":"Rhizome","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_50","event":"Botany","subtopic":"Biochemistry","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following statments is correct?","options":["Plants absorb carbon dioxide and only release oxygen.","Plants absorb carbon dioxide, and release oxygen and carbon dioxide.","Plants absorb carbon dioxide and oxygen, and release oxygen and carbon dioxide.","Plants absorb oxygen and only release carbon dioxide."],"correctAnswer":"Plants absorb carbon dioxide and oxygen, and release oxygen and carbon dioxide.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_51","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Easy","question":"The embryonic portion of the seed is called the radicle is associated with which of the following plant parts?","options":["Fruiting body","Root","Leaf","Stem"],"correctAnswer":"Root","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_52","event":"Botany","subtopic":"Taxonomy","division":"C","type":"FRQ","difficulty":"Easy","question":"What plant is known as the smallest flowering plant? Hint: Has two tiny vascular roots. Capitalize the first letter of the first word. One-word answer.","correctAnswer":"Duckweed","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_53","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Easy","question":"Thorns are found on many different plants but biologically are not modified leaves.","options":["True","False"],"correctAnswer":"True","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_54","event":"Botany","subtopic":"Ecology","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the symbiotic relationship between various fungi and plant roots called? Capitalize the first letter of the first word. One-word answer.","correctAnswer":"Mycorrhizae","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_55","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Medium","question":"The relationship described in the previous question occurs in what percentage of plants?","options":["50%","70%","80%","90%"],"correctAnswer":"80%","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_56","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Medium","question":"Some plants produce an underground stem that is almost entirely stem tissue. Which of the following option refers to such a growth?","options":["Corm","Rhizome","Stolon","Tuber"],"correctAnswer":"Corm","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_57","event":"Botany","subtopic":"Economic Botany","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following was not restricted to the Western Hemisphere until 1942?","options":["Banana","Cacao","Potato","Pepper"],"correctAnswer":"Banana","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_58","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Hard","question":"The photosynthetic process can only make use of a fraction of the total energy in sunlight. For a \"typical\" plant, how much of sunlight is in the photosynthetically active wavelength range?","options":["65%","55%","45%","35%"],"correctAnswer":"45%","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_59","event":"Botany","subtopic":"Taxonomy","division":"C","type":"MCQ","difficulty":"Medium","question":"Which macroscopic group of marine plants is the most diverse and abundant?","options":["Chrysophyta","Phaeophyta","Pyrrophyta","Rhodophyta"],"correctAnswer":"Rhodophyta","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_60","event":"Botany","subtopic":"Taxonomy","division":"C","type":"MCQ","difficulty":"Easy","question":"Sedges superficially resemble grasses. Which of the following statements does not accurately describe the differences between grasses and sedges?","options":["Sedges have triangular stems with leaves that are arranged in three ranks.","Sedges have hollow stems.","Sedge leaves confined to the base and/or top of the plant.","Sedges have specialized flowering structures."],"correctAnswer":"Sedges have hollow stems.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_61","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Medium","question":"Periphyton is a type/group of plants that would be associated with which of the following settings?","options":["Sand dunes","Tropical/Semitropical forests","Rivers/Streams","Tundras"],"correctAnswer":"Rivers/Streams","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_62","event":"Botany","subtopic":"Ecology","division":"C","type":"FRQ","difficulty":"Easy","question":"Many trees, mostly gymnosperms, do not release their seeds until exposed to high heat, such as a fire. Such a cone is described as? Capitalize the first letter of the first word. One-word answer (adjective).","correctAnswer":"Serotinous","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_63","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"MCQ","difficulty":"Easy","question":"Which color light is the most important for plant growth and flowering?","options":["Blue and Red","Green and Blue","Red and Green","Orange and Red"],"correctAnswer":"Blue and Red","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_64","event":"Botany","subtopic":"Economic Botany","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following reasons correctly describes why coffee plants produce caffeine?","options":["As an energy storage mechanism.","As a pesticide to ward off insects.","As a means to help survive extended dry periods.","As an astringent to discourage grazing animals."],"correctAnswer":"As a pesticide to ward off insects.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_65","event":"Botany","subtopic":"Ecology","division":"C","type":"FRQ","difficulty":"Medium","question":"If you were a chiropterophilus plant, you would have adapted yourself to attract the attention of what organism for pollination? Capitalize the first letter of the first word. One-word answer.","correctAnswer":"Bat","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_66","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"FRQ","difficulty":"Easy","question":"Any response of a plant to the relative lengths of daylight and darkness. Capitalize the first letter of the first word. One-word answer.","correctAnswer":"Photoperiodism","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_67","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following trees are well known for allelopathy?","options":["Oak","Walnut","Beech","Pecan"],"correctAnswer":"Walnut","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_68","event":"Botany","subtopic":"Economic Botany","division":"C","type":"MCQ","difficulty":"Medium","question":"California is one of the nation's largest agricultural producers. Agriculture in California is faced with the constant (and growing) challenge of limited water supply. Which of these crops is the largest consumer of water (total aggregate volume) in that state?","options":["Rice","Vineyards/Wine","Citrus","Almonds/Pistachios"],"correctAnswer":"Almonds/Pistachios","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_69","event":"Botany","subtopic":"Economic Botany","division":"C","type":"FRQ","difficulty":"Easy","question":"What medication (common name) was first identified from the bark of the willow tree? Capitalize the first letter of the first word. One-word answer.","correctAnswer":"Aspirin","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_70","event":"Botany","subtopic":"Taxonomy","division":"C","type":"MCQ","difficulty":"Easy","question":"What are the oldest living trees on Earth called?","options":["Bristlecone Pines","Gingko","California Sycamore","Utah Juniper"],"correctAnswer":"Bristlecone Pines","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_71","event":"Botany","subtopic":"Ecology","division":"C","type":"MCQ","difficulty":"Easy","question":"Which soil is rich in organic debris?","options":["Loam soil","Humus soil","Saprophyte","Sandy soil"],"correctAnswer":"Humus soil","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_72","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following is not considered to be a true fruit?","options":["Date","Plum","Apple","Grape"],"correctAnswer":"Apple","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_73","event":"Botany","subtopic":"Taxonomy","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the term used to describe \"land plants\"? Capitalize the first letter of the first word. One-word plural answer.","correctAnswer":"Embryophytes","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_74","event":"Botany","subtopic":"Taxonomy","division":"C","type":"FRQ","difficulty":"Medium","question":"What group of plants is distinguishable from all other plant groups by the complete absence of stomata? Capitalize the first letter of the first word. One-word plural answer.","correctAnswer":"Liverworts","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_75","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"MCQ","difficulty":"Medium","question":"Which one of the following is not associated with stomata?","options":["Water","Oxygen","Carbon Dioxide","Hydrogen"],"correctAnswer":"Hydrogen","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_76","event":"Botany","subtopic":"Taxonomy","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following are not a basic growth form of lichen?","options":["Foliose","Fructose","Crustose","Glucose","Fruticose"],"correctAnswer":"Fructose","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_77","event":"Botany","subtopic":"Ecology","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the name for a fire that runs through the tops of living trees or bushes? Capitalize the first letter of the first word. One-word answer.","correctAnswer":"Crown","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_78","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"FRQ","difficulty":"Medium","question":"What type of \"fruit\" structure is produced by an American Elm? Capitalize the first letter of the first word. One-word answer.","correctAnswer":"Samara","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_79","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"FRQ","difficulty":"Medium","question":"Dead empty tubes that make up the largest component of conifer wood (90-94% of volume) are known as what? Capitalize the first letter of the first word. One-word plural answer.","correctAnswer":"Tracheids","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_80","event":"Botany","subtopic":"Biochemistry","division":"C","type":"MCQ","difficulty":"Easy","question":"How many molecules of carbon dioxide are needed in photosynthesis to produce one glucose molecule?","options":["4","6","2","12","3"],"correctAnswer":"6","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_81","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"FRQ","difficulty":"Medium","question":"From the left column down then right column down, identify the following stem parts which are numerically classified. Number each answer in order.","correctAnswer":"1. Last Year's Growth, 2. Internode, 3. Terminal Bud, 4. Axillary Bud, 5. Leaf Scar, 6. Bud Scale Scar, 7. Node, 8. Lenticels.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_82","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"FRQ","difficulty":"Medium","question":"Which of the following leaf bases describes the leaf image (a taro leaf)? (Peltate, Truncate, Dentate, Sagittate)","correctAnswer":"Peltate","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_83","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"FRQ","difficulty":"Easy","question":"Type the answer that describes the leaf margins in this picture below (it has jagged edges). Remember to capitalize the first letter only. One-word answer.","correctAnswer":"Serrate","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_84","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify this leaf shape followed by its venation. First answer should be the leaf shape. Second answer should be its venation type.","correctAnswer":"Ovate Pinnate","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_85","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"FRQ","difficulty":"Hard","question":"The plant genus Alternanthera includes some C3 and C4 species. From the three graphs below, identify and justify which species is a C3 plant and which is a C4 plant. Name one C3, C4, and CAM plant.","correctAnswer":"C3 plant: Species 2. C4 plant: Species 1. C3 plants are less efficient than C4 because as CO2 levels increase, photorespiration is suppressed. C3 plant: wheat; C4 plant: corn; CAM plant: pineapple.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_86","event":"Botany","subtopic":"Plant Anatomy","division":"C","type":"FRQ","difficulty":"Hard","question":"Below is a microscopic transverse image of the native black locust (Robinia pseudoacacia) displaying a plant condition. Name the growths around these vessels and identify their relative location. Describe how these growths are formed. Reason why these growths are formed. What role do ergastic substances play? Include two ergastic substances in your answer. Describe how this relates to CODIT.","correctAnswer":"Tyloses growths. Located in the lumen of tracheids or vessels of the secondary xylem. Balloon-like outgrowths of parenchymatous cells formed when a plant is stressed by a drought or infection. They block up the vascular tissue to prevent further plant damage and prevent water leakage. Ergastic substances (like resins and tannins) produce odors which protects the wood from termites and mites. CODIT helps arborists analyze the dangers posed by damaged or decaying trees; cells undergo changes to form walls around the wound to slow the spread of disease.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_87","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"FRQ","difficulty":"Medium","question":"Below is an image of the effects of Dutch Elm Disease spread by elm beetles. In your own words, describe two preventable management treatments that can control the spread of Dutch Elm Disease.","correctAnswer":"Mechanical: Pruning and burning diseased timber. Biological: Use of Dutch Trig (nontoxic, suspension of fungal spore strains) injected in the elm to induce an immune response through pathogenicity.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_88","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"FRQ","difficulty":"Medium","question":"Seed dormancy is caused by inner or outer embryonic conditions activated by survival mechanisms. Describe two human practices of breaking seed dormancy to promote and ensure successful germination?","correctAnswer":"Stratification: putting seeds in a refrigerator for a month or in a heated propagator. Scarification: rubbing the seed coat with a file or small seeds shaken in a screw-lid jar lined with sandpaper.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_89","event":"Botany","subtopic":"Plant Physiology","division":"C","type":"FRQ","difficulty":"Hard","question":"Explain how the C4 and CAM pathways are two evolutionary solutions of maintaining photosynthesis with stomata partially or completely closed on hot, dry days? Your response must have the following terms: CO2, mesophyll cells, bundle-sheath cells, Calvin Cycle, PEP Carboxylase. Identify two biomes that C4 plants dominate and describe why?","correctAnswer":"C4 plants: PEP carboxylase adds CO2 to phosphoenolpyruvate in mesophyll cells, which has a much higher affinity for CO2 than rubisco, minimizing photorespiration. The malate is exported to bundle-sheath cells for the Calvin Cycle. CAM plants: Mesophyll cells store organic acids during the night when stomata are open. During the day, CO2 is released from the organic acids for the Calvin cycle. C4 plants dominate grasslands and tundras due to hot environments maintaining low oxygen levels due to their CO2-concentrating system.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_90","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"FRQ","difficulty":"Hard","question":"Carefully read the following statements regarding Agrobacterium in plant transformation. 1. Region A in Ti Plasmid is responsible for replication. 2. Region D in Ti Plasmid is responsible for virulence. 3. A. tumefaciens causes hairy root disease and A. rhizogenes cause crown gall disease. 4. Oncogenic (onc) region in T-DNA is responsible for unusual amino acid synthesis. Identify the correct statement(s) by giving numeric answer(s). Identify what phenolic compound is released by a wounded plant cell. Describe the DNA transfer to plant cells by bacterial parasites... More specifically, what are the five main steps... Identify three types of metabolites...","correctAnswer":"Correct statement: 2. Phenolic compound: Acetosyringone. DNA transfer: Agrobacterium detects acetosyringone, vir genes on the Ti plasmid are expressed, T DNA segment is introduced into plant cell genome. T DNA is synthesized, transferred to plant cell, converted to duplex DNA and integrated into chromosome. Metabolites: Auxin, Cytokines, and Opines.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_91","event":"Botany","subtopic":"Plant Pathology","division":"C","type":"FRQ","difficulty":"Medium","question":"Some opines cannot be metabolized by most soil bacteria. Agrobacterium tumefaciens strains have specialized in utilizing these opines. What two components together synthesize opines?","correctAnswer":"Amino acids and ketoacids (or Amino acids and hexose).","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_92","event":"Botany","subtopic":"Economic Botany","division":"C","type":"FRQ","difficulty":"Medium","question":"Tree Pruning Essentials: Figure 1. Name the pruning technique attempted on this tree. Describe why this is poor pruning. Do consider the environment. Predict two potential issues with this tree’s health and provide at least one solution.","correctAnswer":"Crown-raising. The tree's crown is elevated too much. Lower than 60% live crown ratio should be avoided so that trunk taper is not affected adversely. Potential issues: Risk for decay and trunk cracks can form. Solution: allow the canopy to grow more to at least a 60% ratio.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_93","event":"Botany","subtopic":"Economic Botany","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following values is the correct pruning dose (maximum % of total foliage removed at one pruning) for a mature tree?","options":["25%","10%","50%","None of the above"],"correctAnswer":"10%","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_94","event":"Botany","subtopic":"Economic Botany","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following horticultural practices is demonstrated in this image showing leaves artfully trimmed into a group of musicians?","options":["Pleaching","Bedding","Mulching","Topiary"],"correctAnswer":"Topiary","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_95","event":"Botany","subtopic":"Economic Botany","division":"C","type":"MCQ","difficulty":"Medium","question":"Insects cannot harbor in trees that were poorly mulched.","options":["True","False"],"correctAnswer":"False","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_96","event":"Botany","subtopic":"Economic Botany","division":"C","type":"FRQ","difficulty":"Hard","question":"Tree Pruning Essentials: Figure 2. Describe this tree’s branches relative to its trunk and a potential risk created during a storm. What branch aspect ratio (percentage) should be maintained for such tree branches relative to the trunk? Strategize how would you prune this tree to create a branch structure that is both sustainable and environmentally safe.","correctAnswer":"There are multiple codominant leaders to which the trees are more likely to split during storms because there is an improper, or higher proper branch aspect ratio. Risk: More likely to split = increased chances for decay. Aspect ratio: 50% or less (at least a 2:1 ratio). Pruning strategy: Select the dominant stem in the center of the tree that is healthy and remove competing stems and branches with a reduction cut.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_97","event":"Botany","subtopic":"Economic Botany","division":"C","type":"MCQ","difficulty":"Medium","question":"In terms of the process and practices behind tree installation, which of the following is of poor detail?","options":["Establish support systems for your trees by stalking them for no longer than one year.","Wrap smooth bark trees as an easy control method to protect trees against rabbits, frost cracks, and sunscalds.","Nourish your trees by applying suitable mulching material around the tree.","Eliminate tree problems by pruning dead or dying twigs and branches."],"correctAnswer":"Nourish your trees by applying suitable mulching material around the tree.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_98","event":"Botany","subtopic":"Economic Botany","division":"C","type":"FRQ","difficulty":"Medium","question":"Arborists refer to the following image as a three-cut method that helps prevent infection by not tearing or splitting of the bark. Identify the three cuts in order from 1 to 3.","correctAnswer":"Undercut, Topcut, Stubcut","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_99","event":"Botany","subtopic":"Economic Botany","division":"C","type":"FRQ","difficulty":"Hard","question":"Define drug adulteration. Name the adulteration condition. Describe two other types of drug adulteration with at least one example for each type. Give two reasons for drug adulteration besides economic reasons.","correctAnswer":"The practice of making crude drugs of poorer quality through deliberate or unintentional reasons. Condition: Admixture. Other types: Inferiority (replacement with a substandard drug like Japanese ginger instead of Ginger) and Sophistication (addition of spurious or inferior material with an intent to defraud, like adding wheat flour to powdered ginger). Reasons: to make modified drugs cheaper and effective.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_100","event":"Botany","subtopic":"Economic Botany","division":"C","type":"FRQ","difficulty":"Hard","question":"One parameter behind the manufacturing process is measuring the percentage of acid-insoluble ash (AIA) in crude drugs. Describe one other manufacturing process for this herbal drug. Be sure to clearly identify your physicochemical parameter.","correctAnswer":"The pH value of an aqueous medium may be defined as the common logarithm of the reciprocal of the hydrogen ion concentration expressed in gram per liter. It was done by digital pH meter stabilized in a standard buffer solution.","year":2020,"tournament":"UT Invitational"},
  {"id":"q_botany_2020_ut_101","event":"Botany","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Hard","question":"Identify two chorismic biosynthetic precursors. Describe one distinct pathway (in plants). Identify two foods containing phenylalanine. Describe the role of the Shikimic acid pathway in quercetin biosynthesis. What is the difference between Roundup versus Roundup Ready? What enzymatic modification was made to Roundup? Describe the effect on crops and weeds sprayed with Roundup in regard to the enzymatic modification?","correctAnswer":"Precursors: phenylalanine and tyrosine. Pathway: in plants, tyrosine is produced via prephenate through decarboxylation. Foods: milk and eggs. Quercetin biosynthesis: Phenylalanine and tyrosine are precursors in phenylpropanoid synthesis which then produces flavonoids, lignin, and tannins. Roundup Ready are the GMO seeds resistant to glyphosate-based herbicide, Roundup. Enzymatic modification: Monsanto scientists altered the gene of the EPSP enzyme in plants to make it glyphosate-resistant. Effect: Glyphosate is a competitive inhibitor of PEP that shuts down the enzyme's catalysis, killing weeds, but has no effect on crops because they have the glyphosate-resistance gene.","year":2020,"tournament":"UT Invitational"}
,
  {"id":"q_genes_2025_ssss_1","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"MCQ","difficulty":"Medium","question":"Tom and his wife are both heterozygous for albinism, what is the probability their offspring will express the recessive phenotype?","options":["25%","50%","75%","0%"],"correctAnswer":"25%","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_2","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"FRQ","difficulty":"Hard","question":"Your friend has collected the following data from a monohybrid cross: 390 dominant phenotype, 120 recessive phenotype. She wants you to check if this data is consistent with the Mendelian ratio. Show your calculation using a chi-square test.","correctAnswer":"Chi-square = ((o-e)^2 / expected) = (390-382.5)^2 / 382.5 + (120-127.5)^2 / 127.5 = 0.588. Critical value = 3.84. Accept null hypothesis -> it is consistent.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_3","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"FRQ","difficulty":"Medium","question":"List 8 differences between mitosis and meiosis.","correctAnswer":"1. Purpose: Mitosis for asexual reproduction, Meiosis to make gametes. 2. Number of cell divisions. 3. Number of daughter cells. 4. Mitosis results in genetically identical daughters, meiosis does not. 5. Mitosis results in diploids, Meiosis in haploids. 6. Crossing over does not occur in mitosis. 7. In Mitosis, prophase takes longer. 8. In Meiosis anaphase I, sister chromatids move together and separate in anaphase II.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_4","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"MCQ","difficulty":"Medium","question":"How is DNA packaged inside a eukaryotic cell and how does this affect DNA replication?","options":["DNA in eukaryotic cells is packaged into chromatin using histone proteins, which helps organize the DNA but also makes it less accessible for replication unless it is unwound.","DNA in eukaryotic cells is loosely floating in the cytoplasm, which allows replication to occur at any time and location.","DNA is stored in circular chromosomes in the nucleus, which speeds up the replication process by eliminating the need for unwinding.","DNA in eukaryotic cells is tightly coiled around spindle fibers, preventing replication until cell division begins."],"correctAnswer":"DNA in eukaryotic cells is packaged into chromatin using histone proteins, which helps organize the DNA but also makes it less accessible for replication unless it is unwound.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_5","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"FRQ","difficulty":"Medium","question":"Match the following descriptions with the correct Non-Mendelian type of inheritance:\nA. Both alleles are equally and fully expressed, as in AB blood type.\nB. A red flower crossed with a white flower produces pink offspring.\nC. A trait with more than two alleles in the population, like the ABO blood group.\nD. Traits like height and skin color result from the additive effects of many genes.\n\nOptions: Polygenic Inheritance, Incomplete Dominance, Codominance, Multiple Alleles.","correctAnswer":"A: Codominance, B: Incomplete Dominance, C: Multiple Alleles, D: Polygenic Inheritance","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_6","event":"Designer Genes","subtopic":"Population Genetics","division":"C","type":"FRQ","difficulty":"Medium","question":"Given the Hardy Weinberg equilibrium of p = 0.6 calculate the q, frequency of heterozygotes, and frequency of homozygous recessives.","correctAnswer":"q = 0.4, Heterozygotes = 0.48, Homozygous recessive = 0.16","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_7","event":"Designer Genes","subtopic":"Population Genetics","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain the effects of a population bottleneck on genetic diversity.","correctAnswer":"Reduce gene pool and biodiversity due to drastic population size reduction","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_8","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"FRQ","difficulty":"Medium","question":"What inheritance pattern is shown in the pedigree below?","correctAnswer":"X-linked Recessive","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_9","event":"Designer Genes","subtopic":"Molecular Genetics","division":"C","type":"FRQ","difficulty":"Easy","question":"Match the following to their descriptions:\nA. Changes one amino acid to another\nB. Introduces a stop codon prematurely\nC. Alters the reading frame\nD. No change in amino acid sequence\n\nOptions: Frameshift, Missense, Silent, Nonsense","correctAnswer":"A: Missense, B: Nonsense, C: Frameshift, D: Silent","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_10","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"FRQ","difficulty":"Hard","question":"A trihybrid cross involves organisms that are heterozygous for three traits (e.g., AaBbCc × AaBbCc). Identify the 5 statements below that correctly describe a trihybrid cross and its expected phenotypic outcomes under Mendelian inheritance:\nA. The expected phenotypic ratio is 27:9:9:9:3:3:3:1.\nB. A trihybrid cross involves three independently assorting gene pairs.\nC. The law of segregation does not apply to trihybrid crosses.\nD. There are 64 possible genotypic combinations in the F2 generation.\nE. Each trait in the cross follows Mendelian dominant-recessive inheritance.\nF. A Punnett square for a trihybrid cross would have 16 squares.\nG. The number of phenotypic combinations observed depends on whether the genes exhibit complete dominance.\nH. Crossing AaBbCc × AaBbCc yields 8 different phenotypic classes under complete dominance.\nI. The phenotypic ratio is the same regardless of linkage between genes.\nJ. All offspring will display at least one dominant trait.","correctAnswer":"A, B, D, E, H","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_11","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"FRQ","difficulty":"Easy","question":"List 5 reasons why pea plants were a good choice for Mendel’s experiments.","correctAnswer":"Clear observable traits, short generation time, controlled pollination, fertile offspring, consistently passed on specific traits, easy to grow","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_12","event":"Designer Genes","subtopic":"Gene Expression","division":"C","type":"MCQ","difficulty":"Medium","question":"In the lac operon, what happens when lactose is present but glucose is not?","options":["The operon is turned off","Only the repressor is bound","The operon is fully activated","Rna polymerase is blocked"],"correctAnswer":"The operon is fully activated","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_13","event":"Designer Genes","subtopic":"Gene Expression","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following is a cis-regulatory element?","options":["Transcription factor","Enhancer","RNA polymerase","Ribosome"],"correctAnswer":"Enhancer","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_14","event":"Designer Genes","subtopic":"Gene Expression","division":"C","type":"MCQ","difficulty":"Medium","question":"Which mechanism is not typically used in eukaryotic gene regulation?","options":["DNA methylation","Alternative splicing","Operons","Histone modification"],"correctAnswer":"Operons","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_15","event":"Designer Genes","subtopic":"Gene Expression","division":"C","type":"FRQ","difficulty":"Medium","question":"What is an inducible system and why is it beneficial for the cell? Include 1 example of an inducible system.","correctAnswer":"Inducible system: gene expression that is normally off is turned on by the presence of an inducer. It helps to control gene expression, use resources efficiently, and adapt to environmental changes. Example: lac operon.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_16","event":"Designer Genes","subtopic":"Gene Expression","division":"C","type":"FRQ","difficulty":"Medium","question":"Is the following example an example of epistasis? In certain types of corn, kernel color is determined by 2 genes. Gene A decides if pigment is produced or not and Gene B decides what type of pigment is produced.","correctAnswer":"Yes, it is an example of epistasis.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_17","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"MCQ","difficulty":"Medium","question":"Nondisjunction during meiosis I results in gametes that:","options":["Are all normal","Have two copies of one chromosome or none at all","Have only one copy of each chromosome","Have no impact on offspring"],"correctAnswer":"Have two copies of one chromosome or none at all","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_18","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"FRQ","difficulty":"Hard","question":"Why does the risk of nondisjunction increase with maternal age?","correctAnswer":"Chromosome separation is less accurate as females age. Primary oocytes have been paused at prophase I for longer causing greater chance of mechanical or structural failure, and decreased DNA repair efficiency.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_19","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Easy","question":"What is the primary purpose of polymerase chain reaction (PCR)?","options":["Cut DNA at specific sequences","Separate DNA fragments by size","Make many copies of a DNA sequence","Determine the amino acid sequence of a protein"],"correctAnswer":"Make many copies of a DNA sequence","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_20","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Easy","question":"What makes Taq polymerase suitable for PCR?","options":["It’s the only enzyme that works on DNA","It is heat-resistant and remains active after high-temperature denaturation steps","It works only in bacteria","It creates sticky ends for cloning"],"correctAnswer":"It is heat-resistant and remains active after high-temperature denaturation steps","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_21","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following techniques allows scientists to edit genes at precise locations?","options":["PCR","Gel electrophoresis","CRISPR-Cas9","DNA ligase"],"correctAnswer":"CRISPR-Cas9","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_22","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"FRQ","difficulty":"Medium","question":"What are restriction enzymes and how are they used in genetic engineering?","correctAnswer":"Restriction enzymes cut DNA at specific sites. They are used in genetic engineering to cut and paste DNA in cloning and recombinant DNA construction.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_23","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"FRQ","difficulty":"Medium","question":"What is CRISPR-Cas9, and how is it different from earlier gene-editing techniques?","correctAnswer":"CRISPR-Cas9 is a gene editing tool derived from the bacterial immune system. Compared to older methods, it is simpler, cheaper, faster, and more precise.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_24","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"FRQ","difficulty":"Medium","question":"How does Sanger sequencing determine the sequence of DNA?","correctAnswer":"Sanger sequencing uses fluorescently labeled dideoxynucleotides (ddNTPs) that terminate DNA synthesis at specific bases. The resulting fragments are sorted by size using electrophoresis or capillary systems. A computer reads the colors and builds the DNA sequence.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_25","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following best describes Next-Generation Sequencing (NGS)?","options":["Sequencing one DNA fragment at a time","High-throughput, short-read sequencing of millions of fragments simultaneously","Real-time sequencing of single molecules","Based on chain-termination by dideoxynucleotides"],"correctAnswer":"High-throughput, short-read sequencing of millions of fragments simultaneously","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_26","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Easy","question":"What component in gel electrophoresis allows DNA fragments to move?","options":["pH gradient","Temperature gradient","Magnetic field","Electrical current"],"correctAnswer":"Electrical current","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_27","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Medium","question":"Which application is better suited for third-generation sequencing than traditional NGS?","options":["Whole-genome assembly of highly repetitive regions","Small-scale SNP detection","Gene expression microarrays","Protein sequencing"],"correctAnswer":"Whole-genome assembly of highly repetitive regions","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_28","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"MCQ","difficulty":"Hard","question":"What is the function of the origin recognition complex (ORC) in eukaryotic DNA replication?","options":["Synthesizes RNA primers","Loads helicase onto DNA","Binds replication origins to initiate pre-RC assembly","Unwinds DNA ahead of the replication fork"],"correctAnswer":"Binds replication origins to initiate pre-RC assembly","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_29","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"MCQ","difficulty":"Hard","question":"Which protein is responsible for helicase loading during the formation of the pre-replication complex (pre-RC)?","options":["DNA polymerase α","Cdc6 and Cdt1","Topoisomerase I","Ligase"],"correctAnswer":"Cdc6 and Cdt1","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_30","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"MCQ","difficulty":"Hard","question":"The MCM complex in eukaryotes functions as:","options":["The sliding clamp","A primase that adds RNA","A polymerase that extends primers","A helicase that unwinds DNA"],"correctAnswer":"A helicase that unwinds DNA","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_31","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"FRQ","difficulty":"Medium","question":"Why is it important that the pre-replication complex only assembles once per cell cycle?","correctAnswer":"To prevent re-replication which would cause DNA damage or genome instability","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_32","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"FRQ","difficulty":"Medium","question":"How can microarrays be used to find causes of cancer?","correctAnswer":"Flag abnormal gene expression","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_33","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"FRQ","difficulty":"Easy","question":"What is reverse transcription?","correctAnswer":"RNA is converted to DNA through reverse transcriptase","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_34","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Medium","question":"What does CRISPR use to find its DNA target?","options":["Guide RNA","Reverse transcriptase","Ribosome","DNA polymerase"],"correctAnswer":"Guide RNA","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_35","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Medium","question":"What is a guide RNA (gRNA) used for in CRISPR?","options":["To direct Cas9 to the correct DNA sequence","To create breaks in DNA","To code for Cas9","To translate proteins from edited genes"],"correctAnswer":"To direct Cas9 to the correct DNA sequence","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_36","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Medium","question":"Third-generation sequencing like Nanopore reads:","options":["Only RNA","Short fragments in parallel","Circular DNA only","Long DNA fragments in real-time"],"correctAnswer":"Long DNA fragments in real-time","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_37","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"MCQ","difficulty":"Hard","question":"T/F: Licensing of DNA replication origins occurs during the S phase to ensure that each origin fires exactly once per cell cycle.","options":["True","False"],"correctAnswer":"False","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_38","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"MCQ","difficulty":"Medium","question":"T/F: DNA ligase creates phosphodiester bonds between Okazaki fragments.","options":["True","False"],"correctAnswer":"True","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_39","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"MCQ","difficulty":"Medium","question":"T/F: DNA replication is bidirectional and semi-discontinuous, meaning both strands are synthesized continuously in opposite directions.","options":["True","False"],"correctAnswer":"False","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_40","event":"Designer Genes","subtopic":"Biotechnology","division":"C","type":"MCQ","difficulty":"Medium","question":"T/F: 3rd generation sequencing can detect epigenetic modifications like methylation.","options":["True","False"],"correctAnswer":"True","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_41","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"FRQ","difficulty":"Medium","question":"Labrador retrievers have fur colors controlled by 2 genes. For Gene B, a dominant B would result in black fur, and the recessive allele b would result in brown fur. For gene E, a dominant allele E would allow for Gene B to be expressed, and the recessive allele e would not allow for Gene B to be expressed resulting in yellow. What is the genotype of a yellow Labrador?","correctAnswer":"Any genotype with ee","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_42","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"FRQ","difficulty":"Easy","question":"What would be the coat color of a dog with genotype BBEe?","correctAnswer":"Black","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_43","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"FRQ","difficulty":"Medium","question":"If you cross BbEe dog with another BbEe dog, what is the phenotypic ratio of offspring?","correctAnswer":"9 black : 3 brown : 4 yellow","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_44","event":"Designer Genes","subtopic":"Mendelian Genetics","division":"C","type":"FRQ","difficulty":"Easy","question":"What type of epistasis does this example demonstrate?","correctAnswer":"Recessive","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_45","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"FRQ","difficulty":"Hard","question":"You are studying a eukaryotic cell line in which DNA replication is occurring abnormally, leading to regions of DNA being duplicated more than once per cell cycle. Explain the role of the MCM complex in DNA replication and how its activity is regulated during the cell cycle.","correctAnswer":"The MCM complex unwinds DNA at the replication fork, allowing replication to occur. It is loaded onto DNA during G1 and regulated through the activation at the start of the S phase in which MCM starts moving with the replication fork. Its reloading is then blocked until the next cell cycle.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_46","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"FRQ","difficulty":"Medium","question":"Contrast the initiation of replication in prokaryotes and eukaryotes.","correctAnswer":"In prokaryotes, there is typically one origin of replication, initiated through the binding of initiator proteins. Eukaryotes have multiple origins along their chromosomes, and initiation occurs through the assembly of the Origin Recognition complex, helicase loaders, and multiple regulatory steps.","year":2025,"tournament":"Scioly.org Summer Study Session"},
  {"id":"q_genes_2025_ssss_47","event":"Designer Genes","subtopic":"Cell Cycle & Replication","division":"C","type":"FRQ","difficulty":"Hard","question":"What is one way the cell ensures that each origin of replication only fires once during the cell cycle?","correctAnswer":"One way the cell prevents origins from firing more than once is by licensing origins only in the G1 phase. After replication begins, proteins involved in origin licensing are inhibited or removed to prevent re-licensing during S, G2, and M phases.","year":2025,"tournament":"Scioly.org Summer Study Session"}
,
  {"id":"q_dd_2025_diag_1a","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Easy","question":"Match the term with its definition: Eradication","correctAnswer":"Rinderpest no longer exists naturally in the world","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1b","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Easy","question":"Match the term with its definition: Vector","correctAnswer":"A mosquito","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1c","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Medium","question":"Match the term with its definition: Isolation","correctAnswer":"Separates sick people with a contagious disease from those who are not sick.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1d","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Medium","question":"Match the term with its definition: Quarantine","correctAnswer":"Used to separate and restrict the movement of people who are healthy but who may have been exposed to an infectious disease to see if they develop illness.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1e","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Medium","question":"Match the term with its definition: Public health approach","correctAnswer":"Funds are directed to an area few in healthcare resources so citizens can stay healthy","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1f","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Hard","question":"Match the term with its definition: Pathogenicity","correctAnswer":"The property of causing disease following infection","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1g","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Hard","question":"Match the term with its definition: Virulence","correctAnswer":"The property of causing severe disease","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1h","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Medium","question":"Match the term with its definition: Prophylaxis","correctAnswer":"Wearing a mask on the subway to avoid catching a cold","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1i","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Easy","question":"Match the term with its definition: Disease","correctAnswer":"Any harmful deviation from the normal structural or functional state of an organism.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1j","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Medium","question":"Match the term with its definition: Noscomial","correctAnswer":"Cipher catches a cold after staying at the hospital.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1k","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Medium","question":"Match the term with its definition: Syndromic surveillance","correctAnswer":"A local hospital monitors reports of patients coming in for sore throats.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1l","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Hard","question":"Match the term with its definition: Infectivity","correctAnswer":"The property of establishing infection after exposure","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_1m","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Easy","question":"Match the term with its definition: Agent","correctAnswer":"Staphylococcus aureus","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_2","event":"Disease Detectives","subtopic":"Laboratory & Diagnostics","division":"C","type":"MCQ","difficulty":"Medium","question":"Select the statement that describes PFGE (Pulsed-Field Gel Electrophoresis):","options":["An electric field is applied in one direction","Separates DNA based on size","Relies on the positive charge of phosphate","Samples are loaded at the positive end"],"correctAnswer":"Separates DNA based on size","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_3","event":"Disease Detectives","subtopic":"Study Design & Causal Inference","division":"C","type":"FRQ","difficulty":"Medium","question":"In Rothman's causal pies, a piece that appears in every pie (is always required for the disease) is called a:","correctAnswer":"Necessary cause","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_4","event":"Disease Detectives","subtopic":"Study Design & Causal Inference","division":"C","type":"MCQ","difficulty":"Easy","question":"In terms of Rothman’s pies, if COVID-19 virus must always be present for disease to occur, then it is a ____.","options":["Necessary cause","Sufficient cause","Critical cause","Component cause"],"correctAnswer":"Necessary cause","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_5","event":"Disease Detectives","subtopic":"Pathogens & Microbes","division":"C","type":"MCQ","difficulty":"Medium","question":"Which statement correctly describes a prion?","options":["Causes thousands of cases of CJD a year","Can be spread through droplet transmission","Also called TSEs","None of the above"],"correctAnswer":"Also called TSEs","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_6","event":"Disease Detectives","subtopic":"Study Design & Causal Inference","division":"C","type":"MCQ","difficulty":"Medium","question":"People consistently develop lung cancer after being exposed to secondhand smoke. Which step of the Bradford Hill Criteria does this fit?","options":["Specificity","Strength of association","Temporality","Coherence"],"correctAnswer":"Temporality","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_7","event":"Disease Detectives","subtopic":"Study Design & Causal Inference","division":"C","type":"MCQ","difficulty":"Medium","question":"On a DAG, if exposure to radioactive waste is one step upstream of cancer, what term best describes exposure to radioactive waste?","options":["Parent","Father","Mediator","Descendent"],"correctAnswer":"Parent","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_8","event":"Disease Detectives","subtopic":"Study Design & Causal Inference","division":"C","type":"MCQ","difficulty":"Medium","question":"If your occupation can lead to lung cancer, but your occupation also exposes you to secondhand smoke from your coworkers (which can lead to lung cancer), what term describes your occupation on a DAG?","options":["Confounding variable","Bidirectional","Mediator","Effect modifier"],"correctAnswer":"Confounding variable","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_9","event":"Disease Detectives","subtopic":"Outbreak Investigation","division":"C","type":"FRQ","difficulty":"Medium","question":"An outbreak of listeria has happened in the US! What might PulseNet do to help?","correctAnswer":"Determine which cases are related and collect samples","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_10","event":"Disease Detectives","subtopic":"Laboratory & Diagnostics","division":"C","type":"MCQ","difficulty":"Medium","question":"True or false: Traditional PCR (with taq polymerase) cannot be used on the COVID-19 virus.","options":["True","False"],"correctAnswer":"True","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_11","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"MCQ","difficulty":"Easy","question":"True or false: The Bradford Hill Criteria builds off of Evans’ Postulates.","options":["True","False"],"correctAnswer":"False","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_12","event":"Disease Detectives","subtopic":"Pathogens & Microbes","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the acronym that describes the favorable conditions for the growth of foodborne pathogens? Please list each letter and what it stands for.","correctAnswer":"FAT TOM: Food, Acidity, Time, Temperature, Oxygen, Moisture","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_13","event":"Disease Detectives","subtopic":"Disease Transmission","division":"C","type":"FRQ","difficulty":"Medium","question":"Phainon was the first to catch the flu in Okhema, but Mydei was the first patient Hyacine caught wind of in her investigation. Who is the primary case and who is the index case? What’s the difference between these two terms?","correctAnswer":"Phainon is the primary case; Mydei is the index case. The primary case is the first person to get a disease and introduce it, while the index case is the first person in an epidemiological study or the first documented patient.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_14","event":"Disease Detectives","subtopic":"Disease Transmission","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the difference between vaccine efficacy and vaccine efficiency? Which measure is usually lower?","correctAnswer":"Vaccine efficacy refers to a vaccine’s usefulness in clinical or ideal settings, while vaccine effectiveness (efficiency) measures usefulness in real-world settings. Vaccine effectiveness is usually lower.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_15","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"FRQ","difficulty":"Hard","question":"What are Koch’s postulates?","correctAnswer":"1. Microbe must be present in all cases of the disease, but not in healthy organisms. 2. Microbe must be isolated from diseased organism and grown in pure culture. 3. Cultured microorganism should cause disease when introduced into a healthy organism. 4. Microbe must be reisolated from inoculated, diseased experimental host and identified as identical to the original.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_16","event":"Disease Detectives","subtopic":"Pathogens & Microbes","division":"C","type":"FRQ","difficulty":"Hard","question":"Which of the following diseases do not fit Koch’s first postulate: COVID-19, Herpes, Tuberculosis, Typhoid fever.","correctAnswer":"COVID-19, Herpes, Typhoid fever","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_17a","event":"Disease Detectives","subtopic":"Epi-curves","division":"C","type":"FRQ","difficulty":"Easy","question":"Please state what type of epi-curve would best describe: A school cafeteria serves contaminated food for a week.","correctAnswer":"Point-source","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_17b","event":"Disease Detectives","subtopic":"Epi-curves","division":"C","type":"FRQ","difficulty":"Easy","question":"Please state what type of epi-curve would best describe: A highly contagious disease spreads from person to person, breaking out in a previously unexposed community.","correctAnswer":"Propagated","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_17c","event":"Disease Detectives","subtopic":"Epi-curves","division":"C","type":"FRQ","difficulty":"Easy","question":"Please state what type of epi-curve would best describe: A river next to a city has contained toxins for many years.","correctAnswer":"Continuous common source","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_18","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the difference between a syndrome and a disease?","correctAnswer":"A disease usually has a defining cause, distinguishing symptoms and treatments, while a syndrome is a group of symptoms that may not always have a definite cause","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_19a","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe what level of prevention is being utilized: Gepard recently dislocated his kneecap, and required surgery to recover. Now, he is going to physical therapy to recover.","correctAnswer":"Tertiary","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_19b","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Easy","question":"Describe what level of prevention is being utilized: To prevent infection by the memetic slumbernana virus, Mr. Reca goes to get vaccinated.","correctAnswer":"Primary","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_19c","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Hard","question":"Describe what level of prevention is being utilized: To prevent future outbreaks of cold-related illnesses, Bronya mandates that every business have working heaters.","correctAnswer":"Primordial","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_19d","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Hard","question":"Describe what level of prevention is being utilized: Sadly, Sunday has been hit by a train and is now in the ICU. The doctors only recommend necessary procedures and painkillers.","correctAnswer":"Quarternary","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_19e","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Easy","question":"Describe what level of prevention is being utilized: Ica hopes to mitigate her chances of getting diabetes, so she regularly goes to the gym.","correctAnswer":"Primary","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_1","event":"Disease Detectives","subtopic":"Outbreak Investigation","division":"C","type":"FRQ","difficulty":"Medium","question":"Construct a case definition for an E. coli outbreak following a picnic in Gru's backyard on June 25th (42 minions sick by July 2nd).","correctAnswer":"Symptoms of E. coli in minions who attended a picnic in Gru's backyard between 6/25 and 7/2.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_2","event":"Disease Detectives","subtopic":"Outbreak Investigation","division":"C","type":"FRQ","difficulty":"Easy","question":"Why is it important to have a case definition?","correctAnswer":"To ensure that cases are consistently diagnosed and classified during an outbreak investigation.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_3","event":"Disease Detectives","subtopic":"Study Design & Causal Inference","division":"C","type":"FRQ","difficulty":"Medium","question":"Agnes claims that Margo is conducting a cohort study, while Edith claims Margo is conducting a case-control study. Who is correct?","correctAnswer":"Edith is correct, Margo is conducting a case-control study.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_4","event":"Disease Detectives","subtopic":"Study Design & Causal Inference","division":"C","type":"FRQ","difficulty":"Easy","question":"Margo sent out a survey to all the minions that attended the picnic, asking them to report any signs of illness. What type of study is this?","correctAnswer":"A cross-sectional study","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_6","event":"Disease Detectives","subtopic":"Biostatistics & Risk Measures","division":"C","type":"FRQ","difficulty":"Hard","question":"Calculate the appropriate measure of risk (Odds Ratio) for the Fruit bowl (Ate and sick: 38, Ate and well: 13, Didn't eat and sick: 4, Didn't eat and well: 45).","correctAnswer":"33.75","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_6b","event":"Disease Detectives","subtopic":"Biostatistics & Risk Measures","division":"C","type":"FRQ","difficulty":"Hard","question":"Calculate the appropriate measure of risk (Odds Ratio) for the Charcuterie board (Ate and sick: 17, Ate and well: 23, Didn't eat and sick: 25, Didn't eat and well: 35).","correctAnswer":"1.03","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_6c","event":"Disease Detectives","subtopic":"Biostatistics & Risk Measures","division":"C","type":"FRQ","difficulty":"Hard","question":"Calculate the appropriate measure of risk (Odds Ratio) for the Burgers (Ate and sick: 24, Ate and well: 52, Didn't eat and sick: 18, Didn't eat and well: 6).","correctAnswer":"0.02","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_7","event":"Disease Detectives","subtopic":"Biostatistics & Risk Measures","division":"C","type":"FRQ","difficulty":"Medium","question":"Which food was likely the cause? Interpret the statistic that led you to this conclusion.","correctAnswer":"The fruit bowl; minions who ate the fruit bowl were 33.75 times as likely to be sick compared to those who didn’t.","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_8a","event":"Disease Detectives","subtopic":"Outbreak Investigation","division":"C","type":"FRQ","difficulty":"Medium","question":"Determine whether the patient is a confirmed, possible, or probable case: Stuart has severe stomach cramping but no other symptoms; he has not received his test results yet.","correctAnswer":"Possible case","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_8b","event":"Disease Detectives","subtopic":"Outbreak Investigation","division":"C","type":"FRQ","difficulty":"Easy","question":"Determine whether the patient is a confirmed, possible, or probable case: Peter tested positive for E. coli.","correctAnswer":"Confirmed case","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s2_8c","event":"Disease Detectives","subtopic":"Outbreak Investigation","division":"C","type":"FRQ","difficulty":"Medium","question":"Determine whether the patient is a confirmed, possible, or probable case: Dave is experiencing severe diarrhea and vomiting and is awaiting his test results.","correctAnswer":"Probable case","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s3_1","event":"Disease Detectives","subtopic":"Biostatistics & Risk Measures","division":"C","type":"FRQ","difficulty":"Hard","question":"Calculate the sensitivity and specificity of a test. True positive: 238. False positive: 12. False negative: 36. True negative: 150.","correctAnswer":"Sensitivity = 0.87, Specificity = 0.93","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s3_2","event":"Disease Detectives","subtopic":"Biostatistics & Risk Measures","division":"C","type":"FRQ","difficulty":"Hard","question":"Calculate the positive predictive value and the negative predictive value of a test. True positive: 238. False positive: 12. False negative: 36. True negative: 150.","correctAnswer":"PPV = 0.95, NPV = 0.81","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s3_3","event":"Disease Detectives","subtopic":"Study Design & Causal Inference","division":"C","type":"FRQ","difficulty":"Medium","question":"Margo and Agnes work together to talk to the ill minions and gather information about possible exposures. They do establish a set of questions to ask. What kind of bias might this introduce?","correctAnswer":"Interviewer bias","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s3_4","event":"Disease Detectives","subtopic":"Outbreak Investigation","division":"C","type":"FRQ","difficulty":"Medium","question":"What step of outbreak investigation are Margo and Agnes on when they find minions and collect information from them?","correctAnswer":"Step 5: Find cases systematically and record information","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s3_5","event":"Disease Detectives","subtopic":"Outbreak Investigation","division":"C","type":"FRQ","difficulty":"Medium","question":"After collecting sufficient information, Edith puts in place a quarantine mandate for all exposed minions. What step of outbreak investigation is this?","correctAnswer":"Step 11: Implement control and prevention measures","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s3_6","event":"Disease Detectives","subtopic":"Outbreak Investigation","division":"C","type":"FRQ","difficulty":"Medium","question":"Given that a disease travels via droplets, what are three other prevention strategies one should implement aside from quarantine?","correctAnswer":"Make the minions wear masks, implement social distancing, sanitize","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s4_1","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"FRQ","difficulty":"Easy","question":"Who conducted research on the causes behind cholera?","correctAnswer":"John Snow","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s4_2","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"FRQ","difficulty":"Easy","question":"Who discovered that limes could prevent scurvy?","correctAnswer":"James Lind","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s4_3","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"FRQ","difficulty":"Medium","question":"Who went far with viral statistics and surveillance?","correctAnswer":"William Farr","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s4_4","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"FRQ","difficulty":"Easy","question":"Who was the first person identified as an asymptomatic carrier of typhoid fever?","correctAnswer":"Mary Mallon","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s4_5","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"FRQ","difficulty":"Easy","question":"Who invented pasteurization?","correctAnswer":"Louis Pasteur","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s4_6","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"FRQ","difficulty":"Medium","question":"Who was the first to propose a basic form of germ theory?","correctAnswer":"Girolamo Fracastoro","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s4_7","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"FRQ","difficulty":"Medium","question":"What does HIPAA stand for, and when was it introduced in the US?","correctAnswer":"Health Insurance Portability and Accountability Act; 1996","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s4_8","event":"Disease Detectives","subtopic":"History of Epidemiology","division":"C","type":"MCQ","difficulty":"Medium","question":"The Framingham study studied…","options":["Stomach cancer","Ulcers","Lung cancer","Cardiovascular disease"],"correctAnswer":"Cardiovascular disease","year":2025,"tournament":"Diagnostic"},
  {"id":"q_dd_2025_diag_s4_9","event":"Disease Detectives","subtopic":"Vocabulary & Concepts","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the difference between HIV and AIDS?","correctAnswer":"HIV is a virus that weakens the immune system. AIDS is a resulting condition; it is the final and most severe stage of an HIV infection.","year":2025,"tournament":"Diagnostic"}
,
  {"id":"q_dp_2025_ssss_1","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"MCQ","difficulty":"Medium","question":"What causes spring tides to occur?","options":["The Earth is at its farthest from the Sun","The Moon and Sun are at 90 degrees relative to Earth","The Sun, Moon, and Earth are aligned in a straight line","Strong surface winds"],"correctAnswer":"The Sun, Moon, and Earth are aligned in a straight line","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_2","event":"Dynamic Planet","subtopic":"Marine Geology & Plate Tectonics","division":"C","type":"MCQ","difficulty":"Easy","question":"What geological process is responsible for the creation of new oceanic crust?","options":["Erosion of continental shelves","Deposition of biogenous sediments","Volcanic activity at mid-ocean ridges","Downward movement at subduction zones"],"correctAnswer":"Volcanic activity at mid-ocean ridges","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_3","event":"Dynamic Planet","subtopic":"Ocean Chemistry & Composition","division":"C","type":"MCQ","difficulty":"Medium","question":"What best defines the pycnocline in the ocean?","options":["A layer where water temperature changes rapidly with depth","A zone of constant salinity between surface and deep water","A region where dissolved oxygen is at its maximum","A layer where water density increases rapidly with depth"],"correctAnswer":"A layer where water density increases rapidly with depth","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_4","event":"Dynamic Planet","subtopic":"Ocean Chemistry & Composition","division":"C","type":"MCQ","difficulty":"Easy","question":"The carbonate buffering system helps regulate ocean:","options":["pH","Salinity","Density","Oxygen content"],"correctAnswer":"pH","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_5","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"MCQ","difficulty":"Medium","question":"Longshore currents are created by:","options":["Earth's rotation","Waves approaching the shore at an angle","Wind blowing directly offshore","Differences in salinity"],"correctAnswer":"Waves approaching the shore at an angle","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_6","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"MCQ","difficulty":"Medium","question":"The SOFAR channel allows sound to:","options":["Travel slowly","Echo vertically","Travel long distances","Escape to the surface"],"correctAnswer":"Travel long distances","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_7","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"MCQ","difficulty":"Medium","question":"During El Niño, which occurs?","options":["Stronger trade winds","Warmer waters near South America","cooler water in the eastern Pacific","Increased upwelling"],"correctAnswer":"Warmer waters near South America","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_8","event":"Dynamic Planet","subtopic":"Ocean Chemistry & Composition","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following sediments is made mostly of land-derived material?","options":["Biogenous sediment","Cosmogenous sediment","Hydrogenous sediment","Terrigenous sediment"],"correctAnswer":"Terrigenous sediment","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_9","event":"Dynamic Planet","subtopic":"Ocean Biology & Ecology","division":"C","type":"MCQ","difficulty":"Medium","question":"What process is responsible for the removal of CO2 from surface waters and its eventual storage in the deep ocean?","options":["Surface wind mixing","The biological pump","El Niño","Thermocline formation"],"correctAnswer":"The biological pump","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_10","event":"Dynamic Planet","subtopic":"Marine Geology & Plate Tectonics","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following features forms at divergent plate boundaries under the ocean?","options":["Ocean trench","Subduction zone","Mid-ocean ridge","Island arc"],"correctAnswer":"Mid-ocean ridge","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_11","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"MCQ","difficulty":"Easy","question":"The Coriolis effect in the Northern Hemisphere causes moving air/water to:","options":["Deflect to the right","Deflect to the left","Move vertically","Remain unaffected"],"correctAnswer":"Deflect to the right","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_12","event":"Dynamic Planet","subtopic":"Ocean Chemistry & Composition","division":"C","type":"MCQ","difficulty":"Easy","question":"What primarily causes thermohaline circulation in the global ocean?","options":["Wind speed and direction","Tidal forces from the Moon","Seafloor Spreading","Temperature and salinity differences"],"correctAnswer":"Temperature and salinity differences","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_13","event":"Dynamic Planet","subtopic":"Ocean Chemistry & Composition","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following is the main long-term source of salt in the ocean?","options":["Precipitation of minerals from the air","Subduction of oceanic crust","Erosion and chemical weathering of continental rocks","Dissolved gases from hydrothermal vents"],"correctAnswer":"Erosion and chemical weathering of continental rocks","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_14","event":"Dynamic Planet","subtopic":"Ocean Biology & Ecology","division":"C","type":"MCQ","difficulty":"Medium","question":"Which region of the ocean is most likely to have the highest rate of biological productivity?","options":["Coastal regions with frequent upwelling","The abyssal plains of the Pacific Ocean","The centers of subtropical gyres","Mid-ocean ridges in tectonically active zones"],"correctAnswer":"Coastal regions with frequent upwelling","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_15","event":"Dynamic Planet","subtopic":"Ocean Biology & Ecology","division":"C","type":"MCQ","difficulty":"Easy","question":"Which ocean zone receives enough sunlight for photosynthesis and supports most marine life?","options":["Bathypelagic zone","Abyssopelagic zone","Epipelagic zone","Hadalpelagic zone"],"correctAnswer":"Epipelagic zone","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_16","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"MCQ","difficulty":"Medium","question":"Which ocean zone is characterized by nearly constant cold temperatures and high pressure?","options":["Epipelagic zone","Mesopelagic zone","Neritic zone","Bathypelagic zone"],"correctAnswer":"Bathypelagic zone","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_17","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"MCQ","difficulty":"Hard","question":"Which of the following best describes the Ekman spiral?","options":["A surface phenomenon where waves break on the shore","The downward and horizontal deflection of ocean water due to wind and Coriolis forces","The process of deep ocean water formation in polar regions","The vertical mixing of seawater caused by tide"],"correctAnswer":"The downward and horizontal deflection of ocean water due to wind and Coriolis forces","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_18","event":"Dynamic Planet","subtopic":"Ocean Chemistry & Composition","division":"C","type":"MCQ","difficulty":"Medium","question":"What do oceanographers measure using Argo floats?","options":["Ocean current speeds only at the surface","Vertical profiles of salinity, temperature, and pressure","Chemical composition of marine sediments","Distribution of marine life"],"correctAnswer":"Vertical profiles of salinity, temperature, and pressure","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_19","event":"Dynamic Planet","subtopic":"Marine Geology & Plate Tectonics","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following describes a major feature of a passive continental margin?","options":["Active subduction zones","Frequent volcanic activity","Wide continental shelf","Deep ocean trenches nearby"],"correctAnswer":"Wide continental shelf","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_20","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"MCQ","difficulty":"Medium","question":"What factor most strongly influences the speed of deep ocean currents?","options":["Temperature and salinity differences","Tidal bulges","Seafloor topography","Wind-driven gyres"],"correctAnswer":"Temperature and salinity differences","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_21","event":"Dynamic Planet","subtopic":"Marine Geology & Plate Tectonics","division":"C","type":"MCQ","difficulty":"Easy","question":"Which plate boundary type is least likely to produce volcanic activity?","options":["Convergent","Divergent","Transform","Subduction"],"correctAnswer":"Transform","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_22","event":"Dynamic Planet","subtopic":"Marine Geology & Plate Tectonics","division":"C","type":"MCQ","difficulty":"Easy","question":"What is the composition of most oceanic crust?","options":["Granite","Andesite","Sandstone","Basalt"],"correctAnswer":"Basalt","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_23","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the main cause of thermohaline circulation in the ocean?","correctAnswer":"The main cause of thermohaline circulation in the ocean is differences in water density, which are driven by variations in temperature and salinity.","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_24","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Medium","question":"What is SONAR used for?","correctAnswer":"SONAR, which stands for Sound Navigation and Ranging, is used to map the seafloor and detect underwater objects by sending out sound waves and measuring how long it takes for them to bounce back.","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_25","event":"Dynamic Planet","subtopic":"Marine Geology & Plate Tectonics","division":"C","type":"FRQ","difficulty":"Medium","question":"Why are the oldest oceanic rocks much younger than the oldest continental rocks?","correctAnswer":"Oceanic rocks are much younger than continental rocks because new ocean crust is constantly being formed at mid-ocean ridges and destroyed at subduction zones, while continental crust is older and more stable since it is not replaced as frequently.","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_26","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the difference between a guyot and a seamount?","correctAnswer":"A seamount is an underwater volcanic mountain with a pointed peak, while a guyot is a flat-topped underwater mountain that was once above sea level and eroded before sinking.","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_27","event":"Dynamic Planet","subtopic":"Ocean Biology & Ecology","division":"C","type":"FRQ","difficulty":"Medium","question":"What is upwelling and why is it important for marine ecosystems?","correctAnswer":"Upwelling is the process where deep, cold, nutrient-rich water rises to the surface. It is important because it brings nutrient-rich water to the surface, supporting plankton, fish, and other marine life, which helps sustain highly productive ecosystems.","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_28","event":"Dynamic Planet","subtopic":"Ocean Chemistry & Composition","division":"C","type":"FRQ","difficulty":"Hard","question":"Explain why the salinity of ocean water can vary between different regions.","correctAnswer":"The salinity of ocean water can vary due to several factors (must list at least one factor): evaporation increases salinity by removing water and leaving salt behind; precipitation and freshwater input from rivers decrease salinity by diluting the salt content; freezing of seawater increases salinity since salt is left behind in the water; melting of sea ice lowers salinity by adding fresh water; and water movement, such as ocean currents, can redistribute salty or less salty water between regions.","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_29","event":"Dynamic Planet","subtopic":"Marine Geology & Plate Tectonics","division":"C","type":"FRQ","difficulty":"Medium","question":"What causes the formation of oceanic trenches?","correctAnswer":"Oceanic trenches are formed at convergent plate boundaries when one tectonic plate is forced beneath another through subduction, creating a deep trench in the ocean floor.","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_30","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the name of the circular ocean current system found in major ocean basins?","correctAnswer":"A gyre","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_31","event":"Dynamic Planet","subtopic":"Physical Oceanography","division":"C","type":"FRQ","difficulty":"Medium","question":"How does the Coriolis effect influence the direction of global ocean circulation patterns?","correctAnswer":"The Coriolis effect, caused by Earth’s rotation, influences global ocean circulation by deflecting currents to the right in the Northern Hemisphere and to the left in the Southern Hemisphere.","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_32","event":"Dynamic Planet","subtopic":"Marine Geology & Plate Tectonics","division":"C","type":"FRQ","difficulty":"Hard","question":"Describe how transform boundaries affect the seafloor and give one example of an underwater transform fault.","correctAnswer":"Transform boundaries affect the seafloor by causing two tectonic plates to slide past each other horizontally, which creates faults and earthquakes along the boundary without creating or destroying crust. Examples: San Andreas Fault, Romanche Transform Fault, Alpine Fault, Húsavík-Flatey Fault, Dead Sea Transform Fault, Clifford Transform Fault, Galapagos Transform Fault, Molokai Transform Fault, Queen Charlotte Transform Fault, North Anatolian Fault, Sagaing Fault, etc.","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_33","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the ocean floor feature that is the shallow, gently sloping area adjacent to a continent (depth 0 to slightly below).","correctAnswer":"Continental Shelf","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_34","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the ocean floor feature that is the steeply sloping area connecting the continental shelf to the deep ocean floor.","correctAnswer":"Continental Slope","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_35","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the ocean floor feature that is a flat, featureless plain in the deep ocean.","correctAnswer":"Abyssal Plain","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_36","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the ocean floor feature that is a small, sediment-covered hill on the abyssal plain.","correctAnswer":"Abyssal Hill","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_37","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the ocean floor feature that is a large underwater volcanic mountain with a pointed peak.","correctAnswer":"Seamount","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_38","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the ocean floor feature that is a deep, narrow depression in the seafloor formed by subduction.","correctAnswer":"Ocean Trench","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_39","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the ocean floor feature that is a volcanic mountain that breaks the ocean surface.","correctAnswer":"Volcanic Island","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_40","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the ocean pelagic zone from 0 to 200 meters depth.","correctAnswer":"Epipelagic / Sunlight Zone","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_41","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the ocean pelagic zone from 200 to 1000 meters depth.","correctAnswer":"Mesopelagic / Twilight / Midwater Zone","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_42","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the ocean pelagic zone from 1000 to 4000 meters depth.","correctAnswer":"Bathypelagic / Midnight Zone","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_43","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the ocean pelagic zone from 4000 to 6000 meters depth.","correctAnswer":"Abyssopelagic Zone","year":2025,"tournament":"SSSS"},
  {"id":"q_dp_2025_ssss_44","event":"Dynamic Planet","subtopic":"Ocean Geography & Zones","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the ocean pelagic zone from 6000 to 10000 meters depth.","correctAnswer":"Hadalpelagic Zone","year":2025,"tournament":"SSSS"}
