  {"id":"q_for_2025_ssss_pow1","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the powder: Soluble, pH 4, NR with HCl, bubbles with Benedict's, green flame.","correctAnswer":"H3BO4 (Boric Acid)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_pow2","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the powder: Soluble, pH 7, NR with HCl, blue with Benedict's, yellow flame.","correctAnswer":"NaCl (Sodium Chloride)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_pow3","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the powder: Soluble, pH 7, NR with HCl, blue with Benedict's, purple flame.","correctAnswer":"KCl (Potassium Chloride)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_pow4","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the powder: Insoluble, pH 6, bubbles with HCl, blue with Benedict's, orange flame.","correctAnswer":"CaCO3 (Calcium Carbonate)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_pow5","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the powder: Soluble, pH 8, NR with HCl, does not dissolve with NaOH, blue with Benedict's, yellow flame.","correctAnswer":"NaC2H3O2 (Sodium Acetate)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_pow6","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the powder: Insoluble, pH 10, bubbles with HCl, clear with I2, yellow flame.","correctAnswer":"Na2CO3 (Sodium Carbonate)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_pow7","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the powder: Soluble, pH 6, NR with HCl, smells when mixed with NaOH, dark with Benedict's, light green flame.","correctAnswer":"NH4Cl (Ammonium Chloride)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_chem1","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Hard","question":"Give the net ionic equation of Sodium Hydroxide and Calcium Nitrate.","correctAnswer":"2OH- (aq) + Ca2+ (aq) -> Ca(OH)2 (s)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_chem2","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Give the molecular explanation as to why flame colors occur.","correctAnswer":"When the substance is heated, electrons get excited into a higher energy level. When the electrons return to the ground energy level, a wave is released that can be seen.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_chem3","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Name a process that can be used to produce Sodium Carbonate.","correctAnswer":"Solvay Process or Leblanc Process","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_chem4","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain the molecular difference of sucrose and glucose.","correctAnswer":"Sucrose is a disaccharide composed of glucose and fructose bonded together.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_chem5","event":"Forensics","subtopic":"Qualitative Analysis","division":"C","type":"FRQ","difficulty":"Hard","question":"Give a full balanced reaction of a gas evolution reaction that occurs in forensics.","correctAnswer":"Any Carbonate + HCl -> Salt + CO2 + H2O (e.g., CaCO3 + 2HCl -> CaCl2 + CO2 + H2O)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_plasA","event":"Forensics","subtopic":"Polymers","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the plastic based on float tests (F = floats, S = sinks): Vegetable Oil (F), 46% Isopropyl (F), Water (F), 10% NaCl (F), 25% NaCl (F), Saturated NaCl (F).","correctAnswer":"PP (Polypropylene)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_plasB","event":"Forensics","subtopic":"Polymers","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the plastic based on float tests (F = floats, S = sinks): Vegetable Oil (S), 46% Isopropyl (S), Water (S), 10% NaCl (F), 25% NaCl (F), Saturated NaCl (F).","correctAnswer":"PS (Polystyrene)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_plasC","event":"Forensics","subtopic":"Polymers","division":"C","type":"FRQ","difficulty":"Hard","question":"Identify the plastic based on float tests (F = floats, S = sinks): Vegetable Oil (S), 46% Isopropyl (S), Water (S), 10% NaCl (S), 25% NaCl (F), Saturated NaCl (F).","correctAnswer":"PMMA (Polymethyl Methacrylate)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_plasD","event":"Forensics","subtopic":"Polymers","division":"C","type":"FRQ","difficulty":"Hard","question":"Identify the plastic based on float tests (F = floats, S = sinks): Vegetable Oil (S), 46% Isopropyl (S), Water (S), 10% NaCl (S), 25% NaCl (S), Saturated NaCl (F).","correctAnswer":"PC (Polycarbonate)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_plas1","event":"Forensics","subtopic":"Polymers","division":"C","type":"FRQ","difficulty":"Medium","question":"What forensics plastic reacts to the Beilstein wire test and why?","correctAnswer":"PVC; the presence of chloride causes a green flame.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_plas2","event":"Forensics","subtopic":"Polymers","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the name of the first synthetic plastic produced in 1907?","correctAnswer":"Bakelite","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_plas3","event":"Forensics","subtopic":"Polymers","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the role of a plasticizer in polymers?","correctAnswer":"They create increased space between polymer chains, which makes the plastics more soft and pliable.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_hair1","event":"Forensics","subtopic":"Hairs & Fibers","division":"C","type":"FRQ","difficulty":"Easy","question":"What percent of hairs on a human head are currently in the telogen phase?","correctAnswer":"10 to 15%","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_hair2","event":"Forensics","subtopic":"Miscellaneous","division":"C","type":"FRQ","difficulty":"Easy","question":"Describe Locard’s Exchange Principle.","correctAnswer":"At any crime scene, there will be a transfer of evidence.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_hair3","event":"Forensics","subtopic":"Hairs & Fibers","division":"C","type":"FRQ","difficulty":"Medium","question":"What does the presence of a follicular tag on a hair indicate?","correctAnswer":"The hair was ripped or forcibly pulled out.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_hair4","event":"Forensics","subtopic":"Hairs & Fibers","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the difference between eumelanin and pheomelanin in hair?","correctAnswer":"Eumelanin gives a brown/black color, while pheomelanin gives an orange/yellow color.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_blood1","event":"Forensics","subtopic":"Blood","division":"C","type":"FRQ","difficulty":"Medium","question":"AB- blood was found on the scene. Suspects have B+, A+, O-, and O+. What does this indicate?","correctAnswer":"This cannot be used as evidence against any of the suspects since none have AB- blood.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_blood2","event":"Forensics","subtopic":"Blood","division":"C","type":"FRQ","difficulty":"Medium","question":"If the mother has blood type A and the Father has blood type AB, what are the possible blood type(s) of the child?","correctAnswer":"A, B, or AB","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_fib1","event":"Forensics","subtopic":"Polymers","division":"C","type":"FRQ","difficulty":"Medium","question":"What liquid can dissolve plant fibers?","correctAnswer":"Bleach (Sodium Hypochlorite)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_fib2","event":"Forensics","subtopic":"Polymers","division":"C","type":"FRQ","difficulty":"Hard","question":"What company invented spandex in 1959?","correctAnswer":"DuPont Chemical Company","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_fp1","event":"Forensics","subtopic":"Fingerprints","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the name of the study of fingerprints?","correctAnswer":"Dactyloscopy","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_fp2","event":"Forensics","subtopic":"Fingerprints","division":"C","type":"FRQ","difficulty":"Medium","question":"When do fingerprints develop in humans?","correctAnswer":"15-20 weeks in the womb","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_fp3","event":"Forensics","subtopic":"Fingerprints","division":"C","type":"FRQ","difficulty":"Hard","question":"Name a genetic condition that results in a lack of fingerprints.","correctAnswer":"Adermatoglyphia, NFJS (Naegeli-Franceschetti-Jadassohn syndrome), or DPR (Dermatopathia pigmentosa reticularis)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_fp4","event":"Forensics","subtopic":"Fingerprints","division":"C","type":"FRQ","difficulty":"Medium","question":"When would ninhydrin be used to develop fingerprints?","correctAnswer":"On porous surfaces like prints on paper.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_misc1","event":"Forensics","subtopic":"Miscellaneous","division":"C","type":"FRQ","difficulty":"Easy","question":"Name a Miranda Right.","correctAnswer":"You have the right to remain silent, anything you say can and will be used against you in a court of law, you have the right to an attorney, etc.","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_misc2","event":"Forensics","subtopic":"Miscellaneous","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the study of pollen called?","correctAnswer":"Palynology","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_misc3","event":"Forensics","subtopic":"Miscellaneous","division":"C","type":"FRQ","difficulty":"Medium","question":"Name Snell’s Law.","correctAnswer":"n1 * sin(θ1) = n2 * sin(θ2)","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_misc4","event":"Forensics","subtopic":"Miscellaneous","division":"C","type":"FRQ","difficulty":"Medium","question":"If a sample of soil is composed of 20% silt, 30% clay, and 50% sand, what is the soil type?","correctAnswer":"Sandy Clay Loam","year":2025,"tournament":"SSSS"},
  {"id":"q_for_2025_ssss_anal1","event":"Forensics","subtopic":"Analysis","division":"C","type":"FRQ","difficulty":"Hard","question":"Provide an analysis based on the evidence collected at the crime scene. Suspects: Brooklyn Bridges (B+, cotton denim, styrofoam cup/PS), Goldie Gate (A+, cotton/polyester lab coat, PP utensils, NaCl diet), London Larson (O-, wool sweater, pet squirrels, orange bottle/PP, LiCl), Pearl Peterson (O+, PVC piping, horseback riding, PC glasses, linen shirt). Evidence: Boric Acid, Salt, Potassium Chloride, PP plastic, Human hair, Spandex fiber, AB- blood.","correctAnswer":"Conclusion: It is likely none of the suspects committed the crime.\nEvidence: Boric acid, salt, and KCl could indicate Goldie Gate (due to lab equipment) or GG/BB because of salt. PP was found, which could indicate GG or LL, but this is not conclusive. Human hair was found, but all suspects are human. Spandex was found but no suspect wore spandex. AB- blood does not match any suspect. Most suspects did not have strong means, motives, or opportunity. Lack of individual evidence (DNA/fingerprints), mostly class evidence. There is not enough evidence to indicate any one person.","year":2025,"tournament":"SSSS"}
,
  {"id":"q_pm_2025_ssss_1_1","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"How do proteins maximize the strength of their hydrophobic interactions?","correctAnswer":"By placing hydrophobic interactions between nonpolar groups and minimizing interactions with water.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_2","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"What two amino acids don't form alpha helices easily and why?","correctAnswer":"Proline and Glycine. Proline is too rigid and has no rotation, while glycine is too small and flexible.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_3","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"How many amino acids residues are there per turn of an alpha helix? How many angstroms in width is this?","correctAnswer":"3.6 residues per turn; 5.4 Angstroms in width.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_4","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"How does hydrogen bonding in an alpha helix work?","correctAnswer":"Hydrogen bonding occurs between every 4th amino acid in order to coil and form a tight helix.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_5","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Easy","question":"What amino acid has the highest tendency to form a helix?","correctAnswer":"Alanine","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_6","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"Which 2 amino acids are solely ketogenic?","correctAnswer":"Leucine and Lysine","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_7","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"What types of amino acids are found in the middle of Beta-sheets?","correctAnswer":"Large aromatic amino acids and Beta-branched amino acids (e.g. Tyrosine, Phenylalanine, Tryptophan, Threonine, Valine, Isoleucine).","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_8","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the relationship between Ka and Kd? What is the relationship between Kd and the affinity of ligands for a protein?","correctAnswer":"Kd is the reciprocal of Ka. A lower Kd value means a higher affinity of a ligand for a protein (and vice versa).","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_9","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"How do enzymes catalyze reactions effectively?","correctAnswer":"By orienting substrates to minimize entropy, causing the desolvation of the water shell, and using induced fit/functional group arrangement.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_10","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Hard","question":"Derive the Michaelis-Menten equation using the steady-state assumption as a starting point.","correctAnswer":"E + S <-> [ES] -> E + P. Rate of ES formation = Rate of ES breakdown. Let [Et] be total enzyme. k1([Et] - [ES])[S] = k-1[ES] + k2[ES]. Define Km = (k2+k-1)/k1. Solving for [ES] yields [ES] = ([Et][S])/([S] + Km). Using V0 = k2[ES], we get V0 = (k2[Et][S])/(Km + [S]). Assuming Vmax = k2[Et], V0 = (Vmax[S])/(Km + [S]).","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_11","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Hard","question":"Describe the titration curve for histidine, including the approximate pKa values of its ionizable groups.","correctAnswer":"Histidine has three ionizable groups: the carboxyl group (pK1 ≈ 1.8), the R-group/imidazole ring (pK2 ≈ 6.0), and the amino group (pK3 ≈ 9.3). The isoelectric point (pI) is approximately 7.6.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_12a","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Easy","question":"RNA and DNA are two important nucleic acids in eukaryotes. Identify how the sugar ribose differs from deoxyribose.","correctAnswer":"Ribose has an additional 2' OH (hydroxyl) group that deoxyribose lacks.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_12b","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"What are the implications of the structural difference between ribose and deoxyribose with regards to the stability of RNA and DNA?","correctAnswer":"The extra hydroxyl group allows for self-catalyzed RNA hydrolysis which cleaves the phosphodiester bond in the backbone, making RNA less stable than DNA (alkaline hydrolysis).","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_12c","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Hard","question":"Describe the reaction mechanism by which self-catalyzed RNA hydrolysis occurs.","correctAnswer":"Under alkaline conditions (deprotonation), the deprotonated 2' OH acts as a nucleophile that attacks the phosphorus atom, which cleaves the phosphodiester bond that holds the sugar-phosphate backbone.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_1_12d","event":"Protein Modeling","subtopic":"Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"What amino acids preferentially bind to DNA and what structures are they commonly found in?","correctAnswer":"Arginine and Lysine; they are commonly found in Histones.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_2_1","event":"Protein Modeling","subtopic":"CRISPR","division":"C","type":"FRQ","difficulty":"Easy","question":"Where is CRISPR-CAS9 naturally found and what is its purpose?","correctAnswer":"Found in bacteria/archaea as an adaptive immunity defense mechanism against bacteriophages.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_2_2","event":"Protein Modeling","subtopic":"CRISPR","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the PAM sequence and why is it important?","correctAnswer":"It is the Protospacer Adjacent Motif, a few nucleotides downstream of the cut site. No cleavage can be made if this sequence is absent.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_2_3","event":"Protein Modeling","subtopic":"CRISPR","division":"C","type":"FRQ","difficulty":"Medium","question":"What are the two possible repair pathways that might be activated after Cas9 cleaves the DNA?","correctAnswer":"NHEJ (Non-Homologous End Joining) and HDR (Homology Directed Repair).","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_2_4","event":"Protein Modeling","subtopic":"CRISPR","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the signature gene of the three most important types of CRISPR-Cas systems?","correctAnswer":"Type 1: CRISPR-CAS3; Type 2: CRISPR-CAS9; Type 3: CRISPR-Cas10.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_2_5","event":"Protein Modeling","subtopic":"CRISPR","division":"C","type":"FRQ","difficulty":"Hard","question":"Name and explain the mechanism behind two gene editing techniques other than CRISPR.","correctAnswer":"Zinc Finger Nuclease (ZNF): uses a Zinc Finger DNA binding domain, half Fok1 endonuclease, and Fok1 dimerization. TALENs: Similar to ZNF except they recognize single nucleotides rather than codons.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_2_6","event":"Protein Modeling","subtopic":"CRISPR","division":"C","type":"FRQ","difficulty":"Hard","question":"What are the two nuclease domains involved in Cas9 DNA cleavage?","correctAnswer":"RuvC and HNH","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_2_7","event":"Protein Modeling","subtopic":"CRISPR","division":"C","type":"FRQ","difficulty":"Hard","question":"What is AcrII-A4 and what is its function in regards to CRISPR and genome editing?","correctAnswer":"It is an Anti-CRISPR protein that inhibits genome editing by preventing the binding of CRISPR protein complexes with the DNA. This illustrates the Red Queen hypothesis as phages evolve to fight the anti-viral mechanisms of bacteria.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_3_1","event":"Protein Modeling","subtopic":"Cytidine Deaminase","division":"C","type":"FRQ","difficulty":"Medium","question":"How does APOBEC3G cause a 5-methylcytosine to thymine mutation?","correctAnswer":"By removing an amino group from 5-methylcytosine (deamination).","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_3_2","event":"Protein Modeling","subtopic":"Cytidine Deaminase","division":"C","type":"FRQ","difficulty":"Medium","question":"Is the APOBEC3 family part of the adaptive or innate immune system? What is their specific role?","correctAnswer":"Innate immune system. Their role is restricting retroviruses and mobile genetic elements like retrotransposons and transposons.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_3_3","event":"Protein Modeling","subtopic":"Cytidine Deaminase","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the role of APOBEC1?","correctAnswer":"It deaminates apolipoprotein B messenger RNA to generate a premature stop codon.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_3_4","event":"Protein Modeling","subtopic":"Cytidine Deaminase","division":"C","type":"FRQ","difficulty":"Medium","question":"What compounds are formed by the deamination of cytidine/deoxycytidine?","correctAnswer":"Uridine, Deoxyuridine, and Ammonia/NH3.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_3_5","event":"Protein Modeling","subtopic":"Cytidine Deaminase","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the function of the catalytic zinc section of the APOBEC3 protein?","correctAnswer":"It coordinates the water which acts as the proton source for the amino group and N3 atom of cytosine.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_3_6","event":"Protein Modeling","subtopic":"Cytidine Deaminase","division":"C","type":"FRQ","difficulty":"Hard","question":"Targeting the APOBEC3A and APOBEC3B offer promising treatments for aggressive cancers. Out of those two proteins, which one is able to cause mutations at a higher rate? What are two plausible ways to treat cancers in regards to APOBEC3A and APOBEC3B expression?","correctAnswer":"APOBEC3A mutates the genome at a higher rate. Two plausible treatments: decrease expression for these proteins to decrease mutations, or increase expression significantly to hopefully induce lethal mutations in tumor DNA.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_1a","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"In the structure of nanobody D3-L11 mutant Y102A in complex with hen egg-white lysozyme (6jb5.pdb), how many hydrophobic atoms are in this structure?","correctAnswer":"913","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_1b","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"How many polar atoms are in this structure?","correctAnswer":"1107","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_1c","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"How many atoms are selected when the structure is restricted to water molecules?","correctAnswer":"310","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_1d","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"How many chains are present in the structure?","correctAnswer":"2","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_1e","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"How many atoms are selected when the structure is restricted to nucleic acids?","correctAnswer":"0","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_1f","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"How many struts are in the structure?","correctAnswer":"39","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_2a","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"For residue 35 of chain A, what is the one letter abbreviation of this amino acid?","correctAnswer":"T","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_2b","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the chemical formula of this amino acid (residue 35, chain A)?","correctAnswer":"C4H9NO3","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_2c","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"How many chiral centers does this amino acid (Threonine) have?","correctAnswer":"2","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_3a","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the full name of the amino acid at residue 23 of chain A?","correctAnswer":"Alanine","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_3b","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"Is the R-group of Alanine aromatic or aliphatic?","correctAnswer":"Aliphatic","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_3c","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"Name the two stereoisomers of Alanine.","correctAnswer":"D-alanine and L-alanine","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_4a","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the full name of the amino acid at residue 100 of chain A?","correctAnswer":"Arginine","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_4b","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"MCQ","difficulty":"Medium","question":"True or False: The positional variability of atom #787 is greater than that of atom #777.","options":["True","False"],"correctAnswer":"True","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_5a","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"How many hydrogen bonds are in chain B?","correctAnswer":"80","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_5b","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"How many atoms are in sheets in chain B?","correctAnswer":"69","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_5c","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"How many 3-10 helices are present in chain B?","correctAnswer":"4","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_5d","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"What ligands are present in chain B? List both the abbreviated ID and the name of the ligands.","correctAnswer":"GOL (glycerol), CL (chloride ion)","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_6","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the default color for sodium in Jmol?","correctAnswer":"Purple","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_7","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"What is measured by an atom’s “temperature factor”? What command would be used to color a structure’s atoms based on their “temperature factor”?","correctAnswer":"Positional variability; `color temperature`","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_8","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"What do struts represent in Jmol?","correctAnswer":"Struts are where structural supports may need to be placed to produce a solid and stable physical model for 3D printing.","year":2025,"tournament":"SSSS"},
  {"id":"q_pm_2025_ssss_4_9","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"What are disulfide bonds referred to in Jmol?","correctAnswer":"ssbonds","year":2025,"tournament":"SSSS"}
,
  {"id":"q_pm_2025_clements_1_1","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Easy","question":"What type of bond is formed when amino acids polymerize?","options":["Phosphodiester bond","Hydrogen bond","Peptide bond","Metallic bond"],"correctAnswer":"Peptide bond","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_2","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"Rate the following intramolecular forces/interactions from least to greatest strength: hydrogen bonds, Van der Waals forces, ionic bond.","correctAnswer":"1) Van der Waals, 2) Hydrogen bond, 3) Ionic Bond","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_3","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Easy","question":"Two functional groups which exist on every amino acid are ____ and ____.","correctAnswer":"amino group and carboxyl group","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_4","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe chirality.","correctAnswer":"A geometric property of molecules/ions in which there exist two optically active asymmetric forms of the molecule that are the mirror images of each other.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_5","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Easy","question":"All amino acids are chiral except for?","options":["Glycine","Alanine","Phenylalanine","Histidine"],"correctAnswer":"Glycine","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_6","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Easy","question":"The start codon for translation is?","options":["UAA","AUG","UGA","UUU","GUA"],"correctAnswer":"AUG","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_7","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Easy","question":"The amino acid that is coded for by the start codon is ________.","correctAnswer":"methionine","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_8","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following amino acids can form disulfide bonds?","options":["Tyrosine","Asparagine","Glutamic Acid","Cysteine"],"correctAnswer":"Cysteine","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_9","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Medium","question":"What level of protein structure is characterized by hydrogen bonding between Beta sheets?","options":["Primary","Secondary","Tertiary","Quaternary"],"correctAnswer":"Secondary","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_10","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Hard","question":"What intermolecular force contributes most strongly to the folding of tertiary structures (ex. packing of α-helices against one another into a four-helix bundle)?","options":["Electrostatic interactions","Van der Waals Force","Hydrogen Bond","Hydrophobic interactions"],"correctAnswer":"Hydrophobic interactions","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_11","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Medium","question":"If protein folding forces the formation of intramolecular disulfide bonds, when in the folding process would the disulfide bonds actually form?","options":["After tertiary structure","Between secondary and tertiary structure","Between primary and secondary structure","In the primary structure"],"correctAnswer":"After tertiary structure","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_12","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"Most proteins are in the _______________ configuration where r-groups extend in opposite sides of the peptide bond plane.","correctAnswer":"trans (or R)","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_13","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following is a function of proteins?","options":["Catalysis as enzymes","Structural support","Transport","Signal transduction","All of the above"],"correctAnswer":"All of the above","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_14","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Hard","question":"Which of the following methods would allow a scientist to identify the primary structure of a protein without any prior knowledge of the protein of interest?","options":["Edman degradation","Tandem mass spectrometry (MS/MS)","Matrix-assisted laser desorption ionization-time of flight (MALDI-TOF)","Enzyme digestion"],"correctAnswer":"Edman degradation","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_15","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Hard","question":"A protein solution has a low salt concentration and then salt is added, at first the solubility of proteins increases since the salt ions shield charged regions of proteins from each other. What happens at a high salt concentration to the solubility of proteins?","options":["Decrease, salt ions disrupt hydrophobic interactions","Decrease, salt ions compete with proteins for water molecule interactions","Increase, there are more electrostatic interactions since salt ions deprotonate ionizable side groups","Increase, salt ions continue to shield charged regions of the proteins"],"correctAnswer":"Decrease, salt ions compete with proteins for water molecule interactions","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_16","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Hard","question":"What proteins would migrate through native gel electrophoresis towards the positively charged end faster than the other proteins described in the options below?","options":["Negatively charged, globular","Negatively charged, fibrous","Positively charged, globular","Positively charged, fibrous"],"correctAnswer":"Negatively charged, globular","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_17","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Medium","question":"How many possible proteins 300 amino acids in length could exist?","options":["10^290","20^300","20^290","10^300"],"correctAnswer":"20^300","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_18a","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Hard","question":"What does the dihedral angle Φ (phi) measure and when is it positive or negative (view down from N-C alpha bond)?","correctAnswer":"The angle between the nitrogen and the alpha carbon of the same amino acid and left is negative while the right is positive.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_18b","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Hard","question":"What does the dihedral bond ψ (psi) measure?","correctAnswer":"The angle between the N-C bond of that amino acid and carbonyl - N/C or one amino acid away by the right-hand rule.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_19","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"MCQ","difficulty":"Hard","question":"A protein that is composed of mainly α-helices is plotted on the Ramachandran plot. Which statement best describes the Ramachandran plot of amino acids in the protein that you would expect based on its structure?","options":["Most data points in the two left quadrants","Most data points in the top left quadrant","Most data points in the top right quadrant","Most data points in the bottom left quadrant"],"correctAnswer":"Most data points in the bottom left quadrant","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_20a","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"What is competitive inhibition?","correctAnswer":"Competitive inhibition is when molecules that are similar to the substrate molecules bind to the active site and prevent the actual substrate from binding.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_20b","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"What is noncompetitive inhibition?","correctAnswer":"Noncompetitive inhibition is when an inhibitor binds to the enzyme at a site that isn’t the active site.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_21","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Hard","question":"What is Anfinsen’s Dogma and its three conditions?","correctAnswer":"The idea that if a protein is folding into its native structure it’s done automatically by the protein's amino acid sequence. The three conditions would be uniqueness (or different from others), stability, and kinetical accessibility.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_22","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Hard","question":"What is Levinthal’s paradox?","correctAnswer":"States that the possible number of conformations available for a specific protein is extremely large (or astronomically large) thus proteins must follow some ordered pathway when folding.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_23a","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"Regarding the structure of an alpha helix, what does the measurement for the pitch of an alpha helix describe and define?","correctAnswer":"The height between one full turn in an α-helix.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_23b","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"The pitch of an alpha helix is __________ angstroms and contains about ___________ amino acids.","correctAnswer":"5.4 angstroms; 3.6 amino acids","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_23c","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"Regarding the structure of an alpha helix, what does the measurement for the rise of an alpha helix describe and define?","correctAnswer":"Distance between two adjacent amino acids along the helical axis.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_1_23d","event":"Protein Modeling","subtopic":"General Biochemistry","division":"C","type":"FRQ","difficulty":"Medium","question":"The rise of an alpha helix is __________ angstroms.","correctAnswer":"1.5","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_1","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"MCQ","difficulty":"Easy","question":"In which bacteria was the CRISPR structure first discovered (1978)?","options":["E. Coli","Campylobacter","Norovirus","Salmonella"],"correctAnswer":"E. Coli","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_2","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"MCQ","difficulty":"Medium","question":"Which gene-editing mechanism has nucleases that recognize one long, specific sequence?","options":["Zinc finger nucleases (ZNFs)","TALENS","Meganucleases","CRISPR"],"correctAnswer":"Meganucleases","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_3","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"MCQ","difficulty":"Medium","question":"Which gene-editing mechanism uses DNA binding motifs to direct non-specific nuclease to cleave the genome?","options":["Zinc finger nucleases (ZNFs)","TALENS","Meganucleases","CRISPR"],"correctAnswer":"TALENS","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_4","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"MCQ","difficulty":"Medium","question":"Which gene-editing mechanism recognizes all of the 64 possible trinucleotide combinations?","options":["Zinc finger nucleases (ZNFs)","TALENS","Meganucleases","CRISPR"],"correctAnswer":"Zinc finger nucleases (ZNFs)","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_5","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"MCQ","difficulty":"Medium","question":"Which gene-editing mechanism is made up of a transcription activator-like protein?","options":["Zinc finger nucleases (ZNFs)","TALENS","Meganucleases","CRISPR"],"correctAnswer":"TALENS","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_6","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"MCQ","difficulty":"Medium","question":"Which gene-editing mechanism has about 70% efficiency?","options":["Zinc finger nucleases (ZNFs)","TALENS","Meganucleases","CRISPR"],"correctAnswer":"CRISPR","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_7","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"MCQ","difficulty":"Medium","question":"How many base pairs long is the region targeted by Cas9?","options":["10 base pairs","20 base pairs","30 base pairs","40 base pairs"],"correctAnswer":"20 base pairs","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_8a","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"FRQ","difficulty":"Medium","question":"What are yeast artificial chromosomes (YAC)?","correctAnswer":"Yeast artificial chromosomes are genetically engineered chromosomes from DNA of yeast. They are linear DNA and contain all that is required for replication in yeast.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_8b","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"FRQ","difficulty":"Medium","question":"What are bacterial artificial chromosomes (BAC)?","correctAnswer":"Circular plasmids that normally replicate long regions of DNA and are maintained at a level of approximately one copy per cell and contain all that is required for replication.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_9","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"FRQ","difficulty":"Medium","question":"What does TALENS stand for?","correctAnswer":"Transcription activator-like effector nuclease","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_10","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"FRQ","difficulty":"Easy","question":"What does CRISPR stand for?","correctAnswer":"Clustered Regularly Interspaced Short Palindromic Repeats","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_11","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"FRQ","difficulty":"Medium","question":"What are palindromic repeats?","correctAnswer":"20-40 letter repeats of DNA same left to right.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_12","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"FRQ","difficulty":"Medium","question":"What is a “dead” Cas9 (dCas9) and what are they used for?","correctAnswer":"Dead Cas9 is a protein that cannot cut DNA. However, it can be used to affect gene expression (being attached to a promoter/repressor).","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_13","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"FRQ","difficulty":"Hard","question":"How many inactive domains are/is there in a Cas9 nickase and what are the benefits of using a Cas9 nickase?","correctAnswer":"Cas9 Nickase has 1 inactive nuclease domain to induce specific single-strand DNA nicks. The benefits are high specificity and want to minimize off-target effects.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_14","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"FRQ","difficulty":"Hard","question":"How is the original CRISPR structure in bacteria different from CRISPR Cas9 structures researchers use (please state at least one difference)?","correctAnswer":"Specific RNA to target a sequence (sgRNA), or can inactivate both nuclease sites, or cytidine deaminase to n-terminus of cas9 (AID).","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_2_15","event":"Protein Modeling","subtopic":"Gene Editing Mechanisms","division":"C","type":"FRQ","difficulty":"Medium","question":"What does the abbreviation PAM stand for and what PAM sequence does Cas9 recognize?","correctAnswer":"PAM stands for protospacer adjacent motifs and cas9 binds to: 5’-N-G-G-3’ (N could be any nucleotide base)","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_3_1","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"In a typical twisted beta sheet or beta saddle, what is/are the main secondary structure(s) shown?","correctAnswer":"Beta Sheets","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_3_4","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"Are parallel or antiparallel beta sheets more stable?","correctAnswer":"Antiparallel beta sheets are a bit more stable than parallel ß sheets since their hydrogen bonding pattern is more optimal.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_3_5","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Hard","question":"How are beta pleated sheets held together and what are the bonds holding beta sheets together formed between?","correctAnswer":"Beta sheets are held together by hydrogen bonds that form between carbonyl and amino groups of backbone, while the R groups extend above and below the plane of the sheet.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_3_6","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"What is another name given to Beta sheets arranged in a circular structure?","correctAnswer":"Twisted beta sheet or twisted beta saddle (beta barrel)","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_3_11","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Medium","question":"How are alpha helices (right handed) held together and what are the bonds holding them together formed between?","correctAnswer":"Alpha helices are held together by hydrogen bonds between the amino and carbonyl groups of every fourth amino acid. The side chains extend outwards.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_3_12","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Hard","question":"Are right handed or left handed alpha helices more commonly found in nature and why?","correctAnswer":"Proteins usually are made of right-handed alpha helices while left-handed alpha helices are more rare since right handed helices are more stable.","year":2025,"tournament":"Clements HS"},
  {"id":"q_pm_2025_clements_3_13","event":"Protein Modeling","subtopic":"Jmol Exploration","division":"C","type":"FRQ","difficulty":"Easy","question":"Assuming a protein is made from one polypeptide chain, what is the lowest level of structure it has?","correctAnswer":"Primary","year":2025,"tournament":"Clements HS"}
,
  {"id":"q_rs_2025_ssss_1","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"What combination of bands was used to generate a MODIS false-color image where healthy vegetation is green, ice is bright blue, and barren land is pinkish?","options":["1, 4, 3","3, 5, 1","7, 2, 1","2, 1, 1"],"correctAnswer":"7, 2, 1","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_2","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Easy","question":"In a 7-2-1 MODIS false-color image, what does a dark blue/black structure typically represent?","options":["Ice","Clouds","Deep water","Shallow Water"],"correctAnswer":"Deep water","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_3","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Easy","question":"In a 7-2-1 MODIS false-color image, what does an electric blue structure typically represent?","options":["Ice","Clouds","Deep water","Shallow water"],"correctAnswer":"Ice","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_4","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Easy","question":"In a 7-2-1 MODIS false-color image, what does a white structure typically represent?","options":["Ice","Clouds","Deep water","Shallow water"],"correctAnswer":"Clouds","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_5","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Easy","question":"The acronym MODIS stands for what?","correctAnswer":"Moderate Resolution Imaging Spectroradiometer","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_6","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Medium","question":"Assuming that the MODIS sensor that took this image was on a satellite that travels from North to South over the equator in the morning, which satellite took this image?","correctAnswer":"Terra","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_7","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the advantage of having MODIS aboard two satellites with different orbits?","correctAnswer":"Terra passes over the equator in the morning while Aqua passes over the equator in the afternoon. Both sensors are identical but provide images with different angles and lighting to create a more comprehensive image.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_8","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Medium","question":"From which area(s) of the electromagnetic spectrum did the sensor measure to generate a 7-2-1 MODIS image?","correctAnswer":"Visible and infrared (specifically 2130nm/SWIR, 858nm/NIR, 648nm/Red).","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_9","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"What is the turquoise structure beneath letter A in the 7-2-1 MODIS image?","options":["Smoke","Icy Cloud","Dust Cloud","Artifact"],"correctAnswer":"Icy Cloud","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_10","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"What is the dark blue splotch in the 7-2-1 MODIS image?","options":["Shallow water","Turbid water","Deep water","Artifact"],"correctAnswer":"Turbid water","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_11","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Hard","question":"Explain in terms of the structures that each color represents and the type of radiation they reflect why healthy vegetation appears green and barren land appears pink in a 7-2-1 MODIS false-color image.","correctAnswer":"In this false color image, band 2/NIR is assigned to green and band 7/SWIR is assigned to red. Healthy vegetation reflects a lot of NIR and absorbs SWIR and band 1/visible light, so we see it as green. Barren land/desert reflects all radiation but more of SWIR, resulting in a pinkish color.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_12","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Hard","question":"Letters B and E represent burn scars but on this image, they are different hues of red/brown. Explain what this structure is and why they might appear as different hues of red/brown from a satellite image.","correctAnswer":"These structures are burn scars. Bands 7, 2, and 1 make it very easy to distinguish healthy vegetation from burned vegetation. Burned vegetation will appear different hues of red/brown based on factors such as carbon content, how much soil is exposed, and ultimately what type of vegetation was burned.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_13","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"What bands are utilized to generate a true-color MODIS image?","options":["1, 4, 3","7, 2, 1","3, 6, 7","2, 1, 1"],"correctAnswer":"1, 4, 3","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_14","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"What type of clouds are visible above the land at the bottom of the true-color image?","options":["Cumulus","Nimbostratus","Altocumulus","Cirrus"],"correctAnswer":"Cirrus","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_15","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Medium","question":"What natural phenomenon is represented by blue-green swirls in a true-color ocean image? Explain one method in which it may occur.","correctAnswer":"Phytoplankton bloom. Water containing excess nutrients, typically from anthropogenic sources like factory waste or fertilizer runoff, enters the ocean and raises the availability of limiting nutrients like phosphorus or nitrogen for phytoplankton to grow.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_16","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain what causes the electric blue color versus the green color in a phytoplankton bloom.","correctAnswer":"The normal green-blue is created via a mixture of green chlorophyll and blue water. An electric blue is created when the calcium containing calcite coccospheres of coccolithophores reflect and add white light to the spectrum.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_17","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Hard","question":"The origin of the electric blue color is believed to participate in a feedback mechanism that stabilizes the Earth's albedo and temperature, known as the CLAW hypothesis. Describe it.","correctAnswer":"Certain phytoplankton like coccolithophores produce dimethylsulfoniopropionate (DMSP) which may break down into dimethyl sulfide (DMS) which may aerosolize into sulfur dioxide, which acts as a cloud condensation nucleus. Increased exposure to sunlight allows phytoplankton to grow in population which creates more CCNs which raises the Earth's albedo/lowers its temperature and decreases phytoplankton growth.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_18","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following sensors is NOT found on CALIPSO?","options":["WFC","CALIOP","ABI","IIR"],"correctAnswer":"ABI","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_19","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"Which instrument is most utilized to generate CALIPSO vertical profile images?","options":["WFC","CALIOP","ABI","IIR"],"correctAnswer":"CALIOP","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_20","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Easy","question":"What does CALIPSO stand for? When was it launched?","correctAnswer":"Cloud-Aerosol Lidar and Infrared Pathfinder Satellite Observations, launched on April 28, 2006.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_21","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the bright white streak in the true-color image over the ocean? How is this structure formed?","correctAnswer":"This is a phenomenon known as sunglint, which occurs when light is reflected directly back to the sensor at the angle at which the sensor views it. The bright white color indicates that the cloud is reflecting light back very strongly.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_22","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Medium","question":"According to CALIPSO measurements of the Hunga Tonga-Hunga Ha’apai volcano eruption, how high did the dust plumes rise?","correctAnswer":"30-35 kilometers","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_23","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Hard","question":"Describe what is happening to create the solid blue chunks underneath all of the yellow and red in a CALIPSO scan. What term is used to describe the creation of these regions?","correctAnswer":"Data can not be accurately gathered for these regions. CALIPSO shoots a photon down and collects data when the photon returns. When it gets reflected by thick clouds, we are unable to glean any information about what is underneath. These regions are known as attenuated backscatter.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_24","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Hard","question":"In a CALIPSO scan, a horizontal boundary can be noticed just above the 20km mark. What is the source of this line?","options":["Changing noise characteristics of data","This is the tropopause","Aerosols above 20km are not detected","Interference with radio waves is not a problem above 20km"],"correctAnswer":"Changing noise characteristics of data","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_25","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"What product is being used to generate the categorical second CALIPSO image?","options":["Aerosol Layer Mask","Vertical Feature Mask","Polar Stratospheric Cloud Mask","Cloud Mask"],"correctAnswer":"Vertical Feature Mask","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_26","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain what the gray blob around the 11km line of the CALIPSO total attenuated backscatter image is. Why is this gray?","correctAnswer":"This is a cloud. It is gray because this is a large cloud returning a strong signal and thus is plotted with a gray color.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_27","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Medium","question":"What does LIDAR stand for? If we use LIDAR to measure the distance to an object and it takes 0.01 milliseconds for a return signal to be detected, how far is the object?","correctAnswer":"Light Detection and Ranging. 1500m = (3x10^8) x 0.01ms / 2.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_28","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Easy","question":"The satellite depicted in the cover image is:","options":["OCO-2","TOPEX-Poseidon","CERES","CloudSat"],"correctAnswer":"CloudSat","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_29","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"What does CloudSat measure?","options":["Reflectivity","Aerosol type","Wind speed","Cloud content"],"correctAnswer":"Reflectivity","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_30","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"CloudSat follows the same orbit as which other satellite?","options":["Aura","PARASOL","Aqua","CALIPSO"],"correctAnswer":"CALIPSO","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_31","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Hard","question":"CloudSat takes data primarily in which frequency?","options":["94 GHz","94 MHz","40 GHz","40 MHz"],"correctAnswer":"94 GHz","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_32","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Easy","question":"The 94 GHz band is in which section of the electromagnetic spectrum?","correctAnswer":"Microwave","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_33","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Hard","question":"In a CloudSat cross section of a typhoon, between which two letters is the eye of the storm? List 3 characteristics of the eyewall region.","correctAnswer":"Between C and D. Eyewalls have tall clouds, heavy rain, and the fastest wind speeds.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_34","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Medium","question":"Name the sensor that took the CloudSat typhoon image.","correctAnswer":"Cloud Profiling Radar","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_35","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Easy","question":"Most of the convection in this typhoon appears to be towards (A / B)","correctAnswer":"B","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_36","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Hard","question":"TOPEX-Poseidon effectively combined data measured in which two regions of the EM spectrum in order to generate accurate sea level data? What are the three instruments that take these data?","correctAnswer":"Radio and microwave. NRA (Dual frequency radar altimeter), DORIS (Doppler Orbitography and Radiopositiong by Satellite), and TMR (TOPEX Microwave Radiometer).","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_37","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Medium","question":"TOPEX-Poseidon sea level data was accurate to within how many centimeters?","correctAnswer":"3-5cm","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_38","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Hard","question":"If TOPEX-Poseidon flew over a mountain in the ocean, would you expect the sea level to be higher or lower? Why?","correctAnswer":"Higher. The Earth is denser at these mountainous regions so the gravitational pull exerted on water is higher.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_39","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"Which satellite is designated as GOES EAST at 75°W?","options":["GOES-14","GOES-15","GOES-16","GOES-17"],"correctAnswer":"GOES-16","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_40","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"Which satellite is designated as GOES WEST at 137.2°W?","options":["GOES-14","GOES-15","GOES-16","GOES-17"],"correctAnswer":"GOES-17","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_41","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Hard","question":"Due to reliability issues with GOES WEST, which satellite operates in tandem with it?","options":["GOES-14","GOES-15","GOES-16","GOES-17"],"correctAnswer":"GOES-15","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_42","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Hard","question":"Which satellite was launched in 2009 and sits in the middle of GOES EAST and WEST as a backup in case either fails?","options":["GOES-14","GOES-15","GOES-16","GOES-17"],"correctAnswer":"GOES-14","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_43","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Hard","question":"The latest GOES satellite entered orbit in March of 2022 to replace GOES WEST. What changes were made?","correctAnswer":"GOES-17 was believed to have suffered damage to its cooling system from debris collisions, as a result, GOES-18 was designed with less complicated hardware that removed susceptibility to debris. It also contains a more advanced magnetometer.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_44","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Medium","question":"GOES is geostationary. What does this mean? Why is this significant for this satellite?","correctAnswer":"It means that the satellite has the same period of rotation as the Earth, and that it will perpetually observe the same swath of land until it is manually moved. This is important for a weather forecasting satellite because it can take data of a specific region and of a weather system as it develops over time.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_45","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Easy","question":"This GOES Derecho image was taken with which sensor?","options":["SUVI","ABI","EXIS","GLM","SEISS"],"correctAnswer":"ABI","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_46","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"The fancy colors in this GOES Derecho image are an example of:","options":["Panchromatic imaging","Multispectral Imaging","Hyperspectral imaging","Orthochromatic imaging"],"correctAnswer":"Multispectral Imaging","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_47","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Hard","question":"Describe each real type of imaging listed above in detail. Compare and contrast each type.","correctAnswer":"Orthochromatic: archaic, blue-sensitive silver halide. Panchromatic: broader visible spectrum, full RGB, grayscale but high spatial res. Multispectral: Uses multiple bands (3-15), higher spectral resolution than panchromatic but lower spatial resolution. Hyperspectral: Uses hundreds of narrow bands, extremely high spectral resolution.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_48","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Medium","question":"Panchromatic and Multispectral images are often combined. Describe one \"pansharpening\" technique.","correctAnswer":"HSV Sharpening (swapping Value with panchromatic), Gran-Schmidt, IHS, or Brovey transformation.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_49","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Easy","question":"How many bands does the ABI sensor use?","correctAnswer":"16","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_50","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Hard","question":"Given what you know about a Derecho, which band was likely very involved in the generation of this image?","options":["8: Low Level Water Vapor","9: Mid Level Water Vapor","7: Shortwave Band","4: Cirrus band"],"correctAnswer":"9: Mid Level Water Vapor","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_51","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Medium","question":"What is the difference between the \"dirty\" and \"clean\" GOES infrared bands?","options":["Sensitivity to water vapor","Sensitivity to groundwater","Sensitivity to snow versus ice","Sensitivity to dirt"],"correctAnswer":"Sensitivity to water vapor","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_52","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe how bands 14 and 16 might be useful to tracking storm systems like these.","correctAnswer":"Bands 14 and 16 are involved in determining cloud top height, which is important as a proxy to determining the convection activity of the storm system.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_53","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Easy","question":"Outside of taking images, how else are the GOES satellites useful for meteorology?","options":["Detects earthquakes","Automatically sends emergency warnings","Launches rockets containing chemicals that dispel storms","Relays information from sensors on Earth"],"correctAnswer":"Relays information from sensors on Earth","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_54","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"MCQ","difficulty":"Easy","question":"GOES is capable of deriving Sea Surface Temperature during:","options":["Morning","Evening","Afternoon","All of the above"],"correctAnswer":"All of the above","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_55","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Hard","question":"Looking at an OCO-2 global map, what is being measured? How is this measured by OCO-2? What is one potential problem with this method?","correctAnswer":"Column CO2. This is measured indirectly by measuring how much sunlight that is reflected off from the Earth is absorbed by CO2 in the column of air. Objects in the atmosphere, namely clouds/aerosols, may absorb or reflect light/heat and throw off measurements.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_56","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Hard","question":"OCO-2 takes measurements in 3 different bands. Describe each of these bands and how they serve to solve the problem you raised in the previous question.","correctAnswer":"The weak CO2 band (1.61 µm) is sensitive to CO2 near the surface; the strong CO2 band (2.06 µm) is very sensitive to aerosols. To help account for clouds/aerosols, OCO-2 also measures O2 concentration in the O2 A-band (0.76 µm). Since O2 is uniformly distributed, any measured deviation can be attributed to clouds/aerosols, allowing for CO2 measurement corrections.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_57","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify a spot where CO2 is high and list 2 reasons why this region has high atmospheric CO2 concentration.","correctAnswer":"Eastern China has high CO2 concentrations because that area is very urban and industrialized. Modern technology such as cars burn fossil fuels and serve as anthropogenic sources of CO2.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_58","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Hard","question":"At the cellular level, what is OCO-2's Solar-Induced Chlorophyll Fluorescence measuring? Specifically, what part of the EMS is this image taking data from?","correctAnswer":"Photosynthetic activity; Near Infrared","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_59","event":"Remote Sensing","subtopic":"Earth Systems & Processes","division":"C","type":"FRQ","difficulty":"Medium","question":"Looking at the chlorophyll fluorescence graph, why did researchers pick the wavelength 757nm to measure?","correctAnswer":"This wavelength has the highest emission in both photosystems.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_60","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Medium","question":"A blackbody emits maximum radiative energy when the wavelength of the radiation is centered around 5.0 microns. What is the temperature of the blackbody to two significant figures?","correctAnswer":"580 K","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_61","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Hard","question":"From your answer above, calculate the power that is being emitted from this blackbody in Watts per square meter to two significant figures.","correctAnswer":"6400 W/m^2","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_62","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Hard","question":"Using your equipment, you measure the temperature of the blackbody and discover that your calculations are off. The real irradiance measures 5,133 W/m^2. What are you dealing with? Calculate its emissivity to two significant figures.","correctAnswer":"Greybody. Emissivity = 0.80.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_63","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Hard","question":"Let's assume that all of that power reaches the surface of a nearby planet with an average albedo of 0.43. Calculate its average surface temperature to two significant figures.","correctAnswer":"340 K","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_64","event":"Remote Sensing","subtopic":"Imaging Systems & Sensors","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the name of the instrument used to measure global solar irradiance?","correctAnswer":"Pyranometer","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_65","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Medium","question":"At the top of Earth's atmosphere, what is the average intensity of radiation, in Watts per square meter to the nearest two significant figures? Why does the Earth's surface receive less than this amount?","correctAnswer":"1360 - 1380 W/m^2. The atmosphere's contents, including aerosols, clouds, and greenhouse gases, play a role in absorbing much of this radiation in different wavelengths.","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_66","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Hard","question":"Sunlight with an intensity of 1100 W/m^2 enters a 4m thick cloud with an extinction coefficient of 0.1 m^-1 at a solar zenith angle of 10°. Calculate the intensity of the light after passing through the cloud.","correctAnswer":"733 W/m^2","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_67","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Easy","question":"The white light that we see from clouds are the result of what kind of scattering?","correctAnswer":"Mie Scattering","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_68","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Medium","question":"The equation I alpha I0 / lambda^4 relates degree of scattering of light scattered with wavelength. What type of scattering does this equation describe?","correctAnswer":"Rayleigh scattering","year":2025,"tournament":"SSSS"},
  {"id":"q_rs_2025_ssss_69","event":"Remote Sensing","subtopic":"Electromagnetic Spectrum & Physics","division":"C","type":"FRQ","difficulty":"Hard","question":"Calculate how many times more intense scattering of light at 700 nm is compared to light at 500 nm for the same incident intensity to 2 significant figures.","correctAnswer":"3.8","year":2025,"tournament":"SSSS"}
,
  {"id":"q_rm_2023_ssss_1","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the orange, prismatic/cubic mineral that is denser than hornblende and is the birthstone for November.","correctAnswer":"Topaz","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_2","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the Mohs hardness of Topaz?","correctAnswer":"8","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_3","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"An English superstition once held that Topaz cured what?","correctAnswer":"Lunacy","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_9","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the carbonate mineral that forms saddle-shaped white crystals and can form biologically via sulfate-reducing microbes.","correctAnswer":"Dolomite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_10","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Give the chemical formula for Dolomite.","correctAnswer":"CaMg(CO3)2","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_11","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Hard","question":"In what two ways does the chemical formula for Dolomite differ from other minerals in the calcite group?","correctAnswer":"It contains two carbonate groups rather than one, and it contains magnesium.","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_21","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the peach-to-pinkish colored carbonate mineral that has a hardness of 3.5-4 and forms a solid solution with ankerite and kutnohorite.","correctAnswer":"Dolomite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_24","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Hard","question":"What is a horticultural use for Dolomite?","correctAnswer":"pH buffer or magnesium source","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_29","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the opaque, red to brown microcrystalline variety of quartz (chalcedony) whose color comes from Iron (III) and whose name means \"spotted or speckled stone\".","correctAnswer":"Jasper","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_32","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"The specific gravity for Jasper is approximately what?","correctAnswer":"2.7","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_41","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the extremely hard mineral (hardness 9) that occurs in gem varieties such as ruby and sapphire, though its most common color is black/brown.","correctAnswer":"Corundum","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_44","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"MCQ","difficulty":"Hard","question":"Which of the following is most likely to be associated with Corundum?","options":["Aragonite","Kyanite","Apophyllite","Chalcedony"],"correctAnswer":"Kyanite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_45","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the iron oxide mineral that often forms botryoidal masses, has a red-brown streak, and is named after the Greek word for \"blood\".","correctAnswer":"Hematite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_48","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the chemical formula for Hematite?","correctAnswer":"Fe2O3","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_49","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Hard","question":"Identify the lead phosphate mineral that often occurs as green or orange barrel-shaped hexagonal crystals and forms a solid solution with mimetite.","correctAnswer":"Pyromorphite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_52","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Hard","question":"In the solid solution series between pyromorphite and mimetite, the phosphorus in pyromorphite is replaced by what element in mimetite?","correctAnswer":"Arsenic","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_61","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the green copper carbonate mineral that frequently exhibits a botryoidal habit and is a less stable form of azurite.","correctAnswer":"Malachite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_62","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Smelting Malachite to produce pure copper produces what as a byproduct?","correctAnswer":"CO2","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_69","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the fibrous, white to grey amphibole mineral that forms a solution series with actinolite and is one of the types of asbestos.","correctAnswer":"Tremolite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_71","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"A green color in Tremolite-Actinolite is produced by what element?","correctAnswer":"Iron","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_73","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the dark, stubby prismatic pyroxene mineral that has cleavage planes meeting at 87 and 93 degrees, and is common in mafic igneous rocks.","correctAnswer":"Augite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_81","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the iridescent copper iron sulfide mineral commonly nicknamed \"peacock ore\" and having the Strunz code 2.BA.10.","correctAnswer":"Bornite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_83","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Bornite is an important ore for what element?","correctAnswer":"Copper","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_5","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the dark-colored, fine-grained (aphanitic), extrusive igneous rock that commonly forms from the mantle.","correctAnswer":"Basalt","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_6","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Basalt has a (high/low) silica content and thus has a (high/low) viscosity.","correctAnswer":"Low, Low","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_7","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Basalt typically contains what percent silica?","correctAnswer":"45-52%","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_13","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the foliated metamorphic rock characterized by distinct compositional banding (alternating light and dark layers).","correctAnswer":"Gneiss","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_14","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Hard","question":"What are two possible theories for how the bands in Gneiss form?","correctAnswer":"Bands develop when rock is more strongly compressed in one direction than in others, due to differences in composition, or metamorphic differentiation causes banding as minerals separate during metamorphism.","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_15","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Hard","question":"The name for Gneiss comes from the German word for what?","correctAnswer":"Spark","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_16","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Hard","question":"What are leucosomes?","correctAnswer":"Intrusive igneous rock that is produced from a silica-rich partial melt.","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_17","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the clastic sedimentary rock consisting of a mixture of quartz, feldspar, and rock fragments set in a clay matrix, typically formed in submarine avalanches and turbidity currents.","correctAnswer":"Greywacke","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_18","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Greywacke is mostly formed from what mineral?","correctAnswer":"Quartz","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_25","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the dark metamorphic rock that is commonly formed from basalt, is mainly composed of amphibole and plagioclase, and was historically used for adzes in the early Neolithic.","correctAnswer":"Amphibolite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_28","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Hard","question":"At 550 celsius, the pressure for the amphibolite facies is located in what range?","correctAnswer":"2-10 kbars","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_33","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the banded, compact form of limestone typically formed by the precipitation of calcium carbonate from hot springs.","correctAnswer":"Travertine","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_35","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"A similar (but softer and more porous) form of Travertine formed from ambient temperature water is known as what?","correctAnswer":"Tufa","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_36","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Hard","question":"Ancient forms of Travertine have lower porosity due to secondary crystallization from what mineral?","correctAnswer":"Calcite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_37","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the highly vesicular, dark-colored volcanic rock that is basaltic/mafic in composition and often falls to the ground in a cone shape.","correctAnswer":"Scoria","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_40","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Scoria is typically (denser/less dense) than pumice.","correctAnswer":"Denser","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_53","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the green, flaky or fibrous metamorphic rock formed from the hydrothermal alteration of peridotite.","correctAnswer":"Serpentinite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_55","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Hard","question":"A reaction between enstatite and water produces Serpentinite and what other mineral?","correctAnswer":"Talc","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_57","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the brown, pisolitic rock that serves as the principal ore for aluminum and gallium, and was first discovered in France.","correctAnswer":"Bauxite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_59","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"The density of bauxite is approximately?","correctAnswer":"2.7","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_65","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the coarse-grained intrusive igneous rock that resembles granite but contains less than 5% quartz and is named after a city in Egypt.","correctAnswer":"Syenite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_67","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the volcanic equivalent of Syenite?","correctAnswer":"Trachyte","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_77","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the sedimentary rock composed mainly of the mineral dolomite, named after the French mineralogist Deodat Gratet de Dolomieu.","correctAnswer":"Dolostone","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_93","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Medium","question":"In a binary phase diagram, what is the name for the curved line(s) separating the liquid phase from the solid+liquid phase?","correctAnswer":"Liquidus","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_94","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Hard","question":"Using the lever rule on the provided Diopside-Anorthite phase diagram: 100g of a melt cools from 1700 degrees. At 1300 degrees, the solid portion length is 17 units and the total length is 57 units. Approximately what percent of the system is solid?","correctAnswer":"Approximately 29.8% (accept 25% - 35%)","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_96","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Medium","question":"For a melt starting with a composition richer in Anorthite than the eutectic point, which mineral will crystallize first as it cools?","correctAnswer":"Anorthite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_98","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"What are the two K-feldspars on the Science Olympiad rocks list?","correctAnswer":"Amazonite and orthoclase/microcline","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_99","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Medium","question":"In a ternary feldspar diagram, the region where \"no feldspars exist here\" is known as what?","correctAnswer":"Miscibility gap","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_100","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"MCQ","difficulty":"Hard","question":"A liquid solution containing equal parts Anorthite and K-feldspar begins to cool. The anorthite and K-feldspar will:","options":["Form an intermediate solid (solid solution)","Form two adjacent minerals as one sinks to the bottom and one rises","Form two minerals that twin with each other","Form a mineral with crystals of the other within it","Form a mineral with layers of one within the other"],"correctAnswer":"Form a mineral with layers of one within the other","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_101","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Hard","question":"An exsolution intergrowth of plagioclase within K-feldspar, forming a mineral with layers of one within the other, is known as?","correctAnswer":"Perthite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_102","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe the typical color(s) of Perthite.","correctAnswer":"Pink with white stripes","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_104","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"Give the chemical formula for albite.","correctAnswer":"NaAlSi3O8","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_105","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"What is albite’s crystal system at room temperature?","correctAnswer":"Triclinic","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_106","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Hard","question":"Above 1050 C, albite’s crystal system changes to what?","correctAnswer":"Monoclinic","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_107","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Hard","question":"Albite can contain up to what percent potassium before being considered anorthoclase?","correctAnswer":"10%","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_85","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"Order the following from least dense to most dense: hematite, diorite, anthracite, serpentinite.","correctAnswer":"Anthracite, serpentinite, diorite, hematite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_89","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Easy","question":"What are the five properties that define a mineral?","correctAnswer":"Naturally formed, solid in natural state, definite chemical composition, characteristic crystalline structure, typically inorganic.","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_90","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"List four minerals with a splintery/fibrous fracture.","correctAnswer":"Any 4 of: ulexite, fluorite, pyrolusite, kyanite, tremolite, amazonite.","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_91","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"How many cleavage planes does a mineral with dodecahedral cleavage exhibit?","correctAnswer":"6","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_92","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"What is one mineral with dodecahedral cleavage?","correctAnswer":"Sphalerite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_108","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"The red color in both rhodochrosite and rhodonite is caused by what element?","correctAnswer":"Manganese","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_109","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"Suzie finds a pinkish mineral with black streaks in it and wants to know whether it is rhodonite or rhodochrosite. This rock is likely:","options":["Rhodonite","Rhodochrosite"],"correctAnswer":"Rhodonite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_110","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"Suzie finds a pinkish mineral with a hardness of 6 and wants to know whether it is rhodonite or rhodochrosite. This rock is likely:","options":["Rhodonite","Rhodochrosite"],"correctAnswer":"Rhodonite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_111","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"Suzie finds a pinkish mineral that contains carbonate and wants to know whether it is rhodonite or rhodochrosite. This rock is likely:","options":["Rhodonite","Rhodochrosite"],"correctAnswer":"Rhodochrosite","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_113","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"Kevin finds two white rocks and is trying to identify them as chalk or diatomite. The heavier rock is more likely to be:","options":["Chalk","Diatomite"],"correctAnswer":"Chalk","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_114","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"Kevin finds two white rocks and is trying to identify them as chalk or diatomite. The rock with a chemical texture is more likely to be:","options":["Chalk","Diatomite"],"correctAnswer":"Chalk","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_117","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the Mohs hardness of apophyllite?","correctAnswer":"4.5 - 5","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_118","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the Mohs hardness of milky quartz?","correctAnswer":"7","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_119","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the Mohs hardness of albite?","correctAnswer":"6 - 6.5","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_120","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the Mohs hardness of smoky quartz?","correctAnswer":"7","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_121","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the Mohs hardness of a human bone?","correctAnswer":"5","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_123","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the absolute hardness of apatite?","correctAnswer":"48","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_124","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the absolute hardness of gypsum?","correctAnswer":"2","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_125","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the absolute hardness of corundum?","correctAnswer":"400","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_126","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the absolute hardness of quartz?","correctAnswer":"100","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_127","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Easy","question":"An adamantine luster is most notably seen in what mineral?","correctAnswer":"Diamond","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_128","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"Minerals with pearly luster typically have what type of cleavage?","correctAnswer":"Perfect","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_129","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"Define sectile cleavage/sectility.","correctAnswer":"The mineral can be separated or cut with a knife into thin shavings.","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_130","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Hard","question":"How many crystal systems and crystal point groups (classes) are there?","correctAnswer":"There are 6 or 7 crystal systems, and 32 crystal classes.","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_132","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"Transformation twinning is formed (before/during/after) cooling.","options":["Before","During","After"],"correctAnswer":"During","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_133","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"Gliding twinning is formed (before/during/after) cooling.","options":["Before","During","After"],"correctAnswer":"After","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_134","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"A mineral can have a splendent luster and be transparent/translucent.","options":["True","False"],"correctAnswer":"False","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_135","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"Give one example of reconstructive polymorphs.","correctAnswer":"Graphite and diamond","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_136","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"Give one example of displacement polymorphs.","correctAnswer":"Alpha/beta quartz","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_137","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"Give one example of order-disorder polymorphs.","correctAnswer":"Sanidine -> orthoclase -> microcline","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_138","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Hard","question":"The solid solution between albite and anorthite is an example of what type of substitution?","options":["Simple","Limited","Coupled"],"correctAnswer":"Coupled","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_139","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Hard","question":"What ion(s) in albite are being replaced in anorthite?","correctAnswer":"Na+ and Si4+","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_140","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"The principle that sediments will extend laterally to the physical margins of the basin it’s filling is known as:","correctAnswer":"Steno’s Law of Lateral Continuity","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_141","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"Within a Bouma sequence, pebbles are typically found in which layer?","options":["A","B","C","D","E"],"correctAnswer":"A","year":2023,"tournament":"SSSS"},
  {"id":"q_rm_2023_ssss_142","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Medium","question":"Within a Bouma sequence, what is the last layer where saltated sediments are deposited? (After this layer, sediments are located within the suspended load).","options":["A","B","C","D","E"],"correctAnswer":"C","year":2023,"tournament":"SSSS"}
,
  {"id":"q_rm_2022_ssss2_1","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Chalk famously makes up the White Cliffs of Dover in England. During which geologic period were these chalk cliffs deposited?","correctAnswer":"(Late) Cretaceous","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_2","event":"Rocks and Minerals","subtopic":"Earth History & Environments","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain the difference between the typical environments of formation of Chalk and Diatomite.","correctAnswer":"Chalk is formed in a deep marine environment, while diatomite can form in either marine or freshwater environments.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_3","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following are common uses of Talc?","options":["Pigment, Sinks, Paper, Insecticide, Antiperspirant","Glass, Concrete, Steel, Fertilizers","Batteries, Wiring, Electronics","Food additive, Water purification"],"correctAnswer":"Pigment, Sinks, Paper, Insecticide, Antiperspirant","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_4","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Give the chemical formulas for Kaolinite and Talc.","correctAnswer":"Kaolinite: Al2O3 2SiO2·2H2O; Talc: Mg3Si4O10(OH)2","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_5","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"MCQ","difficulty":"Medium","question":"Kaolinite is typically:","options":["Paramagnetic","Diamagnetic","Ferromagnetic","Ferrimagnetic"],"correctAnswer":"Paramagnetic","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_6","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the name of the fine white powder that Diatomite crumbles into?","correctAnswer":"Diatomaceous earth","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_7","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Hard","question":"Kaolinite forms a group/series with what other mineral (that is not on the official list)?","correctAnswer":"Serpentine","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_8","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Easy","question":"Name one of the marine organisms that chalk typically forms from.","correctAnswer":"Coccolithophores (or foraminifera)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_9","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Talc is a primary component of soapstone. Explain how soapstone forms.","correctAnswer":"Metamorphosis; rocks with talc are metamorphosed by hydrothermal alteration.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_10","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"List Halite, Ulexite, Calcite, and Fluorite in order of their Mohs hardnesses (lowest to highest).","correctAnswer":"Halite (2.5), Ulexite (2.5), Calcite (3), Fluorite (4)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_11","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Easy","question":"Which mineral(s) define the Mohs Hardness Scale values of 3 and 4?","correctAnswer":"Calcite (3) and Fluorite (4)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_12","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"Of Halite, Ulexite, Calcite, and Fluorite, which could be scratched by a copper penny? A steel nail?","correctAnswer":"Copper penny: Halite, Ulexite, Calcite; Steel nail: all.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_13","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Calcite exhibits what distinctive optical property? Explain how it works.","correctAnswer":"Birefringence/double refraction: the crystal separates incoming light into two linear polarizations.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_14","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Which mineral on the Science Olympiad list is known chemically as sodium chloride?","correctAnswer":"Halite","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_15","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"What happens when dilute HCl is poured on Calcite?","correctAnswer":"It effervesces (fizzes).","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_16","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Describe how Halite is formed in nature.","correctAnswer":"Forms in arid climates; seawater or salty lake water evaporates and leaves halite behind.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_17","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Fluorite is the state mineral/gem of which US state?","correctAnswer":"Illinois","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_18","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the crystal system of Halite?","correctAnswer":"Isometric (Cubic)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_19","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Calcite is a polymorph of what other mineral on the official list? Which of the two is more stable on the surface of the Earth?","correctAnswer":"Aragonite; calcite is more stable.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_20","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"What is a nickname for Ulexite? Why is it called this?","correctAnswer":"TV stone; it has fiber optic properties that transmit images through the crystal.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_21","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Hard","question":"List the specific gravities for Tremolite, Actinolite, and Galena.","correctAnswer":"Tremolite: ~2.99-3.03; Actinolite: ~3.00; Galena: 7.4-7.6","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_22","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Easy","question":"Define specific gravity.","correctAnswer":"Ratio of a mineral’s mass to the mass of an equal volume of water.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_23","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Tremolite and Actinolite are very similar, except Actinolite has more of what metal?","correctAnswer":"Iron","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_24","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Give the chemical formula for Galena.","correctAnswer":"PbS","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_25","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Which minerals on the SO list are known to cause cancer when inhaled?","correctAnswer":"Tremolite and Actinolite (Asbestos varieties)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_26","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"MCQ","difficulty":"Hard","question":"Which of the following environments can Actinolite form in?","options":["Hydrothermal veins, Contact metamorphism regions","Fast-moving waters, Hot springs","Subduction zones, Deep marine trenches","Evaporite basins, Salt lakes"],"correctAnswer":"Hydrothermal veins, Contact metamorphism regions","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_27","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"MCQ","difficulty":"Easy","question":"True or False: Galena is the primary ore of lead.","options":["True","False"],"correctAnswer":"True","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_28","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"When Galena is tarnished, what color is it?","correctAnswer":"Dull gray or black","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_29","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Medium","question":"What type of silicate are Tremolite and Actinolite?","correctAnswer":"Inosilicate (double-chain silicate)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_30","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Give the chemical formulas for Quartz (including varieties like Amethyst, Citrine) and Opal.","correctAnswer":"Quartz: SiO2; Opal: SiO2·nH2O","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_31","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Aventurine (a variety of quartz) often contains glittering pieces which are which mineral (group)?","correctAnswer":"Mica","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_32","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe the origin of the name \"Amethyst\".","correctAnswer":"From Greek \"amethystos\", meaning \"not drunk\", because it was thought to prevent intoxication.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_33","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the tenacity of Smoky Quartz?","correctAnswer":"Brittle","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_34","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"MCQ","difficulty":"Medium","question":"True or False: Citrine was once used as flat panes in sunglasses in 12th century China.","options":["True","False"],"correctAnswer":"False (Smoky Quartz was used)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_35","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the Mohs hardness of Quartz?","correctAnswer":"7","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_36","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"What optical property does Opal famously exhibit?","correctAnswer":"Iridescence (Play of color / Opalescence)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_37","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the natural process that causes Smoky Quartz to be a brownish-black color?","correctAnswer":"Natural irradiation (of aluminum impurities)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_38","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Citrine’s yellow-orange color comes from traces of what metal?","correctAnswer":"Iron","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_39","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"A quartz crystal exhibiting uneven distribution of color (like bands of purple in amethyst) is showing what phenomenon?","correctAnswer":"Color zoning","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_40","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Easy","question":"The continuous and discontinuous series of mineral crystallization from magma is called what?","correctAnswer":"Bowen's Reaction Series","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_41","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Medium","question":"Which branch of Bowen's Reaction Series do Olivine, Pyroxene, and Biotite belong to?","correctAnswer":"Discontinuous series","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_42","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Medium","question":"Order the following from crystallization at the warmest to coolest temperatures: Biotite, Olivine, Orthoclase/Microcline, Pyroxene.","correctAnswer":"Olivine, Pyroxene, Biotite, Orthoclase/Microcline","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_43","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Medium","question":"Minerals formed at warmer temperatures are typically found in igneous rocks that are more _____?","correctAnswer":"Mafic","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_44","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain why mafic minerals like olivine and pyroxene crystallize before felsic minerals like quartz.","correctAnswer":"Mafic minerals crystallize at warmer (higher) temperatures than felsic minerals.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_45","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Orthoclase is a polymorph of what other mineral on the Science Olympiad list?","correctAnswer":"Microcline","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_46","event":"Rocks and Minerals","subtopic":"Phase Diagrams & Bowen's Reaction Series","division":"C","type":"FRQ","difficulty":"Medium","question":"According to Goldich Dissolution Series, minerals formed at cooler temperatures are (more/less) resistant to chemical weathering.","correctAnswer":"More resistant","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_47","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"What is the habit of Biotite?","correctAnswer":"Micaceous (foliated/flaky)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_48","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"FRQ","difficulty":"Hard","question":"Give the silicate structure type for Orthoclase, Biotite, Augite, and Olivine.","correctAnswer":"Orthoclase: Tectosilicate; Biotite: Phyllosilicate; Augite: Inosilicate; Olivine: Nesosilicate","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_49","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"List the common protoliths for Quartzite, Amphibolite, Slate, and Serpentinite.","correctAnswer":"Quartzite: Quartz sandstone; Amphibolite: Gabbro/Basalt; Slate: Shale; Serpentinite: Peridotite","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_50","event":"Rocks and Minerals","subtopic":"Earth History & Environments","division":"C","type":"FRQ","difficulty":"Medium","question":"What type of metamorphism leads to the formation of Slate?","correctAnswer":"Regional metamorphism","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_51","event":"Rocks and Minerals","subtopic":"Earth History & Environments","division":"C","type":"FRQ","difficulty":"Medium","question":"What temperature range does Amphibolite facies typically form in?","correctAnswer":"500 to 850°C","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_52","event":"Rocks and Minerals","subtopic":"Earth History & Environments","division":"C","type":"FRQ","difficulty":"Medium","question":"List and describe two types of metamorphism.","correctAnswer":"Contact: from contact with an igneous intrusion; Regional: large volumes of rock altered by pressure/heat when continents collide; Hydrothermal: alteration by hot fluids.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_53","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"What type of magma (felsic, mafic, etc.) would Serpentinite’s protolith form from?","correctAnswer":"Ultramafic","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_54","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"What minerals/mineral groups is Amphibolite made of?","correctAnswer":"Mostly hornblende (amphiboles) and plagioclase, with quartz, epidote, etc.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_55","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Of Pumice, Diorite, Granite, and Gabbro, which are considered felsic?","correctAnswer":"Pumice and Granite","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_56","event":"Rocks and Minerals","subtopic":"Earth History & Environments","division":"C","type":"MCQ","difficulty":"Medium","question":"What environment is Gabbro formed in?","options":["Lava flows on Earth's surface","Plutons (deep underground)","The mantle","Pyroclastic flow from volcanic eruptions"],"correctAnswer":"Plutons (deep underground)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_57","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Easy","question":"Describe the primary minerals that compose Granite.","correctAnswer":"Mostly quartz, potassium feldspar, and plagioclase feldspar.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_58","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain how Pumice is formed.","correctAnswer":"It erupts from volcanoes. Gas bubbles trapped in the rock during the rapid cooling of a gas-rich frothy magma form vesicles.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_59","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"What type of magma does Diorite form from?","correctAnswer":"Intermediate","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_60","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the extrusive equivalent of Granite?","correctAnswer":"Rhyolite","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_61","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the extrusive equivalent of Diorite?","correctAnswer":"Andesite","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_62","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"MCQ","difficulty":"Easy","question":"True or False: Obsidian is mafic.","options":["True","False"],"correctAnswer":"False (it is felsic)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_63","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Hard","question":"List the following index minerals in order of lowest metamorphic grade to highest: Kyanite, Staurolite, Garnet, Muscovite.","correctAnswer":"Muscovite, Garnet, Staurolite, Kyanite","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_64","event":"Rocks and Minerals","subtopic":"General Geology & Crystallography","division":"C","type":"MCQ","difficulty":"Easy","question":"True or False: Almandine, Muscovite, Kyanite, and Staurolite are all silicates.","options":["True","False"],"correctAnswer":"True","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_65","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Almandine (Garnet) commonly shows what type of crystal habit?","correctAnswer":"Dodecahedral","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_66","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Staurolite famously displays what type of twinning?","correctAnswer":"Penetration twinning (cruciform/cross-shaped)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_67","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"What historical Russian material is Muscovite named for?","correctAnswer":"Muscovy glass","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_68","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Give the chemical formula for Kyanite.","correctAnswer":"Al2SiO5","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_69","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the typical crystal habit of Kyanite?","correctAnswer":"Bladed","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_70","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Gold is often found in hydrothermal veins associated with what other mineral on the list?","correctAnswer":"Quartz","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_71","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Which two minerals on the SO list are polymorphs consisting of pure carbon?","correctAnswer":"Graphite and Diamond","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_72","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"How would you describe the habit of native Gold?","correctAnswer":"Dendritic (or wire-like, massive)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_73","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"MCQ","difficulty":"Easy","question":"True or False: Graphite is commonly used as a dry lubricant.","options":["True","False"],"correctAnswer":"True","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_74","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Which mineral has the highest electrical and thermal conductance of all minerals?","correctAnswer":"Silver","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_75","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe how a gold nugget forms.","correctAnswer":"A chunk of gold breaks off its mother rock before it gets carried downstream by a river, which rolls and rounds it into its distinctive shape (placer deposit).","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_76","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe the streak of Silver.","correctAnswer":"Silver-white to light gray, shiny.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_77","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"What is Sphalerite an ore of?","correctAnswer":"Zinc","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_78","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"What is Rutile an ore of?","correctAnswer":"Titanium","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_79","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"What is Celestite an ore of?","correctAnswer":"Strontium","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_80","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe the habit of Rutile.","correctAnswer":"Acicular (needle-like)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_81","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe the habit of Celestite.","correctAnswer":"Prismatic (or tabular)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_82","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Easy","question":"Describe the habit of Galena.","correctAnswer":"Cubic","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_83","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Common impurities of what element are found in Sphalerite that cause it to be dark and opaque (Black Jack)?","correctAnswer":"Iron","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_84","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Minerals)","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe the color of the pure form of Celestite.","correctAnswer":"Colorless (though commonly light blue)","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_85","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the type of sedimentary rock (clastic, biochemical, or chemical) for: Quartz sandstone, Conglomerate, Oolitic limestone, and Shale.","correctAnswer":"Quartz sandstone: clastic; Conglomerate: clastic; Oolitic limestone: biochemical (or chemical); Shale: clastic.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_86","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Easy","question":"What are the spherical grains of Oolitic limestone known as?","correctAnswer":"Ooids","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_87","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain why Quartz sandstone has grains so much smaller than Conglomerate.","correctAnswer":"The minerals forming the grains were eroded and transported further/longer in sandstone than in conglomerate, sorting and rounding them to a smaller size.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_88","event":"Rocks and Minerals","subtopic":"Earth History & Environments","division":"C","type":"FRQ","difficulty":"Medium","question":"What type of environment would Conglomerate typically form in?","correctAnswer":"Stream/river with a fast current (or alluvial fan).","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_89","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"What are the thin, fissile layers of Shale known as?","correctAnswer":"Laminae","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_90","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"What mineral would be responsible if a Shale was brown or yellow-colored?","correctAnswer":"Goethite/limonite or iron hydroxide","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_91","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Medium","question":"Explain why mature Quartz Sandstone is made of almost pure quartz, and not olivine or labradorite.","correctAnswer":"All the other minerals weather more easily (chemical weathering), so only highly resistant quartz remains to become rock. Olivine and Ca-plagioclase weather very rapidly.","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_92","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following are uses of Oolitic limestone?","options":["Building materials, Biofilters in home aquariums","Ore, Insecticide","Cosmetics, Electronics","Abrasive, Jewelry"],"correctAnswer":"Building materials, Biofilters in home aquariums","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_93","event":"Rocks and Minerals","subtopic":"Earth History & Environments","division":"C","type":"FRQ","difficulty":"Medium","question":"Conglomerate has been found on what planet by rovers, indicating that there was once fast-moving water?","correctAnswer":"Mars","year":2022,"tournament":"SSSS"},
  {"id":"q_rm_2022_ssss2_94","event":"Rocks and Minerals","subtopic":"Specimen Identification & Properties (Rocks)","division":"C","type":"FRQ","difficulty":"Easy","question":"What type of rock would a Conglomerate be if it had angular clasts instead of rounded ones?","correctAnswer":"Breccia","year":2022,"tournament":"SSSS"}
,
  {"id":"q_wq_2023_blair_1","event":"Water Quality","subtopic":"Marine and Estuary Ecology","division":"C","type":"FRQ","difficulty":"Medium","question":"Describe and explain the purpose of coagulation and flocculation in water treatment.","correctAnswer":"Coagulation and flocculation is the process of clumping together sediments and other suspended solids from the water to remove them with greater ease. The particles first coagulate, colliding with the coagulant, and then are flocculated, where the particle size grows. This proceeds to sedimentation, where the flocs settle to the ground and are removed.","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_2","event":"Water Quality","subtopic":"Marine and Estuary Ecology","division":"C","type":"FRQ","difficulty":"Medium","question":"Define nutrient cycling and explain why it is important to the productivity of an ecosystem.","correctAnswer":"Nutrient cycling is the passing of nutrients among different components of an ecosystem and how they are cycled and reutilized. Keeping track of it is important to understanding how an ecosystem responds to alteration of the biotic or physical parameters. To maintain a high level of productivity, there must be a high amount of nutrient conservation and cycling to sustain the flow of energy.","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_3","event":"Water Quality","subtopic":"Marine and Estuary Ecology","division":"C","type":"MCQ","difficulty":"Medium","question":"Which of the following problems are caused by sedimentation pollution?","options":["Lack of sunlight","Lowered fish resistance to disease","Stripping nutrients from the river","Both Lack of sunlight and Lowered fish resistance to disease"],"correctAnswer":"Both Lack of sunlight and Lowered fish resistance to disease","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_4","event":"Water Quality","subtopic":"Marine and Estuary Ecology","division":"C","type":"FRQ","difficulty":"Hard","question":"Explain why the salinity of the Chesapeake Bay changes between spring and fall, and how this affects the spawning of Striped Bass.","correctAnswer":"In the spring, higher river flows overtake the ocean’s influence and the salinity is lower for half the Bay. In the fall, river flow diminishes and the ocean overtakes the rivers, increasing salinity. Striped bass lay eggs in fresh or brackish water and travel up the rivers to spawn, so they mate in the spring where there is more freshwater.","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_5","event":"Water Quality","subtopic":"Marine and Estuary Ecology","division":"C","type":"FRQ","difficulty":"Medium","question":"Why is global warming considered a major factor in coral death? What is the second greatest threat to coral?","correctAnswer":"Global warming changes seawater temperatures from the ideal range corals prefer, causing them to die from stress (bleaching). The second greatest threat is human pollutants of phosphorus and nitrogen, which cause algae blooms and inhibit coral phosphorus absorption.","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_6","event":"Water Quality","subtopic":"Coral Reef Macroflora and Fauna","division":"C","type":"FRQ","difficulty":"Easy","question":"Identify the brightly colored reef fish that feeds on epilithic algae and has a hard beak used to scrape algae off of coral, preventing the coral from being overgrown.","correctAnswer":"Parrotfish","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_7","event":"Water Quality","subtopic":"Coral Reef Macroflora and Fauna","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the large marine mollusk that preys on other mollusks and starfish, playing a critical role in the reef by killing the Crown-of-Thorns starfish.","correctAnswer":"Giant Triton (Triton snail)","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_8","event":"Water Quality","subtopic":"Coral Reef Macroflora and Fauna","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the large reef fish that primarily feeds on invertebrates and fish, and reproduces in large mating groups where males fertilize eggs released into the water column by females.","correctAnswer":"Humphead wrasse","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_9","event":"Water Quality","subtopic":"Coral Reef Macroflora and Fauna","division":"C","type":"FRQ","difficulty":"Medium","question":"Identify the Atlantic reef fish that breeds at specific spawning areas in groups of up to tens of thousands, releasing eggs and sperm into the water column above deep reefs at the same time.","correctAnswer":"Nassau Grouper","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_10","event":"Water Quality","subtopic":"Coral Reef Macroflora and Fauna","division":"C","type":"FRQ","difficulty":"Medium","question":"Where do carnivorous sponges tend to exist in the ocean?","correctAnswer":"Extremely deep locations where there is a lack of light and plankton.","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_11","event":"Water Quality","subtopic":"Coral Reef Macroflora and Fauna","division":"C","type":"FRQ","difficulty":"Medium","question":"Why are giant clams often used as a measure of water quality in the ocean?","correctAnswer":"Giant clams are extremely sensitive to acidity and temperature of water. Their presence means the pH and temperature of the water are at good levels for the ecosystem, as they die when levels are less than perfect.","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_12","event":"Water Quality","subtopic":"Coral Reef Macroflora and Fauna","division":"C","type":"FRQ","difficulty":"Medium","question":"Why is the diet of the parrotfish different from other herbivorous fish in the reef and why is it important?","correctAnswer":"Parrotfish have a harder beak and can eat harder, calciferous algae which many other species avoid. Their presence helps keep algae levels of the reef at healthy levels.","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_13","event":"Water Quality","subtopic":"Coral Reef Macroflora and Fauna","division":"C","type":"FRQ","difficulty":"Hard","question":"How can sea urchins be used as indicators of reef health? How does their population affect the reef in larger or smaller numbers?","correctAnswer":"A reasonable number indicates a healthy reef. Too many, and they eliminate all algae, leaving no food for fish and mollusks and destroying the reef. Too few, and there is uncontrolled algae growth and lack of space for slow growing corals to compete.","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_14","event":"Water Quality","subtopic":"Coral Reef Macroflora and Fauna","division":"C","type":"FRQ","difficulty":"Medium","question":"What would an abundance of fleshy macroalgae indicate about the health of a coral reef?","correctAnswer":"It could indicate decreased grazing pressure from fish, mollusks, and urchins, or an increase of nutrient availability (e.g., from runoff).","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_15","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"FRQ","difficulty":"Hard","question":"Why is aragonite saturation often used as an indicator of ocean acidification?","correctAnswer":"Aragonite is a crystalline form of calcium carbonate that is more readily soluble than calcite and used in building the shells of many crustaceans/mollusks. Testing its saturation quantifies calcium carbonate availability. Lower values indicate less free carbonate and more carbonic acid, making it harder for organisms to build shells.","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_16","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"Water is tested at a location and the salinity is measured to be 20 ppt. What type of water was this sample taken from?","correctAnswer":"Brackish water (e.g. an estuary like the Chesapeake Bay)","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_17","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"MCQ","difficulty":"Medium","question":"Which testing method is commonly used to measure Dissolved Oxygen?","options":["Spectrophotometry","CTD Instrument","(RDO) Luminescence Quenching","Membrane Filter Method"],"correctAnswer":"(RDO) Luminescence Quenching","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_18","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"MCQ","difficulty":"Medium","question":"Which testing method is commonly used to measure pH?","options":["Potentiometry","CTD Instrument","Ascorbic Acid Method","Spectrophotometry"],"correctAnswer":"Potentiometry","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_19","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"MCQ","difficulty":"Medium","question":"Which testing method is commonly used to measure Nitrates?","options":["Spectrophotometry","CTD Instrument","(RDO) Luminescence Quenching","Ascorbic Acid Method"],"correctAnswer":"Spectrophotometry","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_20","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"MCQ","difficulty":"Medium","question":"Which testing method is commonly used to measure Salinity?","options":["Potentiometry","CTD Instrument","Membrane Filter Method","Spectrophotometry"],"correctAnswer":"CTD Instrument","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_21","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"MCQ","difficulty":"Medium","question":"Which testing method is commonly used to measure Phosphates?","options":["Ascorbic Acid Method","CTD Instrument","(RDO) Luminescence Quenching","Membrane Filter Method"],"correctAnswer":"Ascorbic Acid Method","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_22","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"MCQ","difficulty":"Medium","question":"Which testing method is commonly used to measure Fecal Coliform?","options":["Spectrophotometry","Potentiometry","Membrane Filter Method","Ascorbic Acid Method"],"correctAnswer":"Membrane Filter Method","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_23","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"FRQ","difficulty":"Easy","question":"Which two units are most commonly used to measure turbidity?","correctAnswer":"Nephelometric turbidity units (NTU) and Jackson turbidity units (JTU)","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_24","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the measurement of \"total solids\" composed of in water analysis? Give an example of each component.","correctAnswer":"Total solids are composed of total dissolved solids (e.g., calcium, chlorides, nitrate, phosphorus) and total suspended solids (e.g., silt, clay particles, plankton, algae).","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_25","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"MCQ","difficulty":"Medium","question":"If there is an abnormally high concentration of nitrates in a water body, which of the following could occur?","options":["Fish death and Algal bloom","Purple water and Increased biodiversity","Increased biodiversity and Algal bloom","Purple water and Fish death"],"correctAnswer":"Fish death and Algal bloom","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_26","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"If the shells of crustaceans are extremely thin and underdeveloped in a region, what problem might the water have?","correctAnswer":"High acidity caused by large amounts of carbon dioxide forming carbonic acid (ocean acidification).","year":2023,"tournament":"Montgomery Blair"},
  {"id":"q_wq_2023_blair_27","event":"Water Quality","subtopic":"Water Monitoring and Analysis","division":"C","type":"FRQ","difficulty":"Medium","question":"What would an excess amount of phosphates in water cause?","correctAnswer":"Cloudy water, low oxygen, massive growth of algae, death of other organisms from lack of dissolved oxygen, and eutrophication.","year":2023,"tournament":"Montgomery Blair"}
,
  {"id":"q_astro_2024_ssss_1","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Medium","question":"If the parallax of a star is 0.05\", then the distance to the star is:","options":["2 parsecs","5 parsecs","20 parsecs","50 parsecs","250 parsecs"],"correctAnswer":"20 parsecs","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_2","event":"Astronomy","subtopic":"General Astronomy & Scale","division":"C","type":"MCQ","difficulty":"Medium","question":"If we shrink the solar system such that the sun has a diameter of 1 cm, then Earth's diameter is:","options":["0.0001 cm","0.001 cm","0.01 cm","0.1 cm","1 cm"],"correctAnswer":"0.01 cm","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_3","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Easy","question":"A star barely visible with the naked eye has apparent magnitude:","options":["-26.7","0","6","15","22","30"],"correctAnswer":"6","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_4","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Easy","question":"We can determine a star's luminosity by knowing its:","options":["Radius and distance","Apparent brightness and radius","Apparent brightness and distance","Color and surface temperature","Distance and RA and Decl."],"correctAnswer":"Apparent brightness and distance","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_5","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Medium","question":"An emission nebula radiates in the optical predominantly at:","options":["656 nm","Green wavelengths","410 nm","Blue wavelengths","120 nm"],"correctAnswer":"656 nm","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_6","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Easy","question":"A reflection nebula appears:","options":["Bluish","Reddish","Dusty gray","Yellowish","Whitish"],"correctAnswer":"Bluish","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_7","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Medium","question":"Main-sequence stars generally have masses between:","options":["0.4 and ~ 40 M_sun","0.8 and ~ 80 M_sun","0.1 and ~ 10 M_sun","0.8 and ~ 10 M_sun","0.08 and ~ 40 M_sun"],"correctAnswer":"0.08 and ~ 40 M_sun","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_8","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Hard","question":"A star with M=8M_sun spends on the main sequence approximately:","options":["5 x 10^10 yr","5 x 10^9 yr","5 x 10^8 yr","5 x 10^7 yr","5 x 10^6 yr"],"correctAnswer":"5 x 10^7 yr","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_9","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Medium","question":"Fusion of helium atoms into other compounds starts at a temperature of:","options":["10^6 K","10^7 K","10^8 K","5 x 10^8 K","5 x 10^9 K"],"correctAnswer":"10^8 K","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_10","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"MCQ","difficulty":"Medium","question":"The Chandrasekhar limit is:","options":["Escape velocity = speed of light","2,300 rotations per second","Density limit of electron degenerate","M = 1.4 M_sun","M = 140 M_sun"],"correctAnswer":"M = 1.4 M_sun","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_11","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"MCQ","difficulty":"Medium","question":"Neutron stars are created in a:","options":["Thermonuclear explosion of a white dwarf when it exceeds the Chandrasekhar limit","Thermonuclear explosion of two colliding white dwarfs","Core collapse of a massive star with up to ~ 25 M_sun","Core collapse of star with M < M_sun","Planetary nebula as the compact central remnant"],"correctAnswer":"Core collapse of a massive star with up to ~ 25 M_sun","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_12","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"MCQ","difficulty":"Medium","question":"The fastest observed neutron stars spin at an approximate rate of:","options":["1000 rotations per second","700 rotations per second","500 rotations per second","150 rotations per second","70 rotations per second"],"correctAnswer":"700 rotations per second","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_13","event":"Astronomy","subtopic":"Binary Systems & Exoplanets","division":"C","type":"MCQ","difficulty":"Medium","question":"A Roche Lobe for a binary star system is defined as:","options":["A teardrop-shaped orbit of a star in a binary system","A volume surrounding a star, inside which the gas is gravitational bound to that star","The boundary of jet emission in a binary system","The smallest distance where matter from the other star can be held together by gravitational forces","An orbit where the gravitational forces of the two stars cancel out"],"correctAnswer":"A volume surrounding a star, inside which the gas is gravitational bound to that star","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_14","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Easy","question":"Which of the following is the closest approximated value of Hubble constant?","options":["50 Mpc/km/s","50 km/s/MPc","70 km^-1 s^-1 Mpc^-1","70 Mpc/km/s","70 km s^-1 Mpc^-1"],"correctAnswer":"70 km s^-1 Mpc^-1","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_15","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Easy","question":"The Cosmic Microwave Background (CMB) is radiation from a blackbody of temperature:","options":["3000 K","2700 K","270 K","30 K","2.7 K"],"correctAnswer":"2.7 K","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_16","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Medium","question":"The CMB originated from a time after the big bang of:","options":["10^-34 sec","3 sec","2.7 yr","380,000 yr","1.7 Myr"],"correctAnswer":"380,000 yr","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_17","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Medium","question":"A SN-Ia results from:","options":["Core collapse of a massive star","Core collapse of a massive star with hydrogen stripped off","Core collapse of a white dwarf","Core collapse of a massive star with hydrogen & Helium stripped off","Thermonuclear explosion of a white dwarf"],"correctAnswer":"Thermonuclear explosion of a white dwarf","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_18","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Medium","question":"Type-Ic supernovae are usually dimmer than Type-Ia because?","options":["Type Ic forms from neutron stars","Type Ic progenitors has no hydrogen or helium","Type Ic progenitors have binary companions","Type Ic produces less Nickel-56"],"correctAnswer":"Type Ic produces less Nickel-56","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_19","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Hard","question":"A brown dwarf is powered by:","options":["Thermos-nuclear reactions, Kelvin-Helmholtz mechanism","Kelvin-Helmholtz mechanism, Release of gravitational binding energy","Jean's instability, Release of gravitational binding energy","Thermos-nuclear reactions, Jean's instability"],"correctAnswer":"Kelvin-Helmholtz mechanism, Release of gravitational binding energy","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_20","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Medium","question":"What phenomena would you expect near interstellar medium glowing in H-alpha?","options":["Young, massive stars","A supernova remnant","Both young massive stars and supernovae remnants","A dense molecular cloud"],"correctAnswer":"Both young massive stars and supernovae remnants","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_21","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Medium","question":"For the interstellar medium in the Milky Way, which of the following has the most contribution from cold molecular clouds?","options":["Mass","Volume","21-cm emission","Mass and volume"],"correctAnswer":"Mass","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_22","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Medium","question":"The dust grain in the intergalactic medium has an average size of:","options":["10^-10 m","10^-9 m","10^-7 m","10^-3 m"],"correctAnswer":"10^-7 m","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_23","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Medium","question":"Typical molecular gas in intergalactic medium has density and temperature of:","options":["10^-21 g/cm^3, 2.74 K","10^-19 g/cm^3, 10 K","10^-17 g/cm^3, 50 K","10^-16 g/cm^3, 100 K"],"correctAnswer":"10^-19 g/cm^3, 10 K","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_24","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Medium","question":"H-I is observed through a line in spectrum at:","options":["21 cm, 2420 GHz","21 cm, 2420 MHz","21 cm, 1420 GHz","21 cm, 1420 MHz","21 mm, 142 GHz"],"correctAnswer":"21 cm, 1420 GHz","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_25","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Easy","question":"The radio radiation source from the very center of the Milky Way is called:","options":["Crab nebula","Fornax A1","Ophiuchus","Betelguese","SgrA*"],"correctAnswer":"SgrA*","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_26","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Medium","question":"The radio radiation from the Galactic center is:","options":["Synchrotron radiation","Thermal radiation","X-ray radiation","Bremsstrahlung","Cyclotron radiation"],"correctAnswer":"Synchrotron radiation","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_27","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Medium","question":"The rotation speed of gas at a distance of 15 kpc from the galactic center:","options":["500 km/s","250 km/s","150 km/s","100 km/s","50 km/s"],"correctAnswer":"250 km/s","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_28","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"MCQ","difficulty":"Hard","question":"Assume we monitor spectra of a distant molecular cloud in the galactic plane, along a line of sight at 30 deg away from the line from earth to the galactic center. Which location is likely to show the highest radial velocity from their Doppler shift?","options":["4 kpc from earth","6.9 kpc from earth","8 kpc from earth","10.8 kpc from earth","13.8 kpc from earth"],"correctAnswer":"6.9 kpc from earth","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_29","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"MCQ","difficulty":"Hard","question":"Which of the following is true about blackholes (BH)? (Select all that apply)","options":["Most common BH mass is 5-15 M_sun and Schwarzchild BH is non-rotating","Most likely binary star system to form BH has total mass M > 30M_sun","Hawking Radiation (evaporation) is negligible for BH of M > 1 M_sun"],"correctAnswer":"Most common BH mass is 5-15 M_sun and Schwarzchild BH is non-rotating","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_30","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"MCQ","difficulty":"Medium","question":"The escape speed at the event horizon of a black hole is:","options":["Infinite","Not well defined","300,000 km/s","10,000 km/s","Proportional to the black hole mass"],"correctAnswer":"300,000 km/s","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_31","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"MCQ","difficulty":"Medium","question":"Early gravitational wave observations has confirmed a gap in the mass distribution of black holes that was predicted by the physical mechanism of massive star death. This gap is between:","options":["0.5-1 M_sun","2-3 M_sun","3-5 M_sun","30-50 M_sun","50-130 M_sun"],"correctAnswer":"3-5 M_sun","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_32","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"MCQ","difficulty":"Hard","question":"Gravitational waves observed by LIGO are mainly those emitted by black holes and binary neutron star mergers. What frequency from below are within LIGO detection range?","options":["500 Hz, 100 Hz, 50 Hz","5 Hz, 0.5 Hz","500 Hz, 5 Hz","100 Hz, 5 Hz"],"correctAnswer":"500 Hz, 100 Hz, 50 Hz","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_33","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"MCQ","difficulty":"Medium","question":"The next generation, space-based interferometer like LISA can detect binary supermassive black-hole mergers. Which wave period from below are within LISA detection range?","options":["Minutes, Hours","Days, Years","Minutes, Years","Hours, Days"],"correctAnswer":"Minutes, Hours","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_34","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Medium","question":"Two gas clouds are just barely able to start collapsing; one is 10 pc in diameter, and the other is 2 pc in diameter. What is true about their properties, if they are the same temperature?","options":["The first cloud is less dense than the second","The first cloud is more dense than the second","The first cloud has less mass than the second","The first cloud has a longer free-fall time than the second","The first cloud is less dense and has a longer free-fall time than the second"],"correctAnswer":"The first cloud is less dense and has a longer free-fall time than the second","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_35","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"MCQ","difficulty":"Hard","question":"Estimate the luminosity of a 1 solar mass proto-stellar cloud, which collapses from an initial radius of 10^3 AU down to a Solar radius, over a timescale of 40 million years by radiation of its gravitational potential energy, in units of the present solar luminosity:","options":["0.1","0.5","3","20","1000"],"correctAnswer":"0.5","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_36","event":"Astronomy","subtopic":"Binary Systems & Exoplanets","division":"C","type":"MCQ","difficulty":"Hard","question":"Starlight passing through the atmosphere of an exoplanet will be filtered by molecules. Which of the following absorption peaks in wavelength are most likely to indicate water signature in the biosphere?","options":["4.5 and 15 \\mu m","5 \\mu m","3 and 7.2 \\mu m","4.5 and 7.8 \\mu m","9.2 and 9.6 \\mu m","5.4 and 6.4 \\mu m"],"correctAnswer":"5.4 and 6.4 \\mu m","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_37","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the main source of energy/luminosity for the Main Sequence, Horizontal Branch, Red Giant Branch, and White Dwarf stages in a HR diagram for a typical open cluster?","correctAnswer":"Main sequence: H -> He in core. Horizontal Branch: He -> C, O in core, and H -> He in shell. Red Giant Branch: H -> He and He -> C, O in shell. White dwarf: No energy generation, luminosity from thermal energy.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_38","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"FRQ","difficulty":"Medium","question":"Why is a molecular cloud (e.g. H2) more likely to form stars than an atomic cloud (e.g. HI)?","correctAnswer":"Because it has both higher density (about 1000/cm3) and lower temperature (about 10K), making it much easier to collapse under gravity.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_39","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"FRQ","difficulty":"Hard","question":"For a molecular cloud with a mass of 75 M_sun and a temperature of 40 K, will it collapse and form stars based on Jean's criteria? How does added angular momentum affect star formation?","correctAnswer":"Yes, it is higher than the Jean's limit. Angular momentum helps hold material together and assists the collapse by forcing materials to fall in one direction (parallel to the rotational axis).","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_40","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"FRQ","difficulty":"Hard","question":"Explain the Hayashi line – How does luminosity drop precipitously? In what condition can protostar temperature remain roughly constant?","correctAnswer":"During star formation, the radius of the protostar reduces, thus reducing luminosity. For low to medium mass stars, surface temperature remains constant (about 3000-4000K) because of higher opacity (convection in outer zone radiates energy away at the surface while center temperature rises).","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_41","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"FRQ","difficulty":"Medium","question":"Define the \"Stationary limit\" and the \"Ergosphere\" of a black hole.","correctAnswer":"Stationary limit: Location in Black hole where space-time is flowing at the speed of light, even if outside event horizon. Ergosphere: A zone beyond the event horizon of a rotating Black hole where it is possible to extract energy and matter from the black hole.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_42","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"FRQ","difficulty":"Medium","question":"What is the Schwarzchild radius of a black hole (in AU), if it has a mass of 4 x 10^6 M_sun?","correctAnswer":"The Schwarzchild radius is about 8.0 AU (R_s ~ 3km * M/M_sun).","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_43","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"FRQ","difficulty":"Hard","question":"Suppose you want to spend 10 days close to the Schwarzchild radius of a black hole to observe, but still be back to earth no more than 50 years in the future when you return. At what minimum distance you need to be from the event horizon (in km)?","correctAnswer":"~360 km (or 300 to 500 km) away from Event horizon. (Time dilation factor of 1826).","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_44","event":"Astronomy","subtopic":"Binary Systems & Exoplanets","division":"C","type":"FRQ","difficulty":"Hard","question":"For an exoplanet RV curve displaying a non-sinusoidal shape, what is the most common cause?","correctAnswer":"Eccentricity of the orbit.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_45","event":"Astronomy","subtopic":"Galaxies & Cosmology","division":"C","type":"FRQ","difficulty":"Medium","question":"How far away is a galaxy with physical size (diameter) of 100,000 light years and angular size of 12 arcminutes? Give your answer in Mly.","correctAnswer":"29 Mly. (Angular size = 57.3 deg * physical-size / distance; 12 arcmin = 0.2 deg)","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_46","event":"Astronomy","subtopic":"General Astronomy & Scale","division":"C","type":"FRQ","difficulty":"Hard","question":"Imagine a planet orbiting a 2-solar-mass star once every 75 Earth days. If the star is 10 light years from Earth, what aperture size would a visible-light telescope (550 nm) have to be to resolve the planet from its parent star? Give your answer in meters.","correctAnswer":"0.96 m (Accept 0.8 to 1.1 meter). Using Kepler's 3rd Law, a = 0.44 AU. Angular size = 6.23 x 10^5 AU. Resolution = 1.22 * lambda / Aperture.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_47","event":"Astronomy","subtopic":"Stellar Evolution & Properties","division":"C","type":"FRQ","difficulty":"Hard","question":"A particular star has a parallax angle of 0.02 arcsec, an apparent brightness of 7 x 10^-9 W/m^2, and its spectrum peaks at 500 nm. Calculate the luminosity and radius of the star in solar units.","correctAnswer":"L = 545 L_sun, R = 23 R_sun. (Distance = 50pc. L = Flux * Area = 2.094 x 10^29 W. Wien's law T = 5800 K. Stefan's Law gives R = 1.6 x 10^10 m).","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_48","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"FRQ","difficulty":"Hard","question":"Consider a binary star with masses M1 and M2 initially in a circular orbit with semi-major axis a. It is observed to have a period of 10 years. The radial velocities of the two stars are 10 km/s and 20 km/s. Calculate mass of the two stars if the inclination of the orbit is 30 deg.","correctAnswer":"M1 = 54.4 M_sun, M2 = 27.2 M_sun.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_49","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"FRQ","difficulty":"Hard","question":"What is the binding energy of the binary system (M1 = 54.4 M_sun, M2 = 27.2 M_sun) after the two stars moved closer to a = 1 AU?","correctAnswer":"-1.32 x 10^42 J.","year":2024,"tournament":"SSSS"},
  {"id":"q_astro_2024_ssss_50","event":"Astronomy","subtopic":"Compact Objects","division":"C","type":"FRQ","difficulty":"Hard","question":"A supernova occurs in star 1 of a binary resulting in an immediate mass loss. If the supernova remnant receives no kick, what is the maximum mass loss that can occur yet still having a bounded binary? Express results as a fraction of combined mass M = M1 + M2.","correctAnswer":"delta M = M / 2. (Half of the total mass).","year":2024,"tournament":"SSSS"}
